        // Print results
        printf("%d\t%d\t\t%.3f\t\t%.3f\t\t%.3f\n", 
               cycle, adc_value, vout, error, duty_cycle);
    }

    printf("\nSimulation completed.\n");

    return 0;
}

#include <stdio.h>
#include <math.h>

#define STEP 0.01
#define DUTY_MIN 0.05
#define DUTY_MAX 0.95

double mppt_perturb_and_observe(double voltage, double current, double *duty_cycle) {
    static double P_old = 0.0;
    static int direction = 1;

    double P_new = voltage * current;

    if (P_new > P_old) {
        direction = direction;
    } else {
        direction = -direction;
    }

    *duty_cycle += direction * STEP;

    if (*duty_cycle < DUTY_MIN) {
        *duty_cycle = DUTY_MIN;
    }
    if (*duty_cycle > DUTY_MAX) {
        *duty_cycle = DUTY_MAX;
    }

    P_old = P_new;

    return *duty_cycle;
}

int main() {
    double duty = 0.5;

    printf("MPPT Perturb and Observe Simulation\n");
    printf("===================================\n");

    for (int i = 0; i < 20; i++) {
        double V = duty * 5.0;
        double I = (10.0 - 2.0 * V);
        double P = V * I;

        printf("V=%.2f, I=%.2f, P=%.2f, D=%.3f\n", V, I, P, duty);

        duty = mppt_perturb_and_observe(V, I, &duty);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

typedef struct {
    float dead_time_us;
    float switching_period_us;
    float compensation_table[101];
} DeadTimeCompensator;

void init_compensator(DeadTimeCompensator *comp, float dead_time_us, float period_us) {
    comp->dead_time_us = dead_time_us;
    comp->switching_period_us = period_us;

    float dead_time_ratio = dead_time_us / period_us;

    for (int i = 0; i <= 100; i++) {
        comp->compensation_table[i] = dead_time_ratio;
    }
}

float apply_compensation(DeadTimeCompensator *comp, float duty_cycle, int current_direction) {
    int index = (int)(duty_cycle * 100 + 0.5);
    if (index < 0) index = 0;
    if (index > 100) index = 100;

    float compensation = comp->compensation_table[index] * current_direction;
    float compensated_duty = duty_cycle + compensation;

    if (compensated_duty < 0.0f) return 0.0f;
    if (compensated_duty > 1.0f) return 1.0f;
    return compensated_duty;
}

int main() {
    DeadTimeCompensator comp;

    init_compensator(&comp, 2.0f, 100.0f);

    float test_cases[][2] = {
        {0.3f, 1},
        {0.8f, -1},
        {0.05f, -1},
        {0.98f, 1}
    };

    for (int i = 0; i < 4; i++) {
        float duty = test_cases[i][0];
        int current_dir = (int)test_cases[i][1];
        float compensated = apply_compensation(&comp, duty, current_dir);
        printf("Duty: %.2f, Current: %d => Compensated: %.4f\n", duty, current_dir, compensated);
    }

    return 0;
}

