#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define SIN_TABLE_SIZE 256
#define PI 3.14159265358979323846

float sin_table[SIN_TABLE_SIZE];

void init_sin_table(void) {
    for (int i = 0; i < SIN_TABLE_SIZE; i++) {
        float angle = 2.0f * PI * i / SIN_TABLE_SIZE;
        sin_table[i] = (sinf(angle) + 1.0f) / 2.0f;
    }
}

float get_sine_value(float phase) {
    float index_float = phase * SIN_TABLE_SIZE / (2.0f * PI);
    int index_int = (int)index_float;
    float fraction = index_float - index_int;

    index_int = index_int % SIN_TABLE_SIZE;
    if (index_int < 0) index_int += SIN_TABLE_SIZE;

    int next_index = (index_int + 1) % SIN_TABLE_SIZE;

    return sin_table[index_int] * (1.0f - fraction) + sin_table[next_index] * fraction;
}

void generate_spwm(uint32_t carrier_freq, uint32_t sine_freq, uint32_t samples) {
    float sample_rate = carrier_freq * 2.0f;
    float sample_period = 1.0f / sample_rate;

    float sine_angular_freq = 2.0f * PI * sine_freq;
    float carrier_angular_freq = 2.0f * PI * carrier_freq;

    printf("SPWM parameters: carrier=%uHz, sine=%uHz, samples=%u\n", 
           carrier_freq, sine_freq, samples);

    for (uint32_t i = 0; i < samples; i++) {
        float t = i * sample_period;

        float sine_phase = fmodf(sine_angular_freq * t, 2.0f * PI);
        float sine_value = get_sine_value(sine_phase);

        float carrier_phase = fmodf(carrier_angular_freq * t, 2.0f * PI);
        float carrier_value = fabsf(carrier_phase / (2.0f * PI) * 2.0f - 1.0f);

        int pwm_state = (sine_value > carrier_value) ? 1 : 0;

        if (i < 10) {
            printf("Sample %3u: sine=%.4f, carrier=%.4f, PWM=%d\n", 
                   i, sine_value, carrier_value, pwm_state);
        }
    }
}

int main(void) {
    init_sin_table();

    printf("Sine table initialized, size=%d\n", SIN_TABLE_SIZE);

    printf("\n=== Test 1 ===\n");
    generate_spwm(10000, 50, 200);

    printf("\n=== Test 2 ===\n");
    generate_spwm(20000, 100, 100);

    return 0;
}

#include <stdio.h>
