double calculate_rms(float samples[], int length) {
    if (length <= 0) {
        return 0.0;
    }

    double sum_squares = 0.0;
    for (int i = 0; i < length; i++) {
        sum_squares += samples[i] * samples[i];
    }

    return sqrt(sum_squares / length);
}

