#include <stdio.h>
#include <string.h>

typedef struct {
    float Kp, Ki, Kd;
    float error[3];
    float output;
    float output_limit_max;
    float output_limit_min;
} PID_Controller;

void PID_Init(PID_Controller *pid, float kp, float ki, float kd, float max, float min) {
    pid->Kp = kp;
    pid->Ki = ki;
    pid->Kd = kd;
    pid->output_limit_max = max;
    pid->output_limit_min = min;
    pid->output = 0.0f;
    memset(pid->error, 0, sizeof(pid->error));
}

float PID_Calculate(PID_Controller *pid, float setpoint, float measured) {
    pid->error[2] = pid->error[1];
    pid->error[1] = pid->error[0];
    pid->error[0] = setpoint - measured;

    float delta_u = pid->Kp * (pid->error[0] - pid->error[1]) +
                   pid->Ki * pid->error[0] +
                   pid->Kd * (pid->error[0] - 2.0f * pid->error[1] + pid->error[2]);

    pid->output += delta_u;

    if (pid->output > pid->output_limit_max) {
        pid->output = pid->output_limit_max;
    }
    if (pid->output < pid->output_limit_min) {
        pid->output = pid->output_limit_min;
    }

    return pid->output;
}

void PID_Reset(PID_Controller *pid) {
    memset(pid->error, 0, sizeof(pid->error));
    pid->output = 0.0f;
}

int main() {
    PID_Controller pid;
    PID_Init(&pid, 1.2f, 0.5f, 0.1f, 10.0f, -10.0f);

    float setpoint = 100.0f;
    float measured_values[] = {80.0f, 85.0f, 92.0f, 96.0f, 99.0f};
    int num_cycles = 5;

    printf("Incremental PID Controller Test\n");
    printf("========================================\n");

    for (int i = 0; i < num_cycles; i++) {
        float measured = measured_values[i];
        float output = PID_Calculate(&pid, setpoint, measured);

        printf("Cycle %d:\n", i + 1);
        printf("  Setpoint: %.2f\n", setpoint);
        printf("  Measured: %.2f\n", measured);
        printf("  Error e(k): %.2f\n", pid.error[0]);
        printf("  PID Output: %.2f\n", output);
        printf("  Error history: e(k)=%.2f, e(k-1)=%.2f, e(k-2)=%.2f\n", 
               pid.error[0], pid.error[1], pid.error[2]);
        printf("----------------------------------------\n");
    }

    printf("\nResetting PID controller...\n");
    PID_Reset(&pid);

    printf("Error array after reset: e(k)=%.2f, e(k-1)=%.2f, e(k-2)=%.2f\n",
           pid.error[0], pid.error[1], pid.error[2]);
    printf("Output after reset: %.2f\n", pid.output);

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <time.h>

#define VIN 12.0
#define TARGET_VOUT 24.0
#define INITIAL_DUTY 0.5
#define DT 0.001
#define NOISE_AMPLITUDE 0.1

typedef struct {
    double Kp;
    double Ki;
    double Kd;
    double integral;
    double prev_error;
} PIDController;

double pid_update(PIDController *pid, double error, double dt) {
    double proportional = pid->Kp * error;

    pid->integral += error * dt;
    double integral = pid->Ki * pid->integral;

    double derivative = pid->Kd * (error - pid->prev_error) / dt;
    pid->prev_error = error;

    return proportional + integral + derivative;
}

double limit_duty(double duty) {
    if (duty < 0.05) return 0.05;
    if (duty > 0.95) return 0.95;
    return duty;
}

double simulate_vout(double duty, double noise) {
    return VIN / (1.0 - duty) + noise;
}

double generate_noise() {
    return ((double)rand() / RAND_MAX * 2.0 - 1.0) * NOISE_AMPLITUDE;
}

int main() {
    srand(time(NULL));

    PIDController pid = {
        .Kp = 0.1,
        .Ki = 0.05,
        .Kd = 0.01,
        .integral = 0.0,
        .prev_error = 0.0
    };

    double duty = INITIAL_DUTY;
    double time = 0.0;

    printf("时间(s)\t当前Vout(V)\t误差(V)\t占空比\n");
    printf("---------------------------------------------\n");

    for (int i = 0; i < 5; i++) {
        double noise = generate_noise();
        double vout = simulate_vout(duty, noise);
        double error = TARGET_VOUT - vout;

        double pid_output = pid_update(&pid, error, DT);
        duty += pid_output;
        duty = limit_duty(duty);

        printf("%.4f\t%.4f\t\t%.4f\t%.4f\n", time, vout, error, duty);

        time += DT;
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

#define VIN 24.0
#define VREF 12.0
#define FSW 100000.0
#define TS (1.0/FSW)
#define L 100e-6
#define C 220e-6
#define R 5.0

#define KP 0.1
#define KI 10.0
#define DUTY_MIN 0.0
#define DUTY_MAX 0.9

double pi_controller(double error, double kp, double ki) {
    static double error_sum = 0.0;
    error_sum += error * TS;
    double output = kp * error + ki * error_sum;
    return output;
}

double buck_model(double vin, double duty, double il_prev, double vc_prev) {
    double vout_prev = vc_prev;
    double il_next = il_prev + (vin * duty - vout_prev) * TS / L;
    double vc_next = vc_prev + (il_prev - vout_prev / R) * TS / C;
    return vc_next;
}

int main() {
    double vout = 0.0;
    double il = 0.0;
    double vc = 0.0;
    double duty = 0.0;

    printf("Buck降压转换器数字PI控制仿真\n");
    printf("参数: Vin=%.1fV, Vref=%.1fV, fsw=%.0fkHz, L=%.1fuH, C=%.0fuF, R=%.1fΩ\n", 
           VIN, VREF, FSW/1000, L*1e6, C*1e6, R);
    printf("周期  输出电压(V)  占空比   电感电流(A)\n");

    for (int k = 0; k < 1000; k++) {
        double error = VREF - vout;
        double control_signal = pi_controller(error, KP, KI);

        duty = control_signal;
        if (duty < DUTY_MIN) duty = DUTY_MIN;
        if (duty > DUTY_MAX) duty = DUTY_MAX;

        vc = buck_model(VIN, duty, il, vc);
        vout = vc;
        il = il + (VIN * duty - vout) * TS / L;

        if (k % 100 == 0) {
            printf("%4d  %10.3f  %8.4f  %10.3f\n", k, vout, duty, il);
        }
    }

    printf("\n稳态结果:\n");
    printf("最终输出电压: %.3f V\n", vout);
    printf("最终占空比: %.4f\n", duty);
    printf("最终电感电流: %.3f A\n", il);
    printf("期望电压误差: %.3f V\n", VREF - vout);

    return 0;
}

#include <stdio.h>

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float prev_error;
    float output_min;
    float output_max;
} PID_Controller;

void PID_Init(PID_Controller *pid, float Kp, float Ki, float Kd, float min, float max) {
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output_min = min;
    pid->output_max = max;
}

float PID_Update(PID_Controller *pid, float setpoint, float measurement, float dt) {
    float error = setpoint - measurement;

    pid->integral += error * dt;

    float derivative = (error - pid->prev_error) / dt;

    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    if (output < pid->output_min) {
        output = pid->output_min;
    } else if (output > pid->output_max) {
        output = pid->output_max;
    }

    pid->prev_error = error;

    return output;
}

