#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846f
#define SQRT3 1.73205080756887729352f

void clark_transform(float a, float b, float c, float *alpha, float *beta) {
    *alpha = a;
    *beta = (a + 2.0f * b) / SQRT3;
}

void park_transform(float alpha, float beta, float theta, float *d, float *q) {
    float cos_theta = cosf(theta);
    float sin_theta = sinf(theta);
    *d = alpha * cos_theta + beta * sin_theta;
    *q = -alpha * sin_theta + beta * cos_theta;
}

void pll_update(float q, float *theta, float kp, float ki, float dt) {
    static float integral = 0.0f;
    integral += q * dt;
    *theta += (kp * q + ki * integral) * dt;
}

int main() {
    float omega = 2.0f * PI * 50.0f;
    float kp = 100.0f;
    float ki = 1000.0f;
    float dt = 0.0001f;
    float theta = 0.0f;
    float t = 0.0f;

    int total_steps = 200;
    int print_interval = 40;

    printf("t=%.4f, theta=%.4f, q=%.4f\n", t, theta, 0.0f);

    for (int i = 1; i <= total_steps; i++) {
        t = i * dt;

        float a = sinf(omega * t);
        float b = sinf(omega * t - 2.0f * PI / 3.0f);
        float c = sinf(omega * t + 2.0f * PI / 3.0f);

        float alpha, beta;
        clark_transform(a, b, c, &alpha, &beta);

        float d, q;
        park_transform(alpha, beta, theta, &d, &q);

        pll_update(q, &theta, kp, ki, dt);

        if (i % print_interval == 0) {
            printf("t=%.4f, theta=%.4f, q=%.4f\n", t, theta, q);
        }
    }

    return 0;
}

