#define SQRT3_2 0.8660254f

int svpwm_sector_detection(float Ualpha, float Ubeta) {
    float V1 = Ubeta;
    float V2 = SQRT3_2 * Ualpha - 0.5f * Ubeta;
    float V3 = -SQRT3_2 * Ualpha - 0.5f * Ubeta;

    int A = (V1 > 0) ? 1 : 0;
    int B = (V2 > 0) ? 1 : 0;
    int C = (V3 > 0) ? 1 : 0;

    int N = A + 2 * B + 4 * C;

    switch(N) {
        case 3: return 1;
        case 1: return 2;
        case 5: return 3;
        case 4: return 4;
        case 6: return 5;
        case 2: return 6;
        default: return 0;
    }
}

