#include <stdio.h>

typedef struct {
    float kp;
    float ki;
    float kd;
    float last_error;
    float prev_error;
} IncrementalPID;

void pid_init(IncrementalPID *pid, float kp, float ki, float kd) {
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->last_error = 0.0f;
    pid->prev_error = 0.0f;
}

float pid_update(IncrementalPID *pid, float setpoint, float measurement) {
    float error = setpoint - measurement;

    float delta_error = error - pid->last_error;
    float delta2_error = error - 2.0f * pid->last_error + pid->prev_error;

    float control_increment = pid->kp * delta_error + 
                              pid->ki * error + 
                              pid->kd * delta2_error;

    pid->prev_error = pid->last_error;
    pid->last_error = error;

    return control_increment;
}

int main() {
    IncrementalPID pid;
    pid_init(&pid, 1.0f, 0.1f, 0.05f);

    float setpoint = 10.0f;
    float measurements[] = {9.0f, 9.5f, 9.8f, 10.0f, 10.1f};
    int cycles = sizeof(measurements) / sizeof(measurements[0]);

    for (int i = 0; i < cycles; i++) {
        float control_increment = pid_update(&pid, setpoint, measurements[i]);
        printf("Cycle %d: control_increment = %.6f\n", i + 1, control_increment);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

#define I_SC 8.0
#define V_OC 22.0
#define K 0.02
#define V_START 15.0
#define DV 0.5
#define MAX_ITER 20

double calculate_current(double v) {
    return I_SC - K * (v - V_OC) * (v - V_OC);
}

double calculate_power(double v) {
    double i = calculate_current(v);
    return v * i;
}

void mppt_perturb_and_observe() {
    double v = V_START;
    double p_prev = calculate_power(v);
    int direction = 1;

    printf("MPPT Perturb and Observe Algorithm Simulation\n");
    printf("Parameters: I_sc=%.2f, V_oc=%.2f, K=%.3f, dV=%.2f\n", I_SC, V_OC, K, DV);
    printf("Iter\tVoltage(V)\tCurrent(A)\tPower(W)\tDirection\n");
    printf("------------------------------------------------------------\n");

    for (int iter = 1; iter <= MAX_ITER; iter++) {
        double i = calculate_current(v);
        double p = v * i;

        printf("%d\t%.2f\t\t%.3f\t\t%.3f\t\t", iter, v, i, p);

        if (direction == 1) {
            printf("+ (increase)\n");
        } else {
            printf("- (decrease)\n");
        }

        if (iter < MAX_ITER) {
            double v_new = v + direction * DV;
            double p_new = calculate_power(v_new);

            if (p_new > p) {
                direction = direction;
            } else {
                direction = -direction;
            }

            v = v_new;
            p_prev = p_new;
        }
    }
}

