typedef struct {
    float dead_time_us;
    float switching_period_us;
    float compensation_voltage;
} DeadTimeCompensator;

void init_compensator(DeadTimeCompensator *comp, float dead_time, float period) {
    comp->dead_time_us = dead_time;
    comp->switching_period_us = period;
    comp->compensation_voltage = 0.0f;
}

float calculate_compensation(DeadTimeCompensator *comp, float duty_cycle, int current_sign) {
    float dead_time_ratio = comp->dead_time_us / comp->switching_period_us;
    float direction_factor = (duty_cycle > 0.5f) ? 1.0f : -1.0f;
    float compensation = dead_time_ratio * (float)current_sign * direction_factor;
    comp->compensation_voltage = compensation;
    return compensation;
}

