#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846f
#define K 1.414f
#define GAMMA 100.0f

typedef struct {
    float theta;
    float freq;
    float v_alpha;
    float v_beta;
    float integrator1;
    float integrator2;
    float freq_integrator;
} SinglePhasePLL;

void pll_init(SinglePhasePLL *pll, float init_freq) {
    pll->theta = 0.0f;
    pll->freq = init_freq;
    pll->v_alpha = 0.0f;
    pll->v_beta = 0.0f;
    pll->integrator1 = 0.0f;
    pll->integrator2 = 0.0f;
    pll->freq_integrator = 0.0f;
}

void pll_update(SinglePhasePLL *pll, float v_input, float dt) {
    float omega = 2.0f * PI * pll->freq;

    float sogi_error = v_input - pll->v_alpha;
    pll->integrator1 += (K * omega * sogi_error - omega * pll->v_beta) * dt;
    pll->v_alpha = pll->integrator1;

    pll->integrator2 += omega * pll->v_alpha * dt;
    pll->v_beta = pll->integrator2;

    float freq_error = v_input * pll->v_beta;
    pll->freq_integrator += GAMMA * freq_error * dt;
    pll->freq += pll->freq_integrator;

    if (pll->freq < 0.0f) pll->freq = 0.0f;

    pll->theta += 2.0f * PI * pll->freq * dt;
    while (pll->theta > 2.0f * PI) pll->theta -= 2.0f * PI;
    while (pll->theta < 0.0f) pll->theta += 2.0f * PI;
}

int main() {
    SinglePhasePLL pll;
    pll_init(&pll, 50.0f);

    float t = 0.0f;
    float dt = 0.0001f;
    float total_time = 0.1f;
    int print_interval = 100;
    int step_count = 0;

    printf("Time(s)\tInput(V)\tPhase(deg)\tFreq(Hz)\n");

    while (t < total_time + dt/2.0f) {
        float v_input = 220.0f * sinf(2.0f * PI * 50.0f * t + PI/4.0f);

        pll_update(&pll, v_input, dt);

        if (step_count % print_interval == 0) {
            float phase_deg = pll.theta * 180.0f / PI;
            printf("%.4f\t%.2f\t\t%.2f\t\t%.2f\n", 
                   t, v_input, phase_deg, pll.freq);
        }

        t += dt;
        step_count++;
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

#define SQRT3 1.7320508075688772
#define TWO_THIRDS (2.0/3.0)

void clarke_transform(double va, double vb, double vc, double *valpha, double *vbeta) {
    *valpha = TWO_THIRDS * (va - 0.5*vb - 0.5*vc);
    *vbeta = TWO_THIRDS * (SQRT3/2.0*vb - SQRT3/2.0*vc);
}

int determine_sector(double valpha, double vbeta) {
    if (vbeta > 0.0) {
        if (valpha > 0.0) {
            if (fabs(vbeta) < SQRT3 * valpha) {
                return 1;
            } else {
                return 2;
            }
        } else {
            if (fabs(vbeta) < -SQRT3 * valpha) {
                return 3;
            } else {
                return 2;
            }
        }
    } else {
        if (valpha < 0.0) {
            if (fabs(vbeta) < SQRT3 * valpha) {
                return 4;
            } else {
                return 5;
            }
        } else {
            if (fabs(vbeta) > SQRT3 * fabs(valpha)) {
                return 5;
            } else {
                return 6;
            }
        }
    }
}

void calculate_times_sector1(double valpha, double vbeta, double *t1, double *t2, double *t0) {
    double X = SQRT3 * vbeta;
    double Y = (SQRT3/2.0) * vbeta + (3.0/2.0) * valpha;
    double Z = -(SQRT3/2.0) * vbeta + (3.0/2.0) * valpha;

    *t1 = Z;
    *t2 = Y;

    double total = *t1 + *t2;
    if (total > 1.0) {
        *t1 = *t1 / total;
        *t2 = *t2 / total;
        total = 1.0;
    }
    *t0 = 1.0 - total;
}

void calculate_times(int sector, double valpha, double vbeta, double *t1, double *t2, double *t0) {
    if (sector == 1) {
        calculate_times_sector1(valpha, vbeta, t1, t2, t0);
    } else {
        *t1 = 0.0;
        *t2 = 0.0;
        *t0 = 1.0;
    }
}

void test_case(double va, double vb, double vc, int case_num) {
    double valpha, vbeta;
    int sector;
    double t1, t2, t0;

    clarke_transform(va, vb, vc, &valpha, &vbeta);
    sector = determine_sector(valpha, vbeta);
    calculate_times(sector, valpha, vbeta, &t1, &t2, &t0);

    printf("测试用例 %d:\n", case_num);
    printf("  输入: Va=%.4f, Vb=%.4f, Vc=%.4f\n", va, vb, vc);
    printf("  Clarke变换: Vα=%.4f, Vβ=%.4f\n", valpha, vbeta);
    printf("  扇区: %d\n", sector);
    printf("  作用时间: T1=%.4f, T2=%.4f, T0=%.4f\n", t1, t2, t0);
    printf("\n");
}

