    printf("三相电压型逆变器SVPWM空间矢量调制算法测试\n");
    printf("==========================================\n\n");

    test_case(1.0, -0.5, -0.5, 1);
    test_case(0.5, 0.0, -0.5, 2);
    test_case(0.0, 0.0, 0.0, 3);

    return 0;
}

