void soc_ah_integration(float current, float delta_t, float capacity_ah, float *soc, int *initialized) {
    static float accumulated_ah = 0.0f;

    if (*initialized == 0) {
        accumulated_ah = (*soc) * capacity_ah;
        *initialized = 1;
        return;
    }

    accumulated_ah += (current * delta_t) / 3600.0f;

    *soc = accumulated_ah / capacity_ah;

    if (*soc > 1.0f) {
        *soc = 1.0f;
        accumulated_ah = capacity_ah;
    } else if (*soc < 0.0f) {
        *soc = 0.0f;
        accumulated_ah = 0.0f;
    }
}

