    float Vref3 = (-SQRT3 * Ualpha - Ubeta) / 2.0f;

    int A = (Vref1 > 0) ? 1 : 0;
    int B = (Vref2 > 0) ? 1 : 0;
    int C = (Vref3 > 0) ? 1 : 0;

    int N = 4 * C + 2 * B + A;

    switch(N) {
        case 1: return 2;
        case 2: return 6;
        case 3: return 1;
        case 4: return 4;
        case 5: return 3;
        case 6: return 5;
        default: return 0;
    }
}

