#define PI 3.14159265358979323846
#define INIT_FREQ 50.0
#define INIT_PHASE 0.0
#define KP 100.0
#define KI 1000.0

static double error_integral = 0.0;

void pll_update(double voltage, double *phase, double *frequency, double dt) {
    double v_alpha = sin(*phase);
    double v_beta = cos(*phase);

    double error = voltage * v_beta;

    *frequency += KP * error + KI * error_integral;

    *phase += 2.0 * PI * (*frequency) * dt;
    while (*phase >= 2.0 * PI) *phase -= 2.0 * PI;
    while (*phase < 0.0) *phase += 2.0 * PI;

    error_integral += error * dt;
}

int main() {
    double actual_freq = 50.0;
    double actual_phase = 0.2;
    double amplitude = 1.0;
    double dt = 0.0001;
    int total_steps = 1000;
    int print_interval = 100;

    double phase = INIT_PHASE;
    double frequency = INIT_FREQ;
    error_integral = 0.0;

    for (int i = 0; i < total_steps; i++) {
        double t = i * dt;
        double voltage = amplitude * sin(2.0 * PI * actual_freq * t + actual_phase);

        pll_update(voltage, &phase, &frequency, dt);

        double actual_phase_current = fmod(2.0 * PI * actual_freq * t + actual_phase, 2.0 * PI);
        if (actual_phase_current < 0) actual_phase_current += 2.0 * PI;

        if ((i + 1) % print_interval == 0) {
            printf("Time: %.4f s, Actual: %.2f rad, Estimated: %.2f rad, Freq: %.1f Hz\n",
                   t + dt, actual_phase_current, phase, frequency);
        }
    }

    return 0;
}

