#define Kp 0.5
#define Ki 0.1
#define D_MIN 0.05
#define D_MAX 0.90

static double integral_state = 0.0;

double boost_control(double V_ref, double V_meas, double Vin, double prev_D) {
    double e = V_ref - V_meas;

    double P_out = Kp * e;

    double I_out = Ki * e + integral_state;

    double delta_D = (P_out + I_out) / Vin * 0.01;

    double D_new = prev_D + delta_D;

    if (D_new < D_MIN) {
        D_new = D_MIN;
    } else if (D_new > D_MAX) {
        D_new = D_MAX;
    }

    if (D_new > D_MIN && D_new < D_MAX) {
        integral_state = I_out;
    } else {
        integral_state = 0.0;
    }

    return D_new;
}

