    for (int i = 0; i < N; i++) {
        float t = i * 0.1f;  // 采样时间
        float sine_wave = sin(2.0f * M_PI * 1.0f * t);  // 1Hz正弦波
        float noise = 0.3f * sin(2.0f * M_PI * 10.0f * t);  // 10Hz高频噪声
        original_signal[i] = sine_wave + noise;
    }

    // 定义不同的alpha值
    float alphas[] = {0.1f, 0.5f, 0.9f};
    const int num_alphas = 3;

    // 存储滤波结果
