    // 对每个alpha值进行滤波
    for (int a = 0; a < num_alphas; a++) {
        float prev_output = 0.0f;  // 初始状态为0
        for (int i = 0; i < N; i++) {
            filtered_signals[a][i] = iir_lowpass_filter(original_signal[i], &prev_output, alphas[a]);
        }
