    printf("\n=== 滤波效果分析 ===\n");
    printf("alpha=0.1: 滤波效果最强，噪声抑制最好，但响应最慢\n");
    printf("alpha=0.5: 平衡效果，有一定噪声抑制，响应适中\n");
    printf("alpha=0.9: 滤波效果最弱，几乎跟随原始信号，响应最快\n");

    // 计算噪声抑制效果
    printf("\n=== 噪声抑制效果（最后5个采样点的标准差） ===\n");
    for (int a = 0; a < num_alphas; a++) {
        // 计算最后5个采样点的标准差
        float sum = 0.0f;
        float sum_sq = 0.0f;
        int start = N - 5;

        for (int i = start; i < N; i++) {
            sum += filtered_signals[a][i];
            sum_sq += filtered_signals[a][i] * filtered_signals[a][i];
        }

        float mean = sum / 5.0f;
        float variance = (sum_sq / 5.0f) - (mean * mean);
        float stddev = sqrt(fabs(variance));

        printf("alpha=%.1f: 标准差 = %.4f\n", alphas[a], stddev);
    }

    return 0;
}

