    const float Fs = 1000.0f;
    const float alpha = 0.1f;
    const int N = 100;

    float prev_output1 = 0.0f;
    float prev_output2 = 0.0f;

    float signal1_input[N];
    float signal1_output[N];
    float signal2_input[N];
    float signal2_output[N];

    float f1 = 10.0f;
    float f2 = 200.0f;

    for (int n = 0; n < N; n++) {
        signal1_input[n] = sinf(2.0f * M_PI * f1 * n / Fs);
        signal2_input[n] = sinf(2.0f * M_PI * f2 * n / Fs);
    }

    for (int n = 0; n < N; n++) {
        signal1_output[n] = iir_lowpass(signal1_input[n], &prev_output1, alpha);
        signal2_output[n] = iir_lowpass(signal2_input[n], &prev_output2, alpha);
    }

    printf("信号1: 输入[0]=%.6f, 输出[0]=%.6f\n", signal1_input[0], signal1_output[0]);
    printf("信号1: 输入[1]=%.6f, 输出[1]=%.6f\n", signal1_input[1], signal1_output[1]);
    printf("信号1: 输入[2]=%.6f, 输出[2]=%.6f\n", signal1_input[2], signal1_output[2]);
    printf("信号1: 输入[3]=%.6f, 输出[3]=%.6f\n", signal1_input[3], signal1_output[3]);
    printf("信号1: 输入[4]=%.6f, 输出[4]=%.6f\n", signal1_input[4], signal1_output[4]);
    printf("\n");
