    printf("信号2: 输入[1]=%.6f, 输出[1]=%.6f\n", signal2_input[1], signal2_output[1]);
    printf("信号2: 输入[2]=%.6f, 输出[2]=%.6f\n", signal2_input[2], signal2_output[2]);
    printf("信号2: 输入[3]=%.6f, 输出[3]=%.6f\n", signal2_input[3], signal2_output[3]);
    printf("信号2: 输入[4]=%.6f, 输出[4]=%.6f\n", signal2_input[4], signal2_output[4]);
    printf("\n");

    float max_input1 = 0.0f;
    float max_output1 = 0.0f;
    float max_input2 = 0.0f;
    float max_output2 = 0.0f;

    for (int n = 20; n < N; n++) {
        if (fabsf(signal1_input[n]) > max_input1) max_input1 = fabsf(signal1_input[n]);
        if (fabsf(signal1_output[n]) > max_output1) max_output1 = fabsf(signal1_output[n]);
        if (fabsf(signal2_input[n]) > max_input2) max_input2 = fabsf(signal2_input[n]);
        if (fabsf(signal2_output[n]) > max_output2) max_output2 = fabsf(signal2_output[n]);
    }

    float attenuation1 = max_output1 / max_input1;
