    float kp = 0.8f;
    float ki = 0.05f;
    float kd = 0.1f;

    for (int i = 1; i <= 5; i++) {
        float delta_u = incremental_pid(setpoint, measured, kp, ki, kd);
        measured += delta_u;

        printf("Loop %d: measured=%.2f, delta_u=%.2f\n", i, measured, delta_u);
    }

    return 0;
}

