#include <stdio.h>
#include <math.h>

static double integral = 0.0;

double buck_pi_controller(double vout_measured, double vref, double kp, double ki, double dt) {
    double error = vref - vout_measured;
    double duty_cycle;

    double new_integral = integral + error * dt;
    duty_cycle = kp * error + ki * new_integral;

    if (duty_cycle > 1.0) {
        duty_cycle = 1.0;
    } else if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    } else {
        integral = new_integral;
    }

    return duty_cycle;
}

int main() {
    const double Vin = 12.0;
    const double Vref = 5.0;
    const double kp = 0.1;
    const double ki = 5.0;
    const double dt = 0.001;

    double duty_cycle = 0.4;
    double vout = duty_cycle * Vin;
    integral = 0.0;

    printf("Buck降压转换器PI控制仿真\n");
    printf("Vin=%.1fV, Vref=%.1fV, kp=%.1f, ki=%.1f, dt=%.4fs\n\n", Vin, Vref, kp, ki, dt);

    for (int i = 0; i < 100; i++) {
        printf("循环%d: vout=%.3fV, duty=%.3f\n", i, vout, duty_cycle);

        duty_cycle = buck_pi_controller(vout, Vref, kp, ki, dt);
        vout = duty_cycle * Vin;
    }

    return 0;
}

#include <stdio.h>
