float calculate_rms(const float *samples, int n) {
    if (n <= 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    for (int i = 0; i < n; i++) {
        sum += samples[i] * samples[i];
    }

    return sqrtf(sum / n);
}

