}

#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846f
#define PI_2_3 (2.0f * PI / 3.0f)
#define INTEGRAL_LIMIT 1000.0f

void clark_transform(float ua, float ub, float uc, float *ualpha, float *ubeta) {
    *ualpha = (2.0f/3.0f) * (ua - 0.5f * ub - 0.5f * uc);
    *ubeta = (2.0f/3.0f) * (0.86602540378f * ub - 0.86602540378f * uc);
}

void park_transform(float ualpha, float ubeta, float theta, float *ud, float *uq) {
    float cos_theta = cosf(theta);
    float sin_theta = sinf(theta);
    *ud = ualpha * cos_theta + ubeta * sin_theta;
    *uq = -ualpha * sin_theta + ubeta * cos_theta;
}

float pi_controller(float error, float kp, float ki, float *integral, float dt) {
    *integral += error * dt;
    if (*integral > INTEGRAL_LIMIT) *integral = INTEGRAL_LIMIT;
    if (*integral < -INTEGRAL_LIMIT) *integral = -INTEGRAL_LIMIT;
    return kp * error + ki * (*integral);
}

void pll_update(float ua, float ub, float uc, float *theta, float *freq, float dt, float kp, float ki) {
    static float integral = 0.0f;
    float ualpha, ubeta;
    float ud, uq;

    clark_transform(ua, ub, uc, &ualpha, &ubeta);
    park_transform(ualpha, ubeta, *theta, &ud, &uq);

    float delta_freq = pi_controller(-uq, kp, ki, &integral, dt);
    *freq = 50.0f + delta_freq;
    *theta += 2.0f * PI * (*freq) * dt;

    if (*theta > 2.0f * PI) *theta -= 2.0f * PI;
    if (*theta < 0) *theta += 2.0f * PI;
}

int main() {
    float dt = 0.001f;
    float kp = 100.0f;
    float ki = 1000.0f;
    float theta_est = 0.0f;
    float freq_est = 50.0f;
    float theta_grid = 0.0f;

    for (int i = 0; i < 5; i++) {
        float ua = sinf(theta_grid);
        float ub = sinf(theta_grid - PI_2_3);
        float uc = sinf(theta_grid + PI_2_3);

        pll_update(ua, ub, uc, &theta_est, &freq_est, dt, kp, ki);

        printf("Step %d: theta_est = %.3f, theta_real = %.3f\n", 
               i+1, theta_est, theta_grid);

        theta_grid += 2.0f * PI * 50.0f * dt;
        if (theta_grid > 2.0f * PI) theta_grid -= 2.0f * PI;
    }

    return 0;
}

