#define EPSILON 1e-6f
#define SQRT3 1.7320508075688772f

int svpwm_sector_detection(float Ua, float Ub, float Uc) {
    float Ualpha = Ua;
    float Ubeta = (Ub - Uc) / SQRT3;

    float A = Ubeta;
    float B = SQRT3/2.0f * Ualpha - 0.5f * Ubeta;
    float C = -SQRT3/2.0f * Ualpha - 0.5f * Ubeta;

    int N = 0;
    if (A > EPSILON) N = 1;
    if (B > EPSILON) N += 2;
    if (C > EPSILON) N += 4;

    const int sector_map[8] = {0, 2, 0, 1, 4, 3, 5, 0};
    return sector_map[N];
}

int main() {
    printf("SVPWM sector detection test\n");
    printf("============================\n");

    float test_cases[][3] = {
        {0.5f, -0.25f, -0.25f},
        {0.0f, 0.866f, -0.866f},
        {0.8f, -0.4f, -0.4f},
        {-0.5f, 0.25f, 0.25f},
        {0.0f, -0.866f, 0.866f}
    };

    int expected[] = {2, 1, 2, 5, 4};

    for (int i = 0; i < 5; i++) {
        float Ua = test_cases[i][0];
        float Ub = test_cases[i][1];
        float Uc = test_cases[i][2];

        int sector = svpwm_sector_detection(Ua, Ub, Uc);

        printf("Test case %d:\n", i+1);
        printf("  Input: Ua=%.3f, Ub=%.3f, Uc=%.3f\n", Ua, Ub, Uc);
        printf("  Calculated sector: %d\n", sector);
        printf("  Expected sector: %d\n", expected[i]);
        printf("  Result: %s\n\n", sector == expected[i] ? "PASS" : "FAIL");
    }

    return 0;
}

