#define PI 3.14159265358979323846
#define PI_2_3 (2.0 * PI / 3.0)

void clarke_transform(double ua, double ub, double uc, double *v_alpha, double *v_beta) {
    *v_alpha = (2.0/3.0) * (ua - 0.5*ub - 0.5*uc);
    *v_beta = (2.0/3.0) * (sqrt(3.0)/2.0 * ub - sqrt(3.0)/2.0 * uc);
}

void park_transform(double v_alpha, double v_beta, double theta, double *vd, double *vq) {
    double cos_theta = cos(theta);
    double sin_theta = sin(theta);
    *vd = v_alpha * cos_theta + v_beta * sin_theta;
    *vq = -v_alpha * sin_theta + v_beta * cos_theta;
}

double pi_controller(double error, double kp, double ki, double dt, double *integral) {
    *integral += error * dt;
    double output = kp * error + ki * (*integral);

    if (output > 100.0) output = 100.0;
    if (output < -100.0) output = -100.0;

    return output;
}

void pll_update(double ua, double ub, double uc, double dt, double kp, double ki, double *theta, double *freq) {
    static double integral = 0.0;

    double v_alpha, v_beta;
    clarke_transform(ua, ub, uc, &v_alpha, &v_beta);

    double vd, vq;
    park_transform(v_alpha, v_beta, *theta, &vd, &vq);

    double error = -vq;
    double delta_freq = pi_controller(error, kp, ki, dt, &integral);

    *freq = 2.0 * PI * 50.0 + delta_freq;
    *theta += *freq * dt;

    while (*theta > 2.0 * PI) *theta -= 2.0 * PI;
    while (*theta < 0) *theta += 2.0 * PI;
}

