#define SQRT3 1.73205080757f

int calc_sector(float Ua, float Ub, float Uc) {
    float Ualpha = Ua;
    float Ubeta = (Ua + 2.0f * Ub) / SQRT3;

    int sector = 0;

    if (Ubeta > 0.0f) {
        sector = 1;
    } else {
        sector = 4;
    }

    if (fabsf(Ualpha) > fabsf(Ubeta) / SQRT3) {
        sector += 2;
    }

    if (Ualpha * Ubeta < 0.0f) {
        sector += 1;
    }

    if (sector > 6) {
        sector -= 6;
    }
    if (sector < 1) {
        sector += 6;
    }

    return sector;
}

