    };

    for (int i = 0; i < 3; i++) {
        float Ua = test_cases[i][0];
        float Ub = test_cases[i][1];
        float Uc = test_cases[i][2];

        int sector = calc_sector(Ua, Ub, Uc);
        printf("测试(%.1f,%.1f,%.1f) -> 扇区%d\n", Ua, Ub, Uc, sector);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define SIN_TABLE_SIZE 256
#define CARRIER_FREQ_HZ 10000.0f
#define CARRIER_PERIOD_US (1000000.0f / CARRIER_FREQ_HZ)

float sin_table[SIN_TABLE_SIZE];

void init_sin_table() {
    for (int i = 0; i < SIN_TABLE_SIZE; i++) {
        float angle = 2.0f * 3.14159265358979323846f * i / SIN_TABLE_SIZE;
        sin_table[i] = 0.5f * (1.0f + sinf(angle));
    }
}

void generate_spwm_pulses(float modulation_index, float frequency_hz, int cycles) {
    if (modulation_index < 0.0f || modulation_index > 1.0f) return;
    if (frequency_hz <= 0.0f) return;
    if (cycles <= 0) return;

    float sin_period_us = 1000000.0f / frequency_hz;
    float sin_step_us = sin_period_us / SIN_TABLE_SIZE;

    int total_steps = cycles * SIN_TABLE_SIZE;
    int last_state = 0;

    for (int step = 0; step < total_steps; step++) {
        int table_index = step % SIN_TABLE_SIZE;
        float sin_value = sin_table[table_index];
        float modulated_value = sin_value * modulation_index;

        float step_start_time = step * sin_step_us;
        float step_end_time = (step + 1) * sin_step_us;

        int carrier_cycles = (int)((step_end_time - step_start_time) / CARRIER_PERIOD_US);
        if (carrier_cycles < 1) carrier_cycles = 1;

        float carrier_step_us = (step_end_time - step_start_time) / carrier_cycles;

        for (int carrier = 0; carrier < carrier_cycles; carrier++) {
            float carrier_start = step_start_time + carrier * carrier_step_us;
            float carrier_mid = carrier_start + carrier_step_us / 2.0f;

            int new_state = (modulated_value > 0.5f) ? 1 : 0;

            if (new_state != last_state) {
                printf("%.2f: %d\n", carrier_mid, new_state);
                last_state = new_state;
            }
        }
    }

    if (last_state == 1) {
        printf("%.2f: 0\n", total_steps * sin_step_us);
    }
}

int main() {
    init_sin_table();

    printf("=== Test 1: MI=0.5, Freq=50Hz, 2 cycles ===\n");
    generate_spwm_pulses(0.5f, 50.0f, 2);

    printf("\n=== Test 2: MI=0.8, Freq=60Hz, 1 cycle ===\n");
    generate_spwm_pulses(0.8f, 60.0f, 1);

    printf("\n=== Test 3: MI=1.0, Freq=100Hz, 1 cycle ===\n");
    generate_spwm_pulses(1.0f, 100.0f, 1);

    return 0;
}

#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846
#define PI_2_3 (2.0 * PI / 3.0)
#define TS 0.001

typedef struct {
    float va, vb, vc;
} ThreePhase;

typedef struct {
    float alpha, beta;
} AlphaBeta;

typedef struct {
    float d, q;
} DQ;

typedef struct {
    float kp;
    float ki;
    float integral;
    float error;
    float output;
} PIController;

typedef struct {
    float theta_est;
    float omega_est;
    float freq_est;
    PIController pi;
} PLLState;

void clarke_transform(const ThreePhase* abc, AlphaBeta* alphabeta) {
    alphabeta->alpha = abc->va;
    alphabeta->beta = (abc->vb - abc->vc) / sqrtf(3.0f);
}

void park_transform(const AlphaBeta* alphabeta, float theta, DQ* dq) {
    float cos_theta = cosf(theta);
    float sin_theta = sinf(theta);

    dq->d = alphabeta->alpha * cos_theta + alphabeta->beta * sin_theta;
    dq->q = -alphabeta->alpha * sin_theta + alphabeta->beta * cos_theta;
}

void pi_controller_update(PIController* pi, float error) {
    pi->error = error;
    pi->integral += error * TS;
    pi->output = pi->kp * error + pi->ki * pi->integral;
}

void pll_update(PLLState* pll, const ThreePhase* voltage) {
    AlphaBeta alphabeta;
    DQ dq;

    clarke_transform(voltage, &alphabeta);
    park_transform(&alphabeta, pll->theta_est, &dq);

    pi_controller_update(&pll->pi, dq.q);

    pll->omega_est = pll->pi.output;
    pll->theta_est += pll->omega_est * TS;

    while (pll->theta_est > 2.0f * PI) {
        pll->theta_est -= 2.0f * PI;
    }
    while (pll->theta_est < 0) {
        pll->theta_est += 2.0f * PI;
    }

    pll->freq_est = pll->omega_est / (2.0f * PI);
}

int main() {
    PLLState pll;
    ThreePhase voltage;
    float theta_input;

    pll.theta_est = 0.0f;
    pll.omega_est = 2.0f * PI * 50.0f;
    pll.freq_est = 50.0f;

    pll.pi.kp = 100.0f;
    pll.pi.ki = 1000.0f;
    pll.pi.integral = 0.0f;
    pll.pi.error = 0.0f;
    pll.pi.output = 0.0f;

    printf("SRF-PLL Test\n");
    printf("Iter\tTheta_in(rad)\tTheta_est(rad)\tFreq_est(Hz)\n");
    printf("---------------------------------------------------\n");

    for (int i = 0; i < 5; i++) {
        theta_input = i * PI / 6.0f;

        voltage.va = sinf(theta_input);
        voltage.vb = sinf(theta_input - PI_2_3);
        voltage.vc = sinf(theta_input + PI_2_3);

        pll_update(&pll, &voltage);

        printf("%d\t%.4f\t\t%.4f\t\t%.2f\n", 
               i+1, theta_input, pll.theta_est, pll.freq_est);
    }

    return 0;
}

