} IIRFilter;

void iir_filter_init(IIRFilter* filter, float alpha) {
    filter->alpha = alpha;
    filter->prev_output = 0.0f;
}

float iir_filter_update(IIRFilter* filter, float input) {
    float output = filter->alpha * input + (1.0f - filter->alpha) * filter->prev_output;
    filter->prev_output = output;
    return output;
}

