#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define PI 3.14159265358979323846
#define TWO_PI (2.0 * PI)

typedef struct {
    float theta_est;
    float omega_est;
    float integral_sum;
    float omega_nom;
    float Ts;
    float Kp;
    float Ki;
} SRF_PLL;

void SRF_PLL_Update(SRF_PLL *pll, float ua, float ub, float uc) {
    // 1. Clark变换
    float ualpha = (2.0/3.0) * (ua - 0.5*ub - 0.5*uc);
    float ubeta = (2.0/3.0) * (sqrt(3.0)/2.0*ub - sqrt(3.0)/2.0*uc);

    // 2. Park变换
    float cos_theta = cos(pll->theta_est);
    float sin_theta = sin(pll->theta_est);
    float ud = ualpha * cos_theta + ubeta * sin_theta;
    float uq = -ualpha * sin_theta + ubeta * cos_theta;

    // 3. PI调节器
    pll->integral_sum += uq * pll->Ts;
    float delta_omega = pll->Kp * uq + pll->Ki * pll->integral_sum;

    // 4. 更新估计角频率和相位角
    pll->omega_est = pll->omega_nom + delta_omega;
    pll->theta_est += pll->omega_est * pll->Ts;

    // 保持相位角在0~2π范围内
    pll->theta_est = fmod(pll->theta_est, TWO_PI);
    if (pll->theta_est < 0) {
        pll->theta_est += TWO_PI;
    }
}

int main() {
    SRF_PLL pll;

    // 初始化PLL参数
    pll.theta_est = 0.0;
    pll.omega_est = 314.159265;  // 2π*50
    pll.integral_sum = 0.0;
    pll.omega_nom = 314.159265;  // 2π*50 rad/s
    pll.Ts = 0.0001;             // 100us采样周期
    pll.Kp = 100.0;
    pll.Ki = 5000.0;

    float U = 1.0;               // 电压幅值
    float phi0 = 0.0;            // 初始相位

    float time = 0.0;
    float print_interval = 0.01;
    float next_print_time = 0.0;

    float grid_freq = 50.0;      // 初始电网频率
    float grid_omega = 2.0 * PI * grid_freq;

    printf("Time(s)\t\tEst_Freq(Hz)\tEst_Phase(rad)\n");
    printf("--------------------------------------------\n");

    while (time <= 0.2) {
        // 0.1秒后频率突变到50.5Hz
        if (time >= 0.1) {
            grid_freq = 50.5;
            grid_omega = 2.0 * PI * grid_freq;
        }

        // 计算电网真实相位
        float theta_grid = grid_omega * time + phi0;

        // 生成三相电压
        float ua = U * sin(theta_grid);
        float ub = U * sin(theta_grid - 2.0*PI/3.0);
        float uc = U * sin(theta_grid + 2.0*PI/3.0);

        // 更新PLL
        SRF_PLL_Update(&pll, ua, ub, uc);

        // 每0.01秒打印一次
        if (time >= next_print_time - 1e-6) {
            float est_freq = pll.omega_est / (2.0 * PI);
            printf("%.4f\t\t%.4f\t\t%.4f\n", time, est_freq, pll.theta_est);
            next_print_time += print_interval;
        }

        time += pll.Ts;
    }

