}

#include <stdio.h>
#include <math.h>

typedef struct {
    float Kp, Ki, Kd;
    float integral;
    float prev_error;
    float output_limit;
} PID_Controller;

void PID_Init(PID_Controller *pid, float Kp, float Ki, float Kd, float limit) {
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->output_limit = limit;
}

float PID_Update(PID_Controller *pid, float setpoint, float measurement, float dt) {
    float error = setpoint - measurement;

    pid->integral += error * dt;

    float derivative = (error - pid->prev_error) / dt;

    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    if (output > pid->output_limit) {
        output = pid->output_limit;
    } else if (output < -pid->output_limit) {
        output = -pid->output_limit;
    }

    pid->prev_error = error;

    return output;
}

int main() {
    PID_Controller pid;
    PID_Init(&pid, 1.0f, 0.5f, 0.1f, 10.0f);

    float test_setpoints[] = {10.0f, 10.0f, 10.0f};
    float test_measurements[] = {8.0f, 9.0f, 9.5f};
    float dt = 0.1f;

    for (int i = 0; i < 3; i++) {
        float output = PID_Update(&pid, test_setpoints[i], test_measurements[i], dt);
        printf("Cycle %d: setpoint=%.2f, measurement=%.2f, output=%.2f\n", 
               i+1, test_setpoints[i], test_measurements[i], output);
    }

    return 0;
}

