#define SQRT3 1.7320508075688772

int get_sector(double Ualpha, double Ubeta) {
    double V1 = Ubeta;
    double V2 = (SQRT3/2.0)*Ualpha - (1.0/2.0)*Ubeta;
    double V3 = -(SQRT3/2.0)*Ualpha - (1.0/2.0)*Ubeta;

    int A = (V1 > 0) ? 1 : 0;
    int B = (V2 > 0) ? 1 : 0;
    int C = (V3 > 0) ? 1 : 0;

    int sector_code = A + 2*B + 4*C;

    switch(sector_code) {
        case 3: return 1;
        case 1: return 2;
        case 5: return 3;
        case 4: return 4;
        case 6: return 5;
        case 2: return 6;
        default: return 0;
    }
}

