        {-1.0, 0.0},     // 扇区5
        {-0.5, -0.866},  // 扇区4
        {0.5, -0.866}    // 扇区6
    };

    for(int i = 0; i < 6; i++) {
        double Ualpha = test_cases[i][0];
        double Ubeta = test_cases[i][1];
        int sector = get_sector(Ualpha, Ubeta);
        printf("Uα=%.2f, Uβ=%.2f → 扇区%d\n", Ualpha, Ubeta, sector);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

typedef struct {
    double voltage;
    double current;
    double power;
    double ref_voltage;
} PVPanel;

void measure_pv_parameters(PVPanel *panel) {
    panel->voltage = panel->ref_voltage;
    if (panel->voltage < 0.0) panel->voltage = 0.0;
    if (panel->voltage > 50.0) panel->voltage = 50.0;

    panel->current = 5.0 - 0.1 * panel->voltage;
    if (panel->current < 0.0) panel->current = 0.0;

    panel->power = panel->voltage * panel->current;
}

void perturb_and_observe(PVPanel *panel, double delta_v) {
    double old_power = panel->power;
    double old_ref_voltage = panel->ref_voltage;

    panel->ref_voltage += delta_v;
    if (panel->ref_voltage < 0.0) panel->ref_voltage = 0.0;
    if (panel->ref_voltage > 50.0) panel->ref_voltage = 50.0;

    measure_pv_parameters(panel);

    if (panel->power < old_power) {
        delta_v = -delta_v;
        panel->ref_voltage = old_ref_voltage + delta_v;
        if (panel->ref_voltage < 0.0) panel->ref_voltage = 0.0;
        if (panel->ref_voltage > 50.0) panel->ref_voltage = 50.0;
        measure_pv_parameters(panel);
    }
}

int main() {
    PVPanel panel;
    panel.ref_voltage = 10.0;
    double delta_v = 0.5;

    measure_pv_parameters(&panel);

    printf("迭代次数\t参考电压(V)\t输出电压(V)\t输出电流(A)\t功率(W)\n");
    printf("0\t\t%.2f\t\t%.2f\t\t%.2f\t\t%.2f\n", 
           panel.ref_voltage, panel.voltage, panel.current, panel.power);

    double max_power = panel.power;
    double max_power_voltage = panel.voltage;

    for (int i = 1; i <= 10; i++) {
        perturb_and_observe(&panel, delta_v);

        printf("%d\t\t%.2f\t\t%.2f\t\t%.2f\t\t%.2f\n", 
               i, panel.ref_voltage, panel.voltage, panel.current, panel.power);

        if (panel.power > max_power) {
            max_power = panel.power;
            max_power_voltage = panel.voltage;
        }
    }

    printf("\n最终找到的最大功率点：\n");
    printf("电压：%.2f V\n", max_power_voltage);
    printf("功率：%.2f W\n", max_power);

    return 0;
}

#include <stdio.h>
#include <math.h>

#define KP 100.0
#define KI 5000.0
#define NOMINAL_FREQ 50.0
#define SAMPLE_RATE 10000.0
#define DT (1.0 / SAMPLE_RATE)
#define PRINT_INTERVAL 0.01

typedef struct {
    double phase;
    double freq;
    double integral;
} PLL_State;

void pll_step(PLL_State *state, double voltage_sample, double dt) {
    double error = voltage_sample * cos(state->phase);

    state->freq = NOMINAL_FREQ + KP * error + KI * state->integral;

    state->integral += error * dt;

    state->phase += 2.0 * M_PI * state->freq * dt;

    while (state->phase >= 2.0 * M_PI) {
        state->phase -= 2.0 * M_PI;
    }
    while (state->phase < 0) {
        state->phase += 2.0 * M_PI;
    }
}

int main() {
    PLL_State pll = {0.0, 50.0, 0.0};

    double simulation_time = 0.1;
    int total_samples = (int)(simulation_time * SAMPLE_RATE);
    int print_interval_samples = (int)(PRINT_INTERVAL * SAMPLE_RATE);

    printf("Time: %.4fs, Actual: %.3f rad, Estimated: %.3f rad, Freq: %.2f Hz\n", 
           0.0, 0.0, pll.phase, pll.freq);

    for (int i = 1; i <= total_samples; i++) {
        double t = i * DT;
        double actual_phase = 2.0 * M_PI * 50.0 * t;
        double voltage_sample = sin(actual_phase);

        pll_step(&pll, voltage_sample, DT);

        if (i % print_interval_samples == 0) {
            double normalized_actual_phase = fmod(actual_phase, 2.0 * M_PI);
            if (normalized_actual_phase < 0) {
                normalized_actual_phase += 2.0 * M_PI;
            }
            printf("Time: %.4fs, Actual: %.3f rad, Estimated: %.3f rad, Freq: %.2f Hz\n", 
                   t, normalized_actual_phase, pll.phase, pll.freq);
        }
    }

    return 0;
}

#include <stdio.h>

typedef struct {
    float kp;
    float ki;
    float kd;
    float prev_error;
    float prev_prev_error;
    float output;
} IncrementalPID;

void pid_init(IncrementalPID *pid, float kp, float ki, float kd) {
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->prev_error = 0.0f;
    pid->prev_prev_error = 0.0f;
    pid->output = 0.0f;
}

float pid_update(IncrementalPID *pid, float setpoint, float measured) {
    float error = setpoint - measured;

    float delta_output = pid->kp * (error - pid->prev_error) +
                        pid->ki * error +
                        pid->kd * (error - 2.0f * pid->prev_error + pid->prev_prev_error);

    pid->prev_prev_error = pid->prev_error;
    pid->prev_error = error;
    pid->output += delta_output;

    return delta_output;
}

int main() {
    IncrementalPID pid;
    pid_init(&pid, 1.2f, 0.5f, 0.1f);

