float mppt_perturb_observe(float V, float I, float V_prev, float P_prev, float D, float delta_D) {
    float P = V * I;

    if (P > P_prev) {
        if (V > V_prev) {
            D = D + delta_D;
        } else {
            D = D - delta_D;
        }
    } else {
        if (V > V_prev) {
            D = D - delta_D;
        } else {
            D = D + delta_D;
        }
    }

    if (D < 0.0f) D = 0.0f;
    if (D > 1.0f) D = 1.0f;

    return D;
}

