#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846f
#define OMEGA0 (2.0f * PI * 50.0f)
#define KP 100.0f
#define KI 2000.0f

void park_transform(float a, float b, float c, float theta, float *d, float *q) {
    float cos_theta = cosf(theta);
    float sin_theta = sinf(theta);
    float cos_theta_120 = cosf(theta - 2.0f*PI/3.0f);
    float sin_theta_120 = sinf(theta - 2.0f*PI/3.0f);
    float cos_theta_240 = cosf(theta + 2.0f*PI/3.0f);
    float sin_theta_240 = sinf(theta + 2.0f*PI/3.0f);

    *d = (2.0f/3.0f) * (cos_theta * a + cos_theta_120 * b + cos_theta_240 * c);
    *q = (2.0f/3.0f) * (-sin_theta * a - sin_theta_120 * b - sin_theta_240 * c);
}

void pll_update(float v_d, float v_q, float *theta, float *omega, float dt) {
    static float integral_vq = 0.0f;

    integral_vq += v_q * dt;
    *omega = OMEGA0 + KP * v_q + KI * integral_vq;
    *theta = *theta + (*omega) * dt;

    while (*theta > 2.0f * PI) {
        *theta -= 2.0f * PI;
    }
    while (*theta < 0) {
        *theta += 2.0f * PI;
    }
}

int main() {
    float dt = 0.001f;
    float theta_grid = 0.0f;
    float theta_pll = 0.0f;
    float omega_pll = OMEGA0;
    float va, vb, vc;
    float v_d, v_q;

    printf("Time(s)  Grid_theta(rad)  PLL_theta(rad)  PLL_freq(Hz)\n");

    for (int i = 0; i < 5; i++) {
        float time = i * dt;

        va = sinf(theta_grid);
        vb = sinf(theta_grid - 2.0f*PI/3.0f);
        vc = sinf(theta_grid + 2.0f*PI/3.0f);

        park_transform(va, vb, vc, theta_pll, &v_d, &v_q);
        pll_update(v_d, v_q, &theta_pll, &omega_pll, dt);

        printf("%.3f    %.3f            %.3f           %.3f\n", 
               time, theta_grid, theta_pll, omega_pll/(2.0f*PI));

        theta_grid += OMEGA0 * dt;
        while (theta_grid > 2.0f * PI) {
            theta_grid -= 2.0f * PI;
        }
    }

    return 0;
}

