#define DELTA 0.01f
#define D_MIN 0.05f
#define D_MAX 0.95f

float mppt_perturb_and_observe(float V, float I, float *D_prev, float *P_prev, int *dir_prev) {
    float P_now = V * I;
    float dP = P_now - *P_prev;

    if (dP < 0) {
        *dir_prev = -(*dir_prev);
    }

    float D_new = *D_prev + (*dir_prev) * DELTA;

    if (D_new < D_MIN) D_new = D_MIN;
    if (D_new > D_MAX) D_new = D_MAX;

    *D_prev = D_new;
    *P_prev = P_now;

    return D_new;
}

