    for (int i = 1; i <= 20; i++) {
        float V = simulate_pv_voltage(D);
        float I = simulate_pv_current(V);
        float P = V * I;

        printf("Iter %2d: V=%.2f I=%.2f P=%.2f D=%.3f\n", i, V, I, P, D);

        D = mppt_perturb_and_observe(V, I, &D, &P_prev, &dir);
    }

    printf("\nFinal values:\n");
    float V_final = simulate_pv_voltage(D);
    float I_final = simulate_pv_current(V_final);
    float P_final = V_final * I_final;
    printf("V=%.2fV, I=%.2fA, P=%.2fW, D=%.3f\n", V_final, I_final, P_final, D);

    return 0;
}

#include <stdio.h>
#include <math.h>

#define STEP 0.01f

static float prev_power = 0.0f;
static int first_run = 1;

float mppt_perturb_and_observe(float voltage, float current, float *duty_cycle) {
    float power = voltage * current;

    if (first_run) {
        first_run = 0;
        prev_power = power;
        return power;
    }

    if (power > prev_power) {
        *duty_cycle += STEP;
    } else {
        *duty_cycle -= STEP;
    }

    if (*duty_cycle > 1.0f) *duty_cycle = 1.0f;
    if (*duty_cycle < 0.0f) *duty_cycle = 0.0f;

    prev_power = power;
    return power;
}

int main() {
    float duty_cycle = 0.5f;
    float voltage, current, power;

    printf("迭代次数\t占空比\t\t电压(V)\t\t电流(A)\t\t功率(W)\n");
    printf("----------------------------------------------------------------\n");

    for (int i = 0; i < 10; i++) {
        voltage = 20.0f * duty_cycle;
        current = 5.0f * (1.0f - 0.5f * fabs(duty_cycle - 0.75f));

        power = mppt_perturb_and_observe(voltage, current, &duty_cycle);

        printf("%d\t\t%.4f\t\t%.4f\t\t%.4f\t\t%.4f\n", 
               i+1, duty_cycle, voltage, current, power);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define PI 3.14159265358979323846
#define SAMPLE_RATE 10000.0
#define GRID_FREQ 50.0
#define INITIAL_FREQ_ESTIMATE 49.5
#define KP 100.0
#define KI 5000.0
#define SIMULATION_TIME 0.1
#define NUM_SAMPLES (int)(SAMPLE_RATE * SIMULATION_TIME)
#define PRINT_INTERVAL 0.01
#define PRINT_SAMPLES (int)(SAMPLE_RATE * PRINT_INTERVAL)

typedef struct {
    double phase;           // 当前相位估计 (rad)
    double frequency;       // 当前频率估计 (Hz)
    double integrator;      // PI控制器的积分项
    double prev_error;      // 前一次误差
    double omega_nominal;   // 额定角频率 (rad/s)
} PLL_State;

void pll_init(PLL_State* pll) {
    pll->phase = 0.0;
    pll->frequency = INITIAL_FREQ_ESTIMATE;
    pll->integrator = 0.0;
    pll->prev_error = 0.0;
    pll->omega_nominal = 2.0 * PI * GRID_FREQ;
}

void pll_update(PLL_State* pll, double voltage_sample) {
    // 相位检测器：使用乘法鉴相器
    double v_ref = sin(pll->phase);
    double phase_error = voltage_sample * v_ref;

    // 环路滤波器：PI控制器
    double proportional = KP * phase_error;
    pll->integrator += KI * phase_error / SAMPLE_RATE;

    // 频率更新
    double freq_correction = proportional + pll->integrator;
    pll->frequency = GRID_FREQ + freq_correction;

    // 压控振荡器：积分得到相位
    double omega = 2.0 * PI * pll->frequency;
    pll->phase += omega / SAMPLE_RATE;

    // 相位卷绕处理：保持在0-2π范围内
    if (pll->phase >= 2.0 * PI) {
        pll->phase -= 2.0 * PI;
    } else if (pll->phase < 0.0) {
        pll->phase += 2.0 * PI;
    }

    pll->prev_error = phase_error;
}

double pll_get_phase(PLL_State* pll) {
    return pll->phase;
}

double pll_get_frequency(PLL_State* pll) {
    return pll->frequency;
}

int main() {
    PLL_State pll;
    pll_init(&pll);

    double time[NUM_SAMPLES];
    double voltage[NUM_SAMPLES];
    double freq_estimate[NUM_SAMPLES];
    double phase_estimate[NUM_SAMPLES];

    // 生成模拟电网电压信号
    for (int i = 0; i < NUM_SAMPLES; i++) {
        time[i] = i / SAMPLE_RATE;
        voltage[i] = sin(2.0 * PI * GRID_FREQ * time[i]);
    }

    // 运行PLL算法
    for (int i = 0; i < NUM_SAMPLES; i++) {
        pll_update(&pll, voltage[i]);
        freq_estimate[i] = pll_get_frequency(&pll);
        phase_estimate[i] = pll_get_phase(&pll);

        // 每10ms打印一次结果
        if (i % PRINT_SAMPLES == 0) {
            printf("Time: %.3fs, Freq: %.3fHz, Phase: %.3frad\n", 
                   time[i], freq_estimate[i], phase_estimate[i]);
        }
    }

    // 计算频率跟踪误差
    double freq_error_sum = 0.0;
    int stable_samples = 0;

    // 忽略前20ms的暂态过程
    int start_idx = (int)(0.02 * SAMPLE_RATE);
    for (int i = start_idx; i < NUM_SAMPLES; i++) {
        double error = freq_estimate[i] - GRID_FREQ;
        freq_error_sum += error * error;
        stable_samples++;
    }

    double rms_error = sqrt(freq_error_sum / stable_samples);
    printf("\n频率跟踪RMS误差: %.6fHz\n", rms_error);

    return 0;
}

