#define SQRT3 1.73205080757f

int determine_sector(float Ualpha, float Ubeta) {
    float A = Ubeta;
    float B = 0.5f * (SQRT3 * Ualpha - Ubeta);
    float C = -0.5f * (SQRT3 * Ualpha + Ubeta);

    if (A > 0 && C <= 0) return 1;
    if (A <= 0 && B > 0) return 2;
    if (B <= 0 && C > 0) return 3;
    if (A <= 0 && C > 0) return 4;
    if (A > 0 && B <= 0) return 5;
    if (B > 0 && C <= 0) return 6;

    return 1;
}

