#define D0 0.5
#define KP 0.1
#define KI 0.01
#define D_MIN 0.05
#define D_MAX 0.95
#define NUM_CYCLES 10

typedef struct {
    double Kp;
    double Ki;
    double integral;
    double last_duty;
} PI_Controller;

void pi_init(PI_Controller* pi, double Kp, double Ki) {
    pi->Kp = Kp;
    pi->Ki = Ki;
    pi->integral = 0.0;
    pi->last_duty = D0;
}

double pi_update(PI_Controller* pi, double error) {
    pi->integral += error;

    double delta_d = pi->Kp * error + pi->Ki * pi->integral;
    double new_duty = pi->last_duty + delta_d;

    if (new_duty < D_MIN) new_duty = D_MIN;
    if (new_duty > D_MAX) new_duty = D_MAX;

    pi->last_duty = new_duty;
    return new_duty;
}

double simulate_buck(double duty, double vin) {
    double noise = ((double)rand() / RAND_MAX) * 0.2 - 0.1;
    return duty * vin + noise;
}

int main() {
    srand(time(NULL));

    PI_Controller pi;
    pi_init(&pi, KP, KI);

    double vout_measured = simulate_buck(D0, VIN);
    double total_vout = 0.0;

    printf("Cycle\tDuty\t\tVout\n");
    printf("--------------------------------\n");

    for (int i = 0; i < NUM_CYCLES; i++) {
        double error = VREF - vout_measured;
        double duty = pi_update(&pi, error);

        vout_measured = simulate_buck(duty, VIN);
        total_vout += vout_measured;

        printf("%d\t%.6f\t%.6f\n", i+1, duty, vout_measured);
    }

    double avg_vout = total_vout / NUM_CYCLES;
    printf("\nFinal duty cycle: %.6f\n", pi.last_duty);
    printf("Average output voltage: %.6f\n", avg_vout);

    return 0;
}

