float dead_time_compensation(float duty_cycle, float dead_time_us, float switching_period_us) {
    if (duty_cycle > 0.5f) {
        return duty_cycle + dead_time_us / switching_period_us;
    } else if (duty_cycle < 0.5f) {
        return duty_cycle - dead_time_us / switching_period_us;
    } else {
        return duty_cycle;
    }
}

