        float original_duty = test_cases[i];
        float compensated_duty = dead_time_compensation(original_duty, DEAD_TIME_US, SWITCHING_PERIOD_US);

        printf("原始占空比: %.3f, 补偿后: %.3f\n", original_duty, compensated_duty);
