#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 8

typedef struct {
    uint16_t buffer[WINDOW_SIZE];
    uint8_t index;
    uint32_t sum;
    bool is_full;
} SlidingWindow;

void filter_init(SlidingWindow* window) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        window->buffer[i] = 0;
    }
    window->index = 0;
    window->sum = 0;
    window->is_full = false;
}

uint16_t filter_update(SlidingWindow* window, uint16_t new_sample) {
    if (window->is_full) {
        window->sum -= window->buffer[window->index];
    }

    window->buffer[window->index] = new_sample;
    window->sum += new_sample;

    window->index++;
    if (window->index >= WINDOW_SIZE) {
        window->index = 0;
        window->is_full = true;
    }

    uint8_t count = window->is_full ? WINDOW_SIZE : window->index;
    uint32_t avg = (window->sum + count/2) / count;
    return (uint16_t)avg;
}

int main() {
    SlidingWindow window;
    filter_init(&window);

    uint16_t samples[] = {100, 102, 98, 105, 103, 101, 99, 104, 102, 100};
    int sample_count = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < sample_count; i++) {
        uint16_t filtered = filter_update(&window, samples[i]);
        printf("采样值：[%d] 滤波后：[%d]\n", samples[i], filtered);
    }

    printf("\n最终窗口元素：");
    for (int i = 0; i < WINDOW_SIZE; i++) {
        printf("%d ", window.buffer[i]);
    }
    printf("\n");

    return 0;
}

#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846
#define KP 100.0
#define KI 1000.0
#define DT 0.001
#define INTEGRAL_LIMIT 1000.0

void clarke_transform(float a, float b, float c, float *alpha, float *beta) {
    *alpha = a;
    *beta = (b - c) / sqrtf(3.0f);
}

void park_transform(float alpha, float beta, float theta, float *d, float *q) {
    float cos_theta = cosf(theta);
    float sin_theta = sinf(theta);
    *d = alpha * cos_theta + beta * sin_theta;
    *q = -alpha * sin_theta + beta * cos_theta;
}

float pi_controller(float error, float kp, float ki, float *integral) {
    *integral += error * DT;
    if (*integral > INTEGRAL_LIMIT) *integral = INTEGRAL_LIMIT;
    if (*integral < -INTEGRAL_LIMIT) *integral = -INTEGRAL_LIMIT;
    return kp * error + ki * (*integral);
}

void pll_update(float va, float vb, float vc, float *theta, float *frequency, float dt) {
    static float integral = 0.0f;

    float alpha, beta;
    clarke_transform(va, vb, vc, &alpha, &beta);

    float d, q;
    park_transform(alpha, beta, *theta, &d, &q);

    float error = -q;
    float delta_freq = pi_controller(error, KP, KI, &integral);

    *frequency = 50.0f + delta_freq;
    *theta += 2.0f * PI * (*frequency) * dt;
    while (*theta > 2.0f * PI) *theta -= 2.0f * PI;
    while (*theta < 0) *theta += 2.0f * PI;
}

int main() {
    float theta_grid = 0.0f;
    float theta_pll = 0.0f;
    float freq_pll = 50.0f;

    for (int i = 0; i < 5; i++) {
        float va = sinf(theta_grid);
        float vb = sinf(theta_grid - 2.0f * PI / 3.0f);
        float vc = sinf(theta_grid + 2.0f * PI / 3.0f);

        pll_update(va, vb, vc, &theta_pll, &freq_pll, DT);

        printf("Step %d: theta_grid=%.6f, theta_pll=%.6f, freq=%.6f\n", 
               i+1, theta_grid, theta_pll, freq_pll);

        theta_grid += 0.1f;
    }

    return 0;
}

