typedef struct {
    double kp, ki, kd;
    double integral;
    double prev_error;
    double duty_cycle;
    double v_ref;
} BuckController;

void buck_init(BuckController* ctrl, double kp, double ki, double kd, double v_ref) {
    ctrl->kp = kp;
    ctrl->ki = ki;
    ctrl->kd = kd;
    ctrl->integral = 0.0;
    ctrl->prev_error = 0.0;
    ctrl->duty_cycle = 0.5;
    ctrl->v_ref = v_ref;
}

void buck_update(BuckController* ctrl, double v_measured, double dt) {
    double error = ctrl->v_ref - v_measured;

    ctrl->integral += error * dt;

    double derivative = (error - ctrl->prev_error) / dt;

    double output = ctrl->kp * error + ctrl->ki * ctrl->integral + ctrl->kd * derivative;

    if (output > 0.5) output = 0.5;
    if (output < -0.5) output = -0.5;

    ctrl->duty_cycle += output;

    if (ctrl->duty_cycle > 1.0) ctrl->duty_cycle = 1.0;
    if (ctrl->duty_cycle < 0.0) ctrl->duty_cycle = 0.0;

    ctrl->prev_error = error;
}

int main() {
    BuckController ctrl;
