#define EPS 1e-6
#define SQRT3_2 0.8660254037844386f

int svpwm_sector_detection(float Ualpha, float Ubeta) {
    float V1 = Ubeta;
    float V2 = SQRT3_2 * Ualpha - 0.5f * Ubeta;
    float V3 = -SQRT3_2 * Ualpha - 0.5f * Ubeta;

    int A = (V1 > EPS) ? 1 : 0;
    int B = (V2 > EPS) ? 1 : 0;
    int C = (V3 > EPS) ? 1 : 0;

    int N = A + 2 * B + 4 * C;

    switch (N) {
        case 3: return 1;
        case 1: return 2;
        case 5: return 3;
        case 4: return 4;
        case 6: return 5;
        case 2: return 6;
        default: return 0;
    }
}

int main() {
    float test_cases[6][2] = {
        {1.0f, 0.0f},
        {0.5f, 0.8660254037844386f},
        {-0.5f, 0.8660254037844386f},
        {-1.0f, 0.0f},
        {-0.5f, -0.8660254037844386f},
        {0.5f, -0.8660254037844386f}
    };

    int expected[6] = {1, 2, 3, 4, 5, 6};

    for (int i = 0; i < 6; i++) {
        float Ualpha = test_cases[i][0];
        float Ubeta = test_cases[i][1];
        int sector = svpwm_sector_detection(Ualpha, Ubeta);

        printf("测试用例 %d: (%.3f, %.3f) -> 扇区%d", 
               i+1, Ualpha, Ubeta, sector);

        if (sector == expected[i]) {
            printf(" ✓\n");
        } else {
            printf(" ✗ (期望: %d)\n", expected[i]);
        }
    }

    return 0;
}

