#define STEP_SIZE 0.01f
#define DUTY_MIN 0.05f
#define DUTY_MAX 0.95f

int mppt_po_step(float voltage, float current, float *duty_cycle) {
    static float p_old = 0.0f;
    static int last_direction = 0;
    static int first_run = 1;

    float p_new = voltage * current;

    if (first_run) {
        p_old = p_new;
        first_run = 0;
        return -1;
    }

    int direction = last_direction;

    if (p_new > p_old) {
        direction = last_direction;
    } else {
        direction = -last_direction;
    }

    if (direction == 0) {
        direction = 1;
    }

    float new_duty = *duty_cycle + direction * STEP_SIZE;

    if (new_duty < DUTY_MIN) {
        new_duty = DUTY_MIN;
        direction = 0;
    } else if (new_duty > DUTY_MAX) {
        new_duty = DUTY_MAX;
        direction = 0;
    }

    *duty_cycle = new_duty;
    last_direction = direction;
    p_old = p_new;

    if (direction > 0) return 0;
    if (direction < 0) return 1;
    return -1;
}

