#include <stdio.h>

double soc_ah_integration(double initial_soc, double capacity_ah, double *currents, double *timestamps, int n) {
    if (n <= 0 || capacity_ah <= 0.0) {
        return initial_soc;
    }

    double total_charge = 0.0;

    for (int i = 1; i < n; i++) {
        double dt = timestamps[i] - timestamps[i-1];
        if (dt <= 0.0) {
            continue;
        }
        double avg_current = (currents[i] + currents[i-1]) / 2.0;
        total_charge += avg_current * dt;
    }

    double soc_change = total_charge / (capacity_ah * 3600.0);
    double soc = initial_soc + soc_change;

    if (soc > 1.0) soc = 1.0;
    if (soc < 0.0) soc = 0.0;

    return soc;
}

