#include <stdio.h>
#include <math.h>

typedef struct {
    float kp;
    float ki;
    float kd;
    float error_prev;
    float error_prev2;
    float output;
} IncrementalPID;

void pid_init(IncrementalPID* pid, float kp, float ki, float kd) {
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->error_prev = 0.0f;
    pid->error_prev2 = 0.0f;
    pid->output = 0.0f;
}

float pid_update(IncrementalPID* pid, float setpoint, float measured) {
    float error = setpoint - measured;

    float delta_u = pid->kp * (error - pid->error_prev) +
                   pid->ki * error +
                   pid->kd * (error - 2.0f * pid->error_prev + pid->error_prev2);

    pid->output += delta_u;

    if (pid->output > 100.0f) {
        pid->output = 100.0f;
    } else if (pid->output < -100.0f) {
        pid->output = -100.0f;
    }

    pid->error_prev2 = pid->error_prev;
    pid->error_prev = error;

    return pid->output;
}

int main() {
    IncrementalPID pid;
    pid_init(&pid, 1.2f, 0.5f, 0.3f);

    float setpoint = 50.0f;
    float measured_values[] = {45.0f, 47.0f, 49.0f, 51.0f, 53.0f};
    int num_cycles = 5;

    for (int i = 0; i < num_cycles; i++) {
        float output = pid_update(&pid, setpoint, measured_values[i]);
        printf("周期 %d: 测量值=%.2f, 控制输出=%.2f\n", 
               i + 1, measured_values[i], output);
    }

    return 0;
}

#include <stdio.h>

#define Kp 0.05
#define Ki 0.001
#define VREF 5.0
#define DUTY_MIN 0.0
#define DUTY_MAX 0.9

typedef struct {
    float kp;
    float ki;
    float integral;
    float prev_error;
} PI_Controller;

void pi_controller_init(PI_Controller* pi, float kp, float ki) {
    pi->kp = kp;
    pi->ki = ki;
    pi->integral = 0.0;
    pi->prev_error = 0.0;
}

float pi_controller_update(PI_Controller* pi, float error) {
    pi->integral += error;

    float duty = pi->kp * error + pi->ki * pi->integral;

    if (duty < DUTY_MIN) duty = DUTY_MIN;
    if (duty > DUTY_MAX) duty = DUTY_MAX;

    return duty;
}

int main() {
    PI_Controller pi;
    pi_controller_init(&pi, Kp, Ki);

    float vout_meas = 0.0;

    for (int cycle = 1; cycle <= 5; cycle++) {
        float error = VREF - vout_meas;
        float duty = pi_controller_update(&pi, error);

        printf("周期%d: Vref=%.2fV, Vout=%.2fV, 误差=%.2fV, D=%.2f\n", 
               cycle, VREF, vout_meas, error, duty);

        vout_meas += 1.0;
    }

    return 0;
}

