#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846
#define TS 0.0001
#define F_GRID 50.0
#define A 1.0
#define INIT_PHASE 0.2
#define K_SOGI 1.414
#define KP 100.0
#define KI 1000.0
#define OMEGA_0 (2.0 * PI * F_GRID)

typedef struct {
    double u;
    double u_quad;
    double v1;
    double v2;
} SOGI_State;

typedef struct {
    double error;
    double integral;
    double omega_est;
    double theta_est;
} PLL_State;

void sogi_init(SOGI_State *s) {
    s->u = 0.0;
    s->u_quad = 0.0;
    s->v1 = 0.0;
    s->v2 = 0.0;
}

void sogi_update(SOGI_State *s, double input, double omega, double ts) {
    double k = K_SOGI;
    double v1_new = s->v1 + ts * (omega * s->v2 - k * omega * (s->v1 - input));
    double v2_new = s->v2 + ts * (-omega * s->v1);

    s->v1 = v1_new;
    s->v2 = v2_new;
    s->u = s->v1;
    s->u_quad = s->v2;
}

void pll_init(PLL_State *p) {
    p->error = 0.0;
    p->integral = 0.0;
    p->omega_est = OMEGA_0;
    p->theta_est = 0.0;
}

void pll_update(PLL_State *p, double u, double u_quad, double ts) {
    p->error = u * u_quad;

    p->integral += p->error * ts;

    p->omega_est = OMEGA_0 + KP * p->error + KI * p->integral;

    p->theta_est += p->omega_est * ts;

    if (p->theta_est > 2.0 * PI) {
        p->theta_est -= 2.0 * PI;
    }
    if (p->theta_est < 0) {
        p->theta_est += 2.0 * PI;
    }
}

int main() {
    SOGI_State sogi;
    PLL_State pll;

    sogi_init(&sogi);
    pll_init(&pll);

    printf("采样点, 输入电压, 估计频率(Hz), 估计相位(弧度)\n");

    for (int n = 0; n < 1000; n++) {
        double t = n * TS;
        double u_input = A * sin(2.0 * PI * F_GRID * t + INIT_PHASE);

        sogi_update(&sogi, u_input, pll.omega_est, TS);
        pll_update(&pll, sogi.u, sogi.u_quad, TS);

        if (n < 10) {
            printf("%d, %.6f, %.6f, %.6f\n", 
                   n, 
                   u_input, 
                   pll.omega_est / (2.0 * PI), 
                   pll.theta_est);
        }
    }

    return 0;
}

