// 定时器结构体定义
typedef struct {
    __IO uint32_t CR1;      // 控制寄存器1
    __IO uint32_t CR2;      // 控制寄存器2
    __IO uint32_t SMCR;     // 从模式控制寄存器
    __IO uint32_t DIER;     // DMA/中断使能寄存器
    __IO uint32_t SR;       // 状态寄存器
    __IO uint32_t EGR;      // 事件产生寄存器
    __IO uint32_t CCMR1;    // 捕获/比较模式寄存器1
    __IO uint32_t CCMR2;    // 捕获/比较模式寄存器2
    __IO uint32_t CCER;     // 捕获/比较使能寄存器
    __IO uint32_t CNT;      // 计数器
    __IO uint32_t PSC;      // 预分频器
    __IO uint32_t ARR;      // 自动重装载寄存器
    __IO uint32_t CCR1;     // 捕获/比较寄存器1
    __IO uint32_t CCR2;     // 捕获/比较寄存器2
    __IO uint32_t CCR3;     // 捕获/比较寄存器3
    __IO uint32_t CCR4;     // 捕获/比较寄存器4
} TIM_TypeDef;

// 函数声明
void TIM_PWM_Init(TIM_TypeDef* TIMx, uint32_t prescaler, uint32_t period, uint32_t pulse);
void TIM_PWM_Start(TIM_TypeDef* TIMx, uint8_t channel);
void TIM_PWM_SetDutyCycle(TIM_TypeDef* TIMx, uint8_t channel, uint32_t pulse);
void print_registers(TIM_TypeDef* TIMx);

void TIM_PWM_Init(TIM_TypeDef* TIMx, uint32_t prescaler, uint32_t period, uint32_t pulse) {
    // 1. 配置预分频器和自动重装载值
    TIMx->PSC = prescaler;
    TIMx->ARR = period;

    // 2. 配置通道1为PWM模式1
    // 清除OC1M位
    TIMx->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    // 设置OC1M为PWM模式1
    TIMx->CCMR1 |= (TIM_OCMODE_PWM1 << TIM_CCMR1_OC1M_Pos);
    // 使能预装载寄存器
    TIMx->CCMR1 |= TIM_CCMR1_OC1PE_Msk;

    // 3. 配置通道2为PWM模式1
    TIMx->CCMR1 &= ~TIM_CCMR1_OC2M_Msk;
    TIMx->CCMR1 |= (TIM_OCMODE_PWM1 << TIM_CCMR1_OC2M_Pos);
    TIMx->CCMR1 |= TIM_CCMR1_OC2PE_Msk;

    // 4. 配置通道3为PWM模式1
    TIMx->CCMR2 &= ~TIM_CCMR2_OC3M_Msk;
    TIMx->CCMR2 |= (TIM_OCMODE_PWM1 << TIM_CCMR2_OC3M_Pos);
    TIMx->CCMR2 |= TIM_CCMR2_OC3PE_Msk;

    // 5. 配置通道4为PWM模式1
    TIMx->CCMR2 &= ~TIM_CCMR2_OC4M_Msk;
    TIMx->CCMR2 |= (TIM_OCMODE_PWM1 << TIM_CCMR2_OC4M_Pos);
    TIMx->CCMR2 |= TIM_CCMR2_OC4PE_Msk;

    // 6. 设置初始脉冲宽度
    TIMx->CCR1 = pulse;
    TIMx->CCR2 = pulse;
    TIMx->CCR3 = pulse;
    TIMx->CCR4 = pulse;

    // 7. 使能ARR预装载
    TIMx->CR1 |= TIM_CR1_ARPE_Msk;

    // 8. 初始化计数器
    TIMx->CNT = 0;
}

void TIM_PWM_Start(TIM_TypeDef* TIMx, uint8_t channel) {
    switch(channel) {
        case 1:
            // 使能通道1输出
            TIMx->CCER |= TIM_CCER_CC1E_Msk;
            // 设置输出极性为高电平有效
            TIMx->CCER &= ~TIM_CCER_CC1P_Msk;
            break;
        case 2:
            TIMx->CCER |= TIM_CCER_CC2E_Msk;
            TIMx->CCER &= ~TIM_CCER_CC2P_Msk;
            break;
        case 3:
            TIMx->CCER |= TIM_CCER_CC3E_Msk;
            TIMx->CCER &= ~TIM_CCER_CC3P_Msk;
            break;
        case 4:
            TIMx->CCER |= TIM_CCER_CC4E_Msk;
            TIMx->CCER &= ~TIM_CCER_CC4P_Msk;
            break;
        default:
            return;
    }

    // 使能定时器计数器
    TIMx->CR1 |= TIM_CR1_CEN_Msk;
}

void TIM_PWM_SetDutyCycle(TIM_TypeDef* TIMx, uint8_t channel, uint32_t pulse) {
    if (pulse > TIMx->ARR) {
        pulse = TIMx->ARR;  // 限制脉冲宽度不超过周期
    }

    switch(channel) {
        case 1:
            TIMx->CCR1 = pulse;
            break;
        case 2:
            TIMx->CCR2 = pulse;
            break;
        case 3:
            TIMx->CCR3 = pulse;
            break;
        case 4:
            TIMx->CCR4 = pulse;
            break;
        default:
            return;
    }
}

