#include <stdio.h>

typedef struct {
    double Vin;
    double Vout;
    double Vref;
    double D;
    double Kp;
    double Ki;
    double integral_sum;
    double Ts;
} BuckConverter;

void buck_update(BuckConverter *conv) {
    double error = conv->Vref - conv->Vout;
    conv->integral_sum += error * conv->Ts;
    double D_new = conv->Kp * error + conv->Ki * conv->integral_sum;
    if (D_new < 0.0) D_new = 0.0;
    if (D_new > 1.0) D_new = 1.0;
    conv->D = D_new;
    conv->Vout = conv->D * conv->Vin;
}

int main() {
    BuckConverter conv = {
        .Vin = 12.0,
        .Vout = 0.0,
        .Vref = 5.0,
        .D = 0.0,
        .Kp = 0.1,
        .Ki = 2.0,
        .integral_sum = 0.0,
        .Ts = 0.001
    };

    for (int i = 0; i < 10; i++) {
        buck_update(&conv);
        printf("Cycle %d: D=%.3f, Vout=%.3f\n", i, conv.D, conv.Vout);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// 滑动窗口大小
#define WINDOW_SIZE 10

// 滑动窗口结构体
typedef struct {
    int buffer[WINDOW_SIZE];  // 数据缓冲区
    int index;                // 当前写入位置
    int count;                // 当前有效数据个数
    int sum;                  // 当前窗口内数据总和
} SlidingWindow;

// 初始化滑动窗口
void init_window(SlidingWindow *window) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        window->buffer[i] = 0;  // 初始化为0
    }
    window->index = 0;
    window->count = 0;
    window->sum = 0;
}

// 滑动平均滤波函数
int sliding_average_filter(SlidingWindow *window, int new_sample) {
    // 如果窗口已满，先减去即将被替换的旧值
    if (window->count == WINDOW_SIZE) {
        window->sum -= window->buffer[window->index];
    } else {
        window->count++;
    }

    // 添加新值到窗口
    window->buffer[window->index] = new_sample;
    window->sum += new_sample;

    // 更新索引（循环缓冲区）
    window->index = (window->index + 1) % WINDOW_SIZE;

    // 计算平均值（整数除法）
    return window->sum / window->count;
}

int main() {
    SlidingWindow window;
    init_window(&window);

    // 模拟ADC采样值
