#define PI 3.14159265358979323846f
#define SQRT3 1.73205080756887729352f
#define BASE_FREQ 314.1592653589793f  // 50Hz * 2π
#define KP 100.0f
#define KI 1000.0f
#define INTEGRAL_LIMIT 100.0f

static float error_integral = 0.0f;

void pll_update(float ua, float ub, float uc, float dt, float *theta) {
    float u_alpha = ua;
    float u_beta = (ub - uc) / SQRT3;

    float cos_theta = cosf(*theta);
    float sin_theta = sinf(*theta);

    float u_d = u_alpha * cos_theta + u_beta * sin_theta;
    float u_q = -u_alpha * sin_theta + u_beta * cos_theta;

    float error = u_q;

    error_integral += error * dt;
    if (error_integral > INTEGRAL_LIMIT) error_integral = INTEGRAL_LIMIT;
    if (error_integral < -INTEGRAL_LIMIT) error_integral = -INTEGRAL_LIMIT;

    float freq_increment = KP * error + KI * error_integral;

    *theta += (BASE_FREQ + freq_increment) * dt;

    while (*theta >= 2.0f * PI) *theta -= 2.0f * PI;
    while (*theta < 0.0f) *theta += 2.0f * PI;
}

