        float ub = sinf(angle + 2.0f * PI / 3.0f);
        float uc = sinf(angle + 4.0f * PI / 3.0f);

        pll_update(ua, ub, uc, dt, &theta);
        printf("Step %d: theta = %.6f rad (%.2f deg)\n", i+1, theta, theta * 180.0f / PI);
    }

    return 0;
}

