#define PWM_DUTY (*((volatile unsigned int*)0x40000004))

static double integral = 0.0;
static const double dt = 0.001;

double pi_controller(double error, double kp, double ki) {
    integral += error * dt;

    if (integral > 1000.0) integral = 1000.0;
    if (integral < -1000.0) integral = -1000.0;

    double delta = kp * error + ki * integral;

    if (delta > 0.2) delta = 0.2;
    if (delta < -0.2) delta = -0.2;

    return delta;
}

