    if (module->status == 2) return;

    if (cycle == 1) {
        module->health_score = 85;
    } else if (cycle == 2) {
        module->health_score = 75;
    } else if (cycle == 3) {
        module->health_score = 55;
    } else if (cycle == 4) {
        module->health_score = 45;
    } else if (cycle == 5) {
