        module->status = 2;
        module->health_score = 0;
    }
}

int need_switch(Module* main_module, Module* backup_module) {
    if (main_module->status == 2) return 1;
    if (main_module->health_score < HEALTH_THRESHOLD && backup_module->status != 2) return 1;
    return 0;
}

void switch_modules(Module* main_module, Module* backup_module) {
    int temp_id = main_module->id;
    int temp_health = main_module->health_score;

    main_module->id = backup_module->id;
    main_module->health_score = backup_module->health_score;
    main_module->status = 1;
    main_module->output_power = TOTAL_POWER;

    backup_module->id = temp_id;
    backup_module->health_score = temp_health;
    backup_module->status = 0;
    backup_module->output_power = 0;
}

void print_status(int cycle, Module* main_module, Module* backup_module) {
    printf("周期%d: 主模块[id=%d]功率=%dW, 备用模块[id=%d]功率=%dW, 健康度:主=%d/备=%d\n",
           cycle, main_module->id, main_module->output_power,
           backup_module->id, backup_module->output_power,
           main_module->health_score, backup_module->health_score);
}

int main() {
    Module module1, module2;
    Module *current_main, *current_backup;

    init_modules(&module1, &module2);
    current_main = &module1;
    current_backup = &module2;

    for (int cycle = 1; cycle <= 5; cycle++) {
        print_status(cycle, current_main, current_backup);

        update_health(current_main, cycle);
        update_health(current_backup, cycle);

        if (need_switch(current_main, current_backup)) {
            printf("周期%d: [切换事件] ", cycle);
            if (current_main->status == 2) {
                printf("主模块故障，切换到模块%d...\n", current_backup->id);
            } else {
                printf("主模块健康度不足，切换到模块%d...\n", current_backup->id);
            }

            switch_modules(current_main, current_backup);

            Module* temp = current_main;
            current_main = current_backup;
            current_backup = temp;

            printf("       新状态: 主模块[id=%d]功率=%dW, 备用模块[id=%d]功率=%dW\n",
                   current_main->id, current_main->output_power,
                   current_backup->id, current_backup->output_power);
        }
    }

    return 0;
}

#include <stdio.h>

typedef struct {
    double current_freq;
    double target_freq;
    double kp_fast;
    double ki_fast;
    double kp_stable;
    double ki_stable;
    double integral_error;
    int is_fast_mode;
} PLL_Controller;

void pll_init(PLL_Controller *pll, double init_freq) {
    pll->current_freq = init_freq;
    pll->target_freq = 0.0;
    pll->kp_fast = 2.0;
    pll->ki_fast = 1.0;
    pll->kp_stable = 0.5;
    pll->ki_stable = 0.1;
    pll->integral_error = 0.0;
    pll->is_fast_mode = 0;
}

void pll_set_target(PLL_Controller *pll, double target) {
    pll->target_freq = target;
}

void pll_set_mode(PLL_Controller *pll, int fast_mode) {
    pll->is_fast_mode = fast_mode;
}

void pll_update(PLL_Controller *pll, double measured_freq, double dt) {
    double error = pll->target_freq - measured_freq;
    pll->integral_error += error * dt;

    double kp, ki;
    if (pll->is_fast_mode) {
        kp = pll->kp_fast;
        ki = pll->ki_fast;
    } else {
        kp = pll->kp_stable;
        ki = pll->ki_stable;
    }

    double freq_adjust = kp * error + ki * pll->integral_error;
    pll->current_freq += freq_adjust * dt;
}

int main() {
    PLL_Controller pll;

    pll_init(&pll, 50.0);
    pll_set_target(&pll, 60.0);

    double dt = 0.1;
    double measured_freq = 50.0;

    printf("Starting with fast tracking mode:\n");
    pll_set_mode(&pll, 1);
    for (int i = 0; i < 5; i++) {
        pll_update(&pll, measured_freq, dt);
        printf("Fast mode: meas=%.2f, target=%.2f, current=%.2f\n", 
               measured_freq, pll.target_freq, pll.current_freq);
    }

    printf("\nSwitching to stable tracking mode:\n");
    pll_set_mode(&pll, 0);
    for (int i = 0; i < 5; i++) {
        pll_update(&pll, measured_freq, dt);
        printf("Stable mode: meas=%.2f, target=%.2f, current=%.2f\n", 
               measured_freq, pll.target_freq, pll.current_freq);
    }

    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FAULTS 100
#define FAULT_FILE "fault_log.bin"

typedef struct {
    uint32_t fault_code;
    uint32_t timestamp;
    uint8_t fault_level;
    uint8_t is_read;
} FaultRecord;

typedef struct {
    FaultRecord records[MAX_FAULTS];
    uint32_t write_index;
    uint32_t read_index;
    uint32_t count;
    uint32_t unread_count;
} FaultLogSystem;

void fault_log_init(FaultLogSystem *sys) {
    memset(sys, 0, sizeof(FaultLogSystem));

    FILE *file = fopen(FAULT_FILE, "rb");
    if (file) {
        fread(sys, sizeof(FaultLogSystem), 1, file);
        fclose(file);
    }
}

void fault_log_save(FaultLogSystem *sys) {
    FILE *file = fopen(FAULT_FILE, "wb");
    if (file) {
        fwrite(sys, sizeof(FaultLogSystem), 1, file);
        fclose(file);
    }
}

void fault_log_add(FaultLogSystem *sys, uint32_t fault_code, uint8_t fault_level) {
    if (sys->count >= MAX_FAULTS) {
        sys->read_index = (sys->read_index + 1) % MAX_FAULTS;
        sys->count--;
        if (sys->records[sys->read_index].is_read == 0) {
            sys->unread_count--;
        }
    }

    FaultRecord *record = &sys->records[sys->write_index];
    record->fault_code = fault_code;
    record->timestamp = (uint32_t)time(NULL);
    record->fault_level = fault_level;
    record->is_read = 0;

    sys->write_index = (sys->write_index + 1) % MAX_FAULTS;
    sys->count++;
    sys->unread_count++;

    fault_log_save(sys);
}

int fault_log_read_earliest(FaultLogSystem *sys, FaultRecord *record) {
    if (sys->unread_count == 0) {
        return 0;
    }

    while (sys->records[sys->read_index].is_read) {
        sys->read_index = (sys->read_index + 1) % MAX_FAULTS;
    }

    *record = sys->records[sys->read_index];
    sys->records[sys->read_index].is_read = 1;
    sys->unread_count--;

    fault_log_save(sys);
    return 1;
}

uint32_t fault_log_get_count(FaultLogSystem *sys) {
    return sys->count;
}

uint32_t fault_log_get_unread_count(FaultLogSystem *sys) {
    return sys->unread_count;
}

void fault_log_clear(FaultLogSystem *sys) {
    memset(sys, 0, sizeof(FaultLogSystem));
    remove(FAULT_FILE);
}

void print_fault_record(FaultRecord *record) {
    printf("Fault Code: 0x%08X, Timestamp: %u, Level: %u, Status: %s\n",
           record->fault_code, record->timestamp, 
           record->fault_level, record->is_read ? "Read" : "Unread");
}

int main() {
    FaultLogSystem sys;
    FaultRecord record;

    printf("=== Test 1: Initialize System ===\n");
    fault_log_init(&sys);
    printf("Current fault count: %u, Unread count: %u\n\n", 
           fault_log_get_count(&sys), fault_log_get_unread_count(&sys));

    printf("=== Test 2: Add Multiple Fault Records ===\n");
    for (int i = 0; i < 105; i++) {
        fault_log_add(&sys, 0x1000 + i, i % 4);
        printf("Add fault %d: code=0x%04X, level=%d\n", 
               i + 1, 0x1000 + i, i % 4);
    }
    printf("Total faults: %u (should be <=100)\n", fault_log_get_count(&sys));
    printf("Unread faults: %u\n\n", fault_log_get_unread_count(&sys));

    printf("=== Test 3: Read Fault Records ===\n");
    uint32_t read_count = 0;
    while (fault_log_read_earliest(&sys, &record)) {
        printf("Read record %u: ", ++read_count);
        print_fault_record(&record);
    }
    printf("Total read: %u records\n", read_count);
    printf("Unread after reading: %u\n\n", fault_log_get_unread_count(&sys));

    printf("=== Test 4: Clear and Re-add Records ===\n");
    fault_log_clear(&sys);
    printf("Fault count after clear: %u\n", fault_log_get_count(&sys));

    fault_log_add(&sys, 0x2001, 2);
    fault_log_add(&sys, 0x2002, 1);
    fault_log_add(&sys, 0x2003, 3);

    printf("After adding 3 new records:\n");
    printf("Fault count: %u, Unread count: %u\n", 
           fault_log_get_count(&sys), fault_log_get_unread_count(&sys));

    printf("\n=== Test 5: Read Newly Added Records ===\n");
    while (fault_log_read_earliest(&sys, &record)) {
        print_fault_record(&record);
    }

    printf("\n=== Test Complete ===\n");
    return 0;
}

