    float delta_V;
    int mode;
} BidirectionalConverter;

void update_mode(BidirectionalConverter *conv) {
    float V_charge = conv->V_ref - conv->delta_V;
    float V_discharge = conv->V_ref + conv->delta_V;

    if (conv->mode == 0) {
        if (conv->V_batt > V_discharge) {
            conv->mode = 1;
        }
    } else {
        if (conv->V_batt < V_charge) {
            conv->mode = 0;
        }
    }
}

