    printf("  当前电压: %.2fV, 目标电压: %.2fV\n", current_voltage, target_voltage);

    adjust_pwm_for_emi(current_voltage, target_voltage, &pwm_duty);

    printf("  调整后占空比: %.3f\n", pwm_duty);
    printf("  电压差: %.2fV\n\n", current_voltage - target_voltage);
}

