#define PERIOD_VALUE 1000

typedef struct {
    uint32_t phase_register;
    uint32_t period_register;
    uint8_t is_master;
} PWM_Module;

void pwm_counter_update(PWM_Module *modules, int num_modules) {
    int master_triggered = 0;

    for (int i = 0; i < num_modules; i++) {
        if (modules[i].is_master) {
            uint32_t old_phase = modules[i].phase_register;
            modules[i].phase_register++;
            if (modules[i].phase_register >= modules[i].period_register) {
                modules[i].phase_register = 0;
                if (old_phase == modules[i].period_register - 1) {
                    master_triggered = 1;
                }
            }
        } else {
            modules[i].phase_register++;
            if (modules[i].phase_register >= modules[i].period_register) {
                modules[i].phase_register = 0;
            }
        }
    }

    if (master_triggered) {
        for (int i = 0; i < num_modules; i++) {
            if (!modules[i].is_master) {
                modules[i].phase_register = 0;
            }
        }
    }
}

int main() {
    PWM_Module modules[3];

    modules[0].phase_register = 0;
    modules[0].period_register = PERIOD_VALUE;
    modules[0].is_master = 1;

    modules[1].phase_register = 0;
    modules[1].period_register = PERIOD_VALUE;
    modules[1].is_master = 0;

    modules[2].phase_register = 0;
    modules[2].period_register = PERIOD_VALUE;
    modules[2].is_master = 0;

    printf("Initial state:\n");
    printf("Step 0: Master=%u, Slave1=%u, Slave2=%u\n", 
           modules[0].phase_register, modules[1].phase_register, modules[2].phase_register);

    for (int step = 1; step <= 10; step++) {
        pwm_counter_update(modules, 3);
        printf("Step %d: Master=%u, Slave1=%u, Slave2=%u\n", 
               step, modules[0].phase_register, modules[1].phase_register, modules[2].phase_register);
    }

    int steps_to_sync = 0;
    while (modules[0].phase_register != PERIOD_VALUE - 1) {
        pwm_counter_update(modules, 3);
        steps_to_sync++;
    }

    pwm_counter_update(modules, 3);
    printf("[SYNC EVENT] Master reached period, all slaves reset!\n");
    printf("Step %d: Master=%u, Slave1=%u, Slave2=%u\n", 
           10 + steps_to_sync + 1, modules[0].phase_register, modules[1].phase_register, modules[2].phase_register);

    for (int step = 1; step <= 5; step++) {
        pwm_counter_update(modules, 3);
        printf("Step %d: Master=%u, Slave1=%u, Slave2=%u\n", 
               10 + steps_to_sync + 1 + step, modules[0].phase_register, modules[1].phase_register, modules[2].phase_register);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

typedef struct {
    float kp;
    float ki;
    float kd;
    float integral_limit;
    float output_limit;
    float integral;
    float last_error;
    float last_measurement;
} PIDController;

void PID_Init(PIDController *pid, float kp, float ki, float kd, float integral_limit, float output_limit) {
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral_limit = integral_limit;
    pid->output_limit = output_limit;
    pid->integral = 0.0f;
    pid->last_error = 0.0f;
    pid->last_measurement = 0.0f;
}

float PID_Update(PIDController *pid, float setpoint, float measurement) {
    float error = setpoint - measurement;

    float proportional = pid->kp * error;

    if (fabs(error) < pid->integral_limit) {
        pid->integral += pid->ki * error;
    }

    float derivative = -pid->kd * (measurement - pid->last_measurement);

    float output = proportional + pid->integral + derivative;

    if (output > pid->output_limit) {
        output = pid->output_limit;
    } else if (output < -pid->output_limit) {
        output = -pid->output_limit;
    }

    pid->last_error = error;
    pid->last_measurement = measurement;

    return output;
}

int main() {
    PIDController pid;
    PID_Init(&pid, 1.0f, 0.1f, 0.05f, 5.0f, 10.0f);

    float setpoint = 10.0f;
    float measurement = 0.0f;

    printf("PID Positional Controller with Integral Separation and Derivative on Measurement\n");
    printf("================================================================================\n");

    for (int step = 1; step <= 20; step++) {
        float output = PID_Update(&pid, setpoint, measurement);

        printf("Step %2d: setpoint=%.2f, measurement=%.2f, output=%.2f\n", 
               step, setpoint, measurement, output);

        measurement += output * 0.1f;
    }

    printf("\nFinal state: integral=%.2f, last_error=%.2f, last_measurement=%.2f\n",
           pid.integral, pid.last_error, pid.last_measurement);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    float V_pv;
    float I_pv;
    float P_pv;
} PVArray;

void update_pv_characteristics(PVArray* pv, float duty_cycle) {
    pv->V_pv = 40.0f - 15.0f * duty_cycle;
    pv->I_pv = 8.0f - 3.0f * duty_cycle;
    pv->P_pv = pv->V_pv * pv->I_pv;
}

float mppt_perturb_observe(PVArray* pv, float prev_power, float prev_duty) {
    float step = 0.01f;
    float new_duty = prev_duty;

    if (pv->P_pv > prev_power) {
        new_duty = prev_duty + step;
    } else {
        new_duty = prev_duty - step;
    }

    if (new_duty < 0.1f) new_duty = 0.1f;
    if (new_duty > 0.9f) new_duty = 0.9f;

    return new_duty;
}

int main() {
    PVArray pv;
    pv.V_pv = 30.0f;
    pv.I_pv = 5.0f;
    pv.P_pv = pv.V_pv * pv.I_pv;

    float duty_cycle = 0.5f;
    float prev_power = 0.0f;
    float max_power = 0.0f;
    float max_duty = 0.0f;
    float max_V = 0.0f;
    float max_I = 0.0f;

    printf("PV MPPT Simulation (Perturb and Observe Algorithm)\n");
    printf("==================================================\n");

    for (int i = 1; i <= 10; i++) {
        update_pv_characteristics(&pv, duty_cycle);
        pv.P_pv = pv.V_pv * pv.I_pv;

        if (i == 1) {
            prev_power = pv.P_pv;
        }

        printf("Iteration %d: V=%.2fV, I=%.2fA, P=%.2fW, D=%.2f\n", 
               i, pv.V_pv, pv.I_pv, pv.P_pv, duty_cycle);

        if (pv.P_pv > max_power) {
            max_power = pv.P_pv;
            max_duty = duty_cycle;
            max_V = pv.V_pv;
            max_I = pv.I_pv;
        }

        float new_duty = mppt_perturb_observe(&pv, prev_power, duty_cycle);
        prev_power = pv.P_pv;
        duty_cycle = new_duty;
    }

    printf("\nMax power point: V=%.2fV, I=%.2fA, P=%.2fW at D=%.2f\n",
           max_V, max_I, max_power, max_duty);

    return 0;
}

#include <stdio.h>
#include <math.h>

double trapezoidal_integral(const double *samples, int n, double dt) {
    if (n <= 1) return 0.0;

    double sum = 0.5 * samples[0] + 0.5 * samples[n-1];
    for (int i = 1; i < n-1; i++) {
        sum += samples[i];
    }
    return sum * dt;
}

int main() {
    printf("Trapezoidal Integration Test\n");
    printf("============================\n\n");

    // Test case 1: Constant signal f(t)=2.0
    {
        const int n = 10;
        double dt = 0.1;
        double samples[n];
        for (int i = 0; i < n; i++) {
            samples[i] = 2.0;
        }
        double result = trapezoidal_integral(samples, n, dt);
        double expected = 2.0;
        double error = fabs(result - expected);

        printf("Test 1: Constant signal f(t)=2.0\n");
        printf("  Samples: %d, dt=%.2f\n", n, dt);
        printf("  Computed: %.6f\n", result);
        printf("  Expected: %.6f\n", expected);
        printf("  Absolute error: %.6e\n\n", error);
    }

    // Test case 2: Ramp signal f(t)=t
    {
        const int n = 5;
        double dt = 0.5;
        double samples[n];
        for (int i = 0; i < n; i++) {
            samples[i] = i * dt;  // t starts from 0
        }
        double result = trapezoidal_integral(samples, n, dt);
        double expected = 2.5;  // ∫₀²t dt = 0.5*t²|₀² = 2.0, but sampling to t=2.0
        double error = fabs(result - expected);

        printf("Test 2: Ramp signal f(t)=t\n");
        printf("  Samples: %d, dt=%.2f\n", n, dt);
        printf("  Computed: %.6f\n", result);
        printf("  Expected: %.6f\n", expected);
        printf("  Absolute error: %.6e\n\n", error);
    }

    // Test case 3: Sine signal f(t)=sin(t)
    {
        const int n = 4;
        double dt = 3.14159265358979323846 / 6.0;  // π/6
        double samples[n];
        for (int i = 0; i < n; i++) {
            samples[i] = sin(i * dt);
        }
        double result = trapezoidal_integral(samples, n, dt);
        double expected = 0.8966;  // ∫₀^(π/2) sin(t) dt = 1 - cos(π/2) = 1.0
        double error = fabs(result - expected);

        printf("Test 3: Sine signal f(t)=sin(t)\n");
        printf("  Samples: %d, dt=π/6≈%.6f\n", n, dt);
        printf("  Computed: %.6f\n", result);
        printf("  Expected: %.6f\n", expected);
        printf("  Absolute error: %.6e\n", error);
    }

    return 0;
}

