#define CARRIER_FREQUENCY 10000.0f  // 10kHz固定载波频率

float calculateSPWMDutyCycle(float time, float frequency, float modulationIndex) {
    // 计算正弦调制波值
    float sine_value = sinf(2.0f * (float)M_PI * frequency * time);

    // 计算占空比：duty = 0.5 + 0.5 * modulationIndex * sin(2πft)
    float duty = 0.5f + 0.5f * modulationIndex * sine_value;

    // 限制在0.0到1.0范围内
    if (duty < 0.0f) {
        duty = 0.0f;
    } else if (duty > 1.0f) {
        duty = 1.0f;
    }

    return duty;
}

int main() {
    // 定义测试用例数组
    struct TestCase {
        float frequency;
        float modulationIndex;
        float time;
    } testCases[] = {
        {50.0f, 0.8f, 0.005f},      // 正常情况：50Hz, 调制比0.8, 时间5ms
        {60.0f, 0.9f, 0.002f},      // 正常情况：60Hz, 调制比0.9, 时间2ms
        {0.0f, 1.2f, 0.001f},       // 边界条件：频率0Hz, 调制比1.2(超调)
        {50.0f, 0.0f, 0.01f},       // 边界条件：调制比为0
        {50.0f, 1.0f, 0.0f},        // 边界条件：时间为0
        {100.0f, 0.5f, 0.001f},     // 高频情况
        {25.0f, 1.1f, 0.0025f},     // 调制比超调测试
    };

    int numCases = sizeof(testCases) / sizeof(testCases[0]);

    printf("异步调制SPWM占空比计算测试（载波频率固定为%.0f Hz）\n", CARRIER_FREQUENCY);
    printf("====================================================\n");

    for (int i = 0; i < numCases; i++) {
        float duty = calculateSPWMDutyCycle(
            testCases[i].time,
            testCases[i].frequency,
            testCases[i].modulationIndex
        );

        printf("频率=%.1f Hz, 调制比=%.2f, 时间=%.4f s => 占空比=%.6f\n",
               testCases[i].frequency,
               testCases[i].modulationIndex,
               testCases[i].time,
               duty);
    }

    // 额外测试：验证正弦波周期特性
    printf("\n正弦波周期特性验证（50Hz, 调制比0.8）：\n");
    float freq = 50.0f;
    float mi = 0.8f;
    float period = 1.0f / freq;

    for (int i = 0; i < 5; i++) {
        float t = i * period / 4.0f;  // 0°, 90°, 180°, 270°, 360°
        float duty = calculateSPWMDutyCycle(t, freq, mi);
        printf("  时间=%.4f s (相位=%d°) => 占空比=%.6f\n", t, i * 90, duty);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846

void calculate_chebyshev_coeffs(double fc, double fs, double Rp, double *b, double *a) {
    double wp = 2.0 * PI * fc;
    double T = 1.0 / fs;

    double epsilon = sqrt(pow(10.0, Rp/10.0) - 1.0);

    double beta = asinh(1.0/epsilon) / 2.0;
    double eta = sinh(beta);
    double xi = cosh(beta);

    double wc = 2.0 / T * tan(wp * T / 2.0);

    double s1_real = -eta * wc;
    double s1_imag = xi * wc;
    double s2_real = -eta * wc;
    double s2_imag = -xi * wc;

    double z1_real = (1.0 + s1_real * T/2.0) / (1.0 - s1_real * T/2.0);
    double z1_imag = (s1_imag * T/2.0) / (1.0 - s1_real * T/2.0);
    double z2_real = (1.0 + s2_real * T/2.0) / (1.0 - s2_real * T/2.0);
    double z2_imag = (s2_imag * T/2.0) / (1.0 - s2_real * T/2.0);

    double z1_mag_sq = z1_real*z1_real + z1_imag*z1_imag;
    double z2_mag_sq = z2_real*z2_real + z2_imag*z2_imag;

    b[0] = 1.0;
    b[1] = -2.0 * z1_real;
    b[2] = z1_mag_sq;

    a[0] = 1.0;
    a[1] = -2.0 * z2_real;
    a[2] = z2_mag_sq;

    double norm = a[0];
    b[0] /= norm;
    b[1] /= norm;
    b[2] /= norm;
    a[1] /= norm;
    a[2] /= norm;
}

double chebyshev_filter(double input, double *state, const double *coeff) {
    double b0 = coeff[0];
    double b1 = coeff[1];
    double b2 = coeff[2];
    double a1 = coeff[3];
    double a2 = coeff[4];

    double w0 = input - a1 * state[0] - a2 * state[1];
    double output = b0 * w0 + b1 * state[0] + b2 * state[1];

    state[1] = state[0];
    state[0] = w0;

    return output;
}

int main() {
    double fc = 100.0;
    double fs = 1000.0;
    double Rp = 1.0;

    double b[3], a[3];
    calculate_chebyshev_coeffs(fc, fs, Rp, b, a);

    printf("Chebyshev Type I Lowpass Filter Coefficients:\n");
    printf("b0 = %.6f, b1 = %.6f, b2 = %.6f\n", b[0], b[1], b[2]);
    printf("a0 = 1.000000, a1 = %.6f, a2 = %.6f\n", a[1], a[2]);

    double coeff[5] = {b[0], b[1], b[2], a[1], a[2]};
    double state[2] = {0.0, 0.0};

    printf("\nTest Signal (50Hz + 150Hz sine waves):\n");
    printf("Input samples and filtered output:\n");

    for (int i = 0; i < 10; i++) {
        double t = i / fs;
        double input = sin(2.0 * PI * 50.0 * t) + sin(2.0 * PI * 150.0 * t);
        double output = chebyshev_filter(input, state, coeff);

        printf("Sample %d: Input = %.6f, Output = %.6f\n", i, input, output);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <string.h>

#define PI 3.14159265358979323846

void repetitive_control(double *error_buffer, int buffer_len, double *output, double k_r) {
    static int write_idx = 0;
    static double prev_output = 0.0;

    double current_error = error_buffer[write_idx];
    double new_output = k_r * (prev_output + current_error) + (1 - k_r) * prev_output;

    *output = new_output;
    prev_output = new_output;

    write_idx = (write_idx + 1) % buffer_len;
}

int main() {
    double fs = 10000.0;
    double f0 = 50.0;
    int buffer_len = (int)(fs / f0);

    double error_buffer[buffer_len];
    memset(error_buffer, 0, sizeof(error_buffer));

    int total_samples = 5 * buffer_len;
    double Ts = 1.0 / fs;

    int write_idx = 0;
    double output;

    for (int cycle = 0; cycle < 5; cycle++) {
        double max_output = -1e9;
        double min_output = 1e9;

        for (int i = 0; i < buffer_len; i++) {
            double t = (cycle * buffer_len + i) * Ts;
            double error = 0.1 * sin(2 * PI * 50 * t) + 0.05 * sin(2 * PI * 150 * t);

            error_buffer[write_idx] = error;

            repetitive_control(error_buffer, buffer_len, &output, 0.5);

            if (output > max_output) max_output = output;
            if (output < min_output) min_output = output;

            write_idx = (write_idx + 1) % buffer_len;
        }

        printf("周期 %d: 输出最大值 = %.6f, 输出最小值 = %.6f\n", 
               cycle + 1, max_output, min_output);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define KP 2.0
#define KI 0.5
#define INTEGRAL_MIN -500
#define INTEGRAL_MAX 500
#define ADJUSTMENT_MIN -100
#define ADJUSTMENT_MAX 100
#define PWM_MIN 0
#define PWM_MAX 1000

int pwm_duty = 500;
float integral = 0.0;

int pi_controller(int current_adc, int target_adc) {
    int error = target_adc - current_adc;

    integral += error;

    if (integral < INTEGRAL_MIN) {
        integral = INTEGRAL_MIN;
    } else if (integral > INTEGRAL_MAX) {
        integral = INTEGRAL_MAX;
    }

    float adjustment_float = KP * error + KI * integral;
    int adjustment = (int)adjustment_float;

    if (adjustment < ADJUSTMENT_MIN) {
        adjustment = ADJUSTMENT_MIN;
    } else if (adjustment > ADJUSTMENT_MAX) {
        adjustment = ADJUSTMENT_MAX;
    }

    return adjustment;
}

void update_pwm_duty(int adjustment) {
    int new_duty = pwm_duty + adjustment;

    if (new_duty < PWM_MIN) {
        new_duty = PWM_MIN;
    } else if (new_duty > PWM_MAX) {
        new_duty = PWM_MAX;
    }

    pwm_duty = new_duty;
}

int main() {
    int test_cases[] = {300, 600, 450, 700, 512};
    int target_adc = 512;
    int num_tests = sizeof(test_cases) / sizeof(test_cases[0]);

    for (int i = 0; i < num_tests; i++) {
        int current_adc = test_cases[i];
        int adjustment = pi_controller(current_adc, target_adc);
        update_pwm_duty(adjustment);

        printf("ADC:%d, Target:%d, Adjustment:%+d, PWM:%d\n", 
               current_adc, target_adc, adjustment, pwm_duty);
    }

    return 0;
}

#include <stdio.h>
#include <stdbool.h>

typedef struct {
    float current_freq;
    float target_freq;
    bool is_locked;
    float phase_error;
} GridInverter;

void detect_grid_frequency(GridInverter *inv, float measured_freq) {
    inv->current_freq = measured_freq;
    if (measured_freq >= 45.0f && measured_freq <= 55.0f) {
        inv->is_locked = true;
    } else {
        inv->is_locked = false;
    }
}

void adaptive_control(GridInverter *inv) {
    if (!inv->is_locked) {
        inv->target_freq = 0.0f;
        return;
    }

    float freq = inv->current_freq;

    if (freq >= 49.5f && freq <= 50.5f) {
        inv->target_freq = 50.0f;
    } else if (freq >= 45.0f && freq < 49.5f) {
        inv->target_freq = 50.0f + (50.0f - freq) * 0.3f;
    } else if (freq > 50.5f && freq <= 55.0f) {
        inv->target_freq = 50.0f - (freq - 50.0f) * 0.3f;
    }

    if (inv->target_freq < 45.0f) inv->target_freq = 45.0f;
    if (inv->target_freq > 55.0f) inv->target_freq = 55.0f;
}

void update_phase(GridInverter *inv) {
    if (!inv->is_locked) {
        inv->phase_error = 0.0f;
        return;
    }
    inv->phase_error = (inv->target_freq - inv->current_freq) * 10.0f;
}

