#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <time.h>

#define PI 3.14159265358979323846

typedef struct {
    unsigned long timestamp;
    float voltage;
    float frequency;
} InverterSample;

int detect_distortion(InverterSample samples[], int n, float threshold) {
    if (n <= 0) return 0;

    float Vm = 0.0;
    for (int i = 0; i < n; i++) {
        float abs_voltage = fabsf(samples[i].voltage);
        if (abs_voltage > Vm) {
            Vm = abs_voltage;
        }
    }

    if (Vm < 0.001) return 0;

    float f = samples[0].frequency;
    float phi = asinf(samples[0].voltage / Vm);

    int distortion_count = 0;

    for (int i = 0; i < n; i++) {
        float t = samples[i].timestamp / 1000.0;
        float theoretical = Vm * sinf(2 * PI * f * t + phi);
        float actual = samples[i].voltage;
        float deviation = fabsf(actual - theoretical);

        if (deviation > threshold) {
            distortion_count++;
        }
    }

    return distortion_count;
}

void generate_normal_waveform(InverterSample samples[], int n, float frequency, float peak_voltage) {
    float time_step = 1000.0 / (frequency * 20);

    for (int i = 0; i < n; i++) {
        samples[i].timestamp = i * time_step;
        samples[i].frequency = frequency;
        float t = samples[i].timestamp / 1000.0;
        samples[i].voltage = peak_voltage * sinf(2 * PI * frequency * t);
    }
}

void generate_distorted_waveform(InverterSample samples[], int n, float frequency, float peak_voltage) {
    srand(time(NULL));

    float time_step = 1000.0 / (frequency * 20);

    for (int i = 0; i < n; i++) {
        samples[i].timestamp = i * time_step;
        samples[i].frequency = frequency;
        float t = samples[i].timestamp / 1000.0;
        float ideal = peak_voltage * sinf(2 * PI * frequency * t);

        if (rand() % 10 < 3) {
            float distortion = (rand() % 100) / 100.0 * peak_voltage * 0.3;
            if (rand() % 2 == 0) {
                samples[i].voltage = ideal + distortion;
            } else {
                samples[i].voltage = ideal - distortion;
            }
        } else {
            samples[i].voltage = ideal;
        }
    }
}

int main() {
    const int sample_count = 200;
    float threshold = 10.0;

    printf("Inverter Voltage Distortion Detection Algorithm Test\n");
    printf("====================================================\n\n");

    InverterSample normal_samples[sample_count];
    InverterSample distorted_samples[sample_count];

    generate_normal_waveform(normal_samples, sample_count, 50.0, 311.0);
    generate_distorted_waveform(distorted_samples, sample_count, 50.0, 311.0);

    printf("Test Case 1: Normal Waveform (50Hz, Peak 311V)\n");
    int normal_distortion = detect_distortion(normal_samples, sample_count, threshold);
    printf("Total Samples: %d\n", sample_count);
    printf("Distortion Points: %d\n", normal_distortion);
    printf("Distortion Ratio: %.2f%%\n\n", (float)normal_distortion / sample_count * 100);

    printf("Test Case 2: Distorted Waveform (50Hz, Peak 311V)\n");
    int distorted_distortion = detect_distortion(distorted_samples, sample_count, threshold);
    printf("Total Samples: %d\n", sample_count);
    printf("Distortion Points: %d\n", distorted_distortion);
    printf("Distortion Ratio: %.2f%%\n\n", (float)distorted_distortion / sample_count * 100);

    printf("Test Case 3: Severe Distortion Waveform\n");
    InverterSample severe_samples[sample_count];
    generate_normal_waveform(severe_samples, sample_count, 50.0, 311.0);
    for (int i = 50; i < 100; i++) {
        severe_samples[i].voltage = severe_samples[i].voltage * 0.5;
    }
    for (int i = 150; i < 180; i++) {
        severe_samples[i].voltage = severe_samples[i].voltage + 100.0;
    }
    int severe_distortion = detect_distortion(severe_samples, sample_count, threshold);
    printf("Total Samples: %d\n", sample_count);
    printf("Distortion Points: %d\n", severe_distortion);
    printf("Distortion Ratio: %.2f%%\n\n", (float)severe_distortion / sample_count * 100);

    printf("Threshold Setting: %.2f V\n", threshold);
    printf("Detection Complete\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <complex.h>

#define PI 3.14159265358979323846

void fft(double complex x[], int n) {
    if (n <= 1) return;

    double complex even[n/2];
    double complex odd[n/2];

    for (int i = 0; i < n/2; i++) {
        even[i] = x[2*i];
        odd[i] = x[2*i + 1];
    }

    fft(even, n/2);
    fft(odd, n/2);

    for (int k = 0; k < n/2; k++) {
        double complex t = cexp(-I * 2.0 * PI * k / n) * odd[k];
        x[k] = even[k] + t;
        x[k + n/2] = even[k] - t;
    }
}

void harmonic_analysis(double complex fft_result[], int n, double fundamental_freq) {
    double fs = fundamental_freq * n;
    double df = fs / n;

    printf("谐波分析结果（幅值，单位：V）：\n");

    for (int h = 1; h <= 15; h++) {
        double freq = h * fundamental_freq;
        int index = (int)round(freq / df);

        if (index >= 0 && index < n/2) {
            double amplitude = 2.0 * cabs(fft_result[index]) / n;
            printf("第%d次谐波（%.0f Hz）：%.3f V\n", h, freq, amplitude);
        }
    }
}

int main() {
    int N = 256;
    double fs = 12800.0;
    double T = 1.0 / fs;

    double complex signal[N];

    for (int i = 0; i < N; i++) {
        double t = i * T;
        signal[i] = 1.0 * sin(2 * PI * 50 * t) + 
                    0.3 * sin(2 * PI * 150 * t) + 
                    0.2 * sin(2 * PI * 250 * t) + 
                    0.1 * sin(2 * PI * 350 * t);
    }

    fft(signal, N);

    printf("前8个频率分量的幅值（单位：V）：\n");
    for (int i = 0; i < 8; i++) {
        double amplitude = 2.0 * cabs(signal[i]) / N;
        double freq = i * fs / N;
        printf("频率 %.1f Hz：%.3f V\n", freq, amplitude);
    }

    printf("\n");
    harmonic_analysis(signal, N, 50.0);

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

// 桥臂状态枚举
typedef enum {
    LEADING_ARM_ON,
    LAGGING_ARM_ON,
    BOTH_OFF,
    BOTH_ON
} BridgeState;

// 移相控制器结构体
typedef struct {
    double f_sw;           // 开关频率 (Hz)
    double t_dead;         // 死区时间 (秒)
    double duty_ratio;     // 移相比 (0.0-1.0)
    double phase_shift;    // 移相角 (度)
    BridgeState state;     // 当前桥臂状态
    double t_on_leading;   // 超前桥臂导通时间 (秒)
    double t_on_lagging;   // 滞后桥臂导通时间 (秒)
    double t_off_leading;  // 超前桥臂关断时间 (秒)
    double t_off_lagging;  // 滞后桥臂关断时间 (秒)
} PhaseShiftController;

// 初始化控制器
void init_controller(PhaseShiftController *ctrl, double f_sw, double t_dead, double duty_ratio) {
    ctrl->f_sw = f_sw;
    ctrl->t_dead = t_dead;
    ctrl->duty_ratio = duty_ratio;
    ctrl->phase_shift = 0.0;
    ctrl->state = BOTH_OFF;

    // 计算开关周期
    double t_sw = 1.0 / f_sw;

    // 计算导通时间
    double t_on = duty_ratio * t_sw;

    // 初始化导通时序
    ctrl->t_on_leading = 0.0;
    ctrl->t_on_lagging = 0.0;
    ctrl->t_off_leading = t_on;
    ctrl->t_off_lagging = t_on;
}

// 根据负载电流判断ZVS是否可实现
int calculate_zvs_condition(PhaseShiftController *ctrl, double i_load) {
    // 计算开关周期
    double t_sw = 1.0 / ctrl->f_sw;

    // 计算导通时间
    double t_on = ctrl->duty_ratio * t_sw;

    // 计算移相角对应的延迟时间
    double t_phase_shift = (ctrl->phase_shift / 180.0) * t_sw;

    // 计算滞后桥臂实现ZVS所需的最小电流
    // 假设：需要足够的电流在死区时间内对寄生电容放电
    // 简化模型：i_min = C * V / t_dead，其中C为寄生电容，V为母线电压
    // 这里使用经验公式：i_min = 0.5 * (t_dead / t_sw) * 10.0

    double i_min_zvs = 0.5 * (ctrl->t_dead / t_sw) * 10.0;

    // 对于滞后桥臂实现ZVS，需要负载电流足够大（正电流）
    // 同时需要考虑移相角的影响：移相角越大，实现ZVS越困难
    double phase_factor = 1.0 - (ctrl->phase_shift / 180.0) * 0.5;

    // 调整最小电流要求
    i_min_zvs = i_min_zvs / phase_factor;

    // 判断ZVS条件
    if (fabs(i_load) >= i_min_zvs) {
        // 还需要检查电流方向：对于滞后桥臂，通常需要正电流
        // 简化判断：电流绝对值足够大即可
        return 1;
    } else {
        return 0;
    }
}

// 更新移相角并重新计算导通时序
void update_phase_shift(PhaseShiftController *ctrl, double phase_shift) {
    // 限制移相角范围在0-180度
    if (phase_shift < 0.0) phase_shift = 0.0;
    if (phase_shift > 180.0) phase_shift = 180.0;

    ctrl->phase_shift = phase_shift;

    // 计算开关周期
    double t_sw = 1.0 / ctrl->f_sw;

    // 计算导通时间
    double t_on = ctrl->duty_ratio * t_sw;

    // 计算移相角对应的延迟时间
    double t_phase_shift = (phase_shift / 180.0) * t_sw;

    // 更新导通时序
    // 超前桥臂：在周期开始时导通
    ctrl->t_on_leading = 0.0;
    ctrl->t_off_leading = t_on;

    // 滞后桥臂：延迟移相角时间后导通
    ctrl->t_on_lagging = t_phase_shift;
    ctrl->t_off_lagging = t_phase_shift + t_on;

    // 如果导通时间超过周期，进行调整
    if (ctrl->t_off_lagging > t_sw) {
        ctrl->t_off_lagging = t_sw;
    }
}

int main() {
    PhaseShiftController ctrl;

    // 初始化控制器参数
    init_controller(&ctrl, 100000.0, 200e-9, 0.4);

    printf("全桥变换器移相控制ZVS算法测试\n");
    printf("开关频率: %.0f Hz\n", ctrl.f_sw);
    printf("死区时间: %.0f ns\n", ctrl.t_dead * 1e9);
    printf("移相比: %.2f\n", ctrl.duty_ratio);
    printf("\n");

    // 测试不同移相角下的ZVS条件
    double phase_shifts[] = {0.0, 45.0, 90.0, 135.0, 180.0};
    int num_phases = sizeof(phase_shifts) / sizeof(phase_shifts[0]);

    for (int p = 0; p < num_phases; p++) {
        update_phase_shift(&ctrl, phase_shifts[p]);

        printf("移相角: %.1f 度\n", phase_shifts[p]);
        printf("负载电流测试:\n");

        // 测试负载电流从-5A到5A变化
        for (double i_load = -5.0; i_load <= 5.0; i_load += 1.0) {
            int zvs_possible = calculate_zvs_condition(&ctrl, i_load);

            printf("  负载电流: %5.2f A, ZVS状态: %s\n", 
                   i_load, 
                   zvs_possible ? "可实现" : "不可实现");
        }
        printf("\n");
    }

    // 详细测试特定移相角下的临界电流
    printf("临界电流测试 (移相角=90度):\n");
    update_phase_shift(&ctrl, 90.0);

    for (double i_load = 0.0; i_load <= 2.0; i_load += 0.1) {
        int zvs_possible = calculate_zvs_condition(&ctrl, i_load);

        if (zvs_possible) {
            printf("  临界电流约为: %.2f A\n", i_load);
            break;
        }
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

typedef struct {
    float target_freq;
    float estimated_freq;
    int mode;
    float stable_k;
    float fast_k;
    float threshold;
} PLL_Controller;

void pll_init(PLL_Controller *pll, float target, float stable_k, float fast_k, float th) {
    pll->target_freq = target;
    pll->estimated_freq = target;
    pll->mode = 0;
    pll->stable_k = stable_k;
    pll->fast_k = fast_k;
    pll->threshold = th;
}

void pll_update(PLL_Controller *pll, float measured_freq) {
    float error = measured_freq - pll->target_freq;
    float abs_error = fabsf(error);

    if (abs_error > pll->threshold) {
        pll->mode = 1;
    } else {
        pll->mode = 0;
    }

    float k = (pll->mode == 1) ? pll->fast_k : pll->stable_k;
    pll->estimated_freq += k * (measured_freq - pll->estimated_freq);
}

int main() {
    PLL_Controller pll;
    pll_init(&pll, 50.0, 0.1, 0.5, 2.0);

    float measurements[] = {48.0, 49.0, 50.5, 51.0, 50.0};
    int steps = sizeof(measurements) / sizeof(measurements[0]);

    for (int i = 0; i < steps; i++) {
        pll_update(&pll, measurements[i]);
        printf("Step %d: meas=%.2f, est=%.2f, mode=%d\n", 
               i+1, measurements[i], pll.estimated_freq, pll.mode);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define HOLDING_REGISTERS_SIZE 100
uint16_t holding_registers[HOLDING_REGISTERS_SIZE] = {0};

uint16_t crc16_modbus(uint8_t* data, uint16_t length) {
    uint16_t crc = 0xFFFF;
    for (uint16_t i = 0; i < length; i++) {
        crc ^= (uint16_t)data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x0001) {
                crc = (crc >> 1) ^ 0xA001;
            } else {
                crc = crc >> 1;
            }
        }
    }
    return crc;
}

uint8_t* modbus_slave_process(uint8_t* request, uint16_t req_len, uint16_t* resp_len) {
    if (req_len < 6) return NULL;

    uint16_t crc_received = (request[req_len-1] << 8) | request[req_len-2];
    uint16_t crc_calculated = crc16_modbus(request, req_len-2);

    if (crc_received != crc_calculated) return NULL;

    uint8_t slave_addr = request[0];
    uint8_t function_code = request[1];

    uint8_t* response = NULL;

    if (function_code == 0x03) {
        uint16_t start_addr = (request[2] << 8) | request[3];
        uint16_t reg_count = (request[4] << 8) | request[5];

        if (start_addr + reg_count > HOLDING_REGISTERS_SIZE) return NULL;

        uint8_t byte_count = reg_count * 2;
        *resp_len = 5 + byte_count + 2;
        response = (uint8_t*)malloc(*resp_len);

        response[0] = slave_addr;
        response[1] = 0x03;
        response[2] = byte_count;

        for (uint16_t i = 0; i < reg_count; i++) {
            uint16_t reg_value = holding_registers[start_addr + i];
            response[3 + i*2] = (reg_value >> 8) & 0xFF;
            response[4 + i*2] = reg_value & 0xFF;
        }

        uint16_t crc = crc16_modbus(response, *resp_len - 2);
        response[*resp_len - 2] = crc & 0xFF;
        response[*resp_len - 1] = (crc >> 8) & 0xFF;

    } else if (function_code == 0x06) {
        uint16_t reg_addr = (request[2] << 8) | request[3];
        uint16_t reg_value = (request[4] << 8) | request[5];

        if (reg_addr >= HOLDING_REGISTERS_SIZE) return NULL;

        holding_registers[reg_addr] = reg_value;

        *resp_len = req_len;
        response = (uint8_t*)malloc(*resp_len);
        memcpy(response, request, *resp_len);

    } else {
        return NULL;
    }

    return response;
}

int main() {
    printf("Modbus RTU Slave Test\n");
    printf("=====================\n\n");

    uint16_t resp_len;

    printf("Test 1: Function Code 0x06 (Write Single Register)\n");
    printf("--------------------------------------------------\n");
    uint8_t write_request[] = {
        0x01, 0x06, 0x00, 0x02, 0x12, 0x34, 0x00, 0x00
    };
    uint16_t write_crc = crc16_modbus(write_request, 6);
    write_request[6] = write_crc & 0xFF;
    write_request[7] = (write_crc >> 8) & 0xFF;

    uint8_t* write_response = modbus_slave_process(write_request, 8, &resp_len);
    if (write_response) {
        printf("Write Response (%d bytes): ", resp_len);
        for (uint16_t i = 0; i < resp_len; i++) {
            printf("%02X ", write_response[i]);
        }
        printf("\n");
        free(write_response);
    } else {
        printf("Write request failed!\n");
    }

    printf("\nTest 2: Function Code 0x03 (Read Holding Registers)\n");
    printf("---------------------------------------------------\n");
    uint8_t read_request[] = {
        0x01, 0x03, 0x00, 0x02, 0x00, 0x02, 0x00, 0x00
    };
    uint16_t read_crc = crc16_modbus(read_request, 6);
    read_request[6] = read_crc & 0xFF;
    read_request[7] = (read_crc >> 8) & 0xFF;

    uint8_t* read_response = modbus_slave_process(read_request, 8, &resp_len);
    if (read_response) {
        printf("Read Response (%d bytes): ", resp_len);
        for (uint16_t i = 0; i < resp_len; i++) {
            printf("%02X ", read_response[i]);
        }
        printf("\n");
        free(read_response);
    } else {
        printf("Read request failed!\n");
    }

    printf("\nTest 3: Verify Register Values\n");
    printf("------------------------------\n");
    printf("holding_registers[2] = 0x%04X (%d)\n", holding_registers[2], holding_registers[2]);
    printf("holding_registers[3] = 0x%04X (%d)\n", holding_registers[3], holding_registers[3]);

    return 0;
}

#include <stdio.h>
#include <stdbool.h>

typedef struct {
    float dc_voltage;
    float output_voltage[3];
    float output_current[3];
    float temperature;
    int fault_status;
} InverterState;

int detect_fault(InverterState *inv, float v_high, float v_low, float i_max, float t_max) {
    if (inv->dc_voltage > v_high) {
        inv->fault_status = 1;
    } else if (inv->dc_voltage < v_low) {
        inv->fault_status = 2;
    } else {
        bool overcurrent = false;
        for (int i = 0; i < 3; i++) {
            if (inv->output_current[i] > i_max) {
                overcurrent = true;
                break;
            }
        }
        if (overcurrent) {
            inv->fault_status = 3;
        } else if (inv->temperature > t_max) {
            inv->fault_status = 4;
        } else {
            inv->fault_status = 0;
        }
    }
    return inv->fault_status;
}

void protection_action(int fault_status) {
    switch (fault_status) {
        case 0:
            printf("正常运行\n");
            break;
        case 1:
            printf("过压保护：封锁PWM，断开接触器\n");
            break;
        case 2:
            printf("欠压保护：降频运行，报警\n");
            break;
        case 3:
            printf("过流保护：立即封锁PWM\n");
            break;
        case 4:
            printf("过热保护：降低载波比，启动风扇\n");
            break;
        default:
            printf("未知故障\n");
            break;
    }
}

int main() {
