               test_cases[i].output_current[2],
               test_cases[i].temperature);

        int fault = detect_fault(&test_cases[i], v_high, v_low, i_max, t_max);
        printf("检测到故障: ");
        switch (fault) {
            case 0: printf("正常\n"); break;
            case 1: printf("过压\n"); break;
            case 2: printf("欠压\n"); break;
            case 3: printf("过流\n"); break;
            case 4: printf("过热\n"); break;
        }

        printf("保护动作: ");
        protection_action(fault);
        printf("\n");
    }

    return 0;
}

