    print_channel_samples();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define Q_MAX 5000.0  // mAh
#define R_BAT 0.05    // Ohm
#define DT 1.0        // s

typedef struct {
    double x;      // 状态估计值 (SOC)
    double P;      // 误差协方差
    double Q;      // 过程噪声协方差
    double R;      // 观测噪声协方差
} KalmanFilter;

double ocv(double soc) {
    return 3.0 + 0.5 * soc;
}

void kalman_init(KalmanFilter *kf, double init_soc, double init_P, double Q, double R) {
    kf->x = init_soc;
    kf->P = init_P;
    kf->Q = Q;
    kf->R = R;
}

void kalman_predict(KalmanFilter *kf, double I, double dt) {
    double current_ah = I * dt / 3600.0;
    kf->x = kf->x + current_ah / (Q_MAX / 1000.0);
    kf->P = kf->P + kf->Q;
}

void kalman_update(KalmanFilter *kf, double V_meas, double I) {
    double H = 0.5;
    double y = V_meas - (ocv(kf->x) + I * R_BAT);
    double S = kf->P * H * H + kf->R;
    double K = kf->P * H / S;

    kf->x = kf->x + K * y;
    kf->P = (1.0 - K * H) * kf->P;
}

double gaussian_noise(double mean, double stddev) {
    double u1 = (rand() + 1.0) / (RAND_MAX + 1.0);
    double u2 = (rand() + 1.0) / (RAND_MAX + 1.0);
    double z = sqrt(-2.0 * log(u1)) * cos(2.0 * 3.141592653589793 * u2);
    return mean + stddev * z;
}

int main() {
    srand(time(NULL));

    KalmanFilter kf;
    double init_soc = 0.5;
    double init_P = 0.1;
    double process_noise_std = 0.01;
    double obs_noise_std = 0.05;

    kalman_init(&kf, init_soc, init_P, process_noise_std * process_noise_std, 
                obs_noise_std * obs_noise_std);

    double true_soc = init_soc;
    double total_error = 0.0;

    printf("Time Step | True SOC | Measured V | Estimated SOC\n");
    printf("--------------------------------------------\n");

    for (int k = 0; k < 10; k++) {
        double I = -2.0 + 4.0 * rand() / RAND_MAX;

        double w_k = gaussian_noise(0.0, process_noise_std);
        double v_k = gaussian_noise(0.0, obs_noise_std);

        double current_ah = I * DT / 3600.0;
        true_soc = true_soc + current_ah / (Q_MAX / 1000.0);

        if (true_soc > 1.0) true_soc = 1.0;
        if (true_soc < 0.0) true_soc = 0.0;

        double V_true = ocv(true_soc) + I * R_BAT;
        double V_meas = V_true + v_k;

        kalman_predict(&kf, I, DT);
        kalman_update(&kf, V_meas, I);

        if (kf.x > 1.0) kf.x = 1.0;
        if (kf.x < 0.0) kf.x = 0.0;

        double error = fabs(true_soc - kf.x);
        total_error += error;

        printf("%9d | %8.4f | %10.4f | %12.4f\n", 
               k+1, true_soc, V_meas, kf.x);
    }

    printf("--------------------------------------------\n");
    printf("Average estimation error: %.4f\n", total_error / 10.0);

    return 0;
}

#include <stdio.h>
#include <stdbool.h>

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float prev_error;
    float out_min;
    float out_max;
} PIDController;

void PID_Init(PIDController *pid, float Kp, float Ki, float Kd, float out_min, float out_max) {
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->out_min = out_min;
    pid->out_max = out_max;
}

float PID_Update(PIDController *pid, float setpoint, float measurement, float dt) {
    float error = setpoint - measurement;

    pid->integral += error * dt;

    float derivative = (error - pid->prev_error) / dt;

    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    bool saturation = false;
    if (output > pid->out_max) {
        output = pid->out_max;
        saturation = true;
    } else if (output < pid->out_min) {
        output = pid->out_min;
        saturation = true;
    }

    if (saturation) {
        pid->integral -= error * dt;
    }

    pid->prev_error = error;

    return output;
}

int main() {
    PIDController pid;
    PID_Init(&pid, 0.5f, 0.1f, 0.01f, 0.0f, 1.0f);

    float setpoint = 5.0f;
    float measurement = 4.8f;
    float dt = 0.001f;

    for (int i = 0; i < 5; i++) {
        float output = PID_Update(&pid, setpoint, measurement, dt);
        printf("Cycle %d: measurement=%.2fV, PID_output=%.3f\n", i+1, measurement, output);
        measurement += 0.05f;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 100

typedef struct {
    unsigned long timestamp;
    float Kp;
    float Ki;
    float Kd;
    float error;
    float output;
} PID_Record;

void add_record(PID_Record records[], int *count, float Kp, float Ki, float Kd, float error, float output) {
    if (*count >= MAX_RECORDS) {
        return;
    }

    static unsigned long last_timestamp = 0;
    records[*count].timestamp = last_timestamp + 100;
    last_timestamp = records[*count].timestamp;

    records[*count].Kp = Kp;
    records[*count].Ki = Ki;
    records[*count].Kd = Kd;
    records[*count].error = error;
    records[*count].output = output;

    (*count)++;
}

void print_trend(PID_Record records[], int count) {
    printf("=== PID参数历史记录 ===\n");
    printf("时间戳(ms) | Kp     | Ki     | Kd     | 误差    | 输出\n");
    printf("--------------------------------------------------------\n");

    for (int i = 0; i < count; i++) {
        printf("%10lu | %6.2f | %6.2f | %6.2f | %7.2f | %6.2f\n",
               records[i].timestamp,
               records[i].Kp,
               records[i].Ki,
               records[i].Kd,
               records[i].error,
               records[i].output);
    }

    if (count >= 3) {
        float moving_avg = (records[count-1].output + records[count-2].output + records[count-3].output) / 3.0f;
        printf("\n移动平均输出：%.2f\n", moving_avg);
    } else if (count > 0) {
        float sum = 0;
        for (int i = 0; i < count; i++) {
            sum += records[i].output;
        }
        printf("\n移动平均输出：%.2f\n", sum / count);
    }
}

void analyze_overshoot(PID_Record records[], int count) {
    printf("\n=== 超调分析 ===\n");

    int overshoot_count = 0;
    const float setpoint = 0.0f;
    const float overshoot_threshold = 0.1f;

    for (int i = 0; i < count; i++) {
        float target_error = setpoint - records[i].error;
        float overshoot_percentage = (records[i].output - target_error) / target_error;

        if (target_error != 0 && overshoot_percentage > overshoot_threshold) {
            if (overshoot_count == 0) {
                printf("发现超调记录：\n");
                printf("时间戳(ms) | 输出   | 目标误差 | 超调百分比\n");
                printf("--------------------------------------------\n");
            }
            printf("%10lu | %6.2f | %8.2f | %10.1f%%\n",
                   records[i].timestamp,
                   records[i].output,
                   target_error,
                   overshoot_percentage * 100);
            overshoot_count++;
        }
    }

    if (overshoot_count == 0) {
        printf("无超调记录\n");
    }
}

int main() {
    PID_Record records[MAX_RECORDS];
    int count = 0;

    add_record(records, &count, 1.0f, 0.1f, 0.01f, -5.0f, 25.0f);
    add_record(records, &count, 1.2f, 0.15f, 0.02f, -3.0f, 18.0f);
    add_record(records, &count, 1.5f, 0.2f, 0.03f, -1.5f, 12.0f);
    add_record(records, &count, 1.8f, 0.25f, 0.04f, -0.5f, 8.0f);
    add_record(records, &count, 2.0f, 0.3f, 0.05f, 0.2f, 5.0f);

    print_trend(records, count);
    analyze_overshoot(records, count);

    return 0;
}

#include <stdio.h>
#include <math.h>

#define MAX_SAMPLES 5000
#define SAMPLE_TIME 0.01

typedef struct {
    double kp;
    double ki;
    double kd;
    double integral;
    double prev_error;
} PIDController;

typedef struct {
    double a;
    double b;
    double prev_output;
} Plant;

typedef struct {
    double ku;
    double tu;
} ZNResult;

void pid_init(PIDController *pid, double kp, double ki, double kd) {
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0.0;
    pid->prev_error = 0.0;
}

double pid_update(PIDController *pid, double error, double dt) {
    pid->integral += error * dt;
    double derivative = (error - pid->prev_error) / dt;
    double output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    pid->prev_error = error;
    return output;
}

void plant_init(Plant *plant, double a, double b) {
    plant->a = a;
    plant->b = b;
    plant->prev_output = 0.0;
}

double plant_update(Plant *plant, double input) {
    double output = plant->a * plant->prev_output + plant->b * input;
    plant->prev_output = output;
    return output;
}

int detect_oscillation(double *output_history, int count, double *period) {
    if (count < 100) return 0;

    int peak_count = 0;
    int peak_indices[10];

    for (int i = 50; i < count - 1; i++) {
        if (output_history[i] > output_history[i-1] && output_history[i] > output_history[i+1]) {
            if (peak_count < 10) {
                peak_indices[peak_count++] = i;
            }
        }
    }

    if (peak_count < 3) return 0;

    double period_sum = 0.0;
    for (int i = 1; i < peak_count; i++) {
        period_sum += (peak_indices[i] - peak_indices[i-1]) * SAMPLE_TIME;
    }

    *period = period_sum / (peak_count - 1);

    double avg_amplitude = 0.0;
    for (int i = 0; i < peak_count; i++) {
        avg_amplitude += fabs(output_history[peak_indices[i]]);
    }
    avg_amplitude /= peak_count;

    double amplitude_var = 0.0;
    for (int i = 0; i < peak_count; i++) {
        double diff = fabs(output_history[peak_indices[i]]) - avg_amplitude;
        amplitude_var += diff * diff;
    }
    amplitude_var = sqrt(amplitude_var / peak_count);

    return (amplitude_var / avg_amplitude < 0.05);
}

ZNResult zn_tuning(double plant_a, double plant_b, double setpoint) {
    ZNResult result = {0.0, 0.0};
    double kp_start = 0.1;
    double kp_step = 0.1;
    double kp_max = 20.0;

    for (double kp = kp_start; kp <= kp_max; kp += kp_step) {
        PIDController pid;
        Plant plant;

        pid_init(&pid, kp, 0.0, 0.0);
        plant_init(&plant, plant_a, plant_b);

        double output_history[MAX_SAMPLES];
        int sample_count = 0;
        double output = 0.0;

        for (int i = 0; i < MAX_SAMPLES; i++) {
            double error = setpoint - output;
            double control = pid_update(&pid, error, SAMPLE_TIME);
            output = plant_update(&plant, control);
            output_history[sample_count++] = output;

            if (i > 300) {
                double period;
                if (detect_oscillation(output_history, sample_count, &period)) {
                    result.ku = kp;
                    result.tu = period;
                    return result;
                }
            }
        }
    }

    return result;
}

void print_results(ZNResult result, int test_case) {
    printf("Test Case %d:\n", test_case);
    printf("Critical Gain Ku = %.2f, Critical Period Tu = %.2fs\n", result.ku, result.tu);
    printf("P Controller: Kp=%.2f\n", 0.5 * result.ku);
    printf("PI Controller: Kp=%.2f, Ti=%.2fs\n", 0.45 * result.ku, result.tu / 1.2);
    printf("PID Controller: Kp=%.2f, Ti=%.2fs, Td=%.2fs\n\n", 
           0.6 * result.ku, result.tu / 2.0, result.tu / 8.0);
}

