#include <stdio.h>
#include <math.h>

typedef struct {
    double kp, ki, kd;
    double integral;
    double prev_error;
    double dead_zone;
    double output_limit;
} DeadZonePID;

double deadzone_pid_update(DeadZonePID *pid, double setpoint, double measurement, double dt) {
    double error = setpoint - measurement;
    double derivative;
    double output;

    if (fabs(error) <= pid->dead_zone) {
        // 死区内，跳过积分
    } else {
        // 死区外，正常积分
        pid->integral += error * dt;
    }

    derivative = (error - pid->prev_error) / dt;
    output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;

    // 输出限幅
    if (fabs(output) > pid->output_limit) {
        output = (output > 0) ? pid->output_limit : -pid->output_limit;
    }

    pid->prev_error = error;
    return output;
}

int main() {
    DeadZonePID pid = {
        .kp = 1.5,
        .ki = 0.8,
        .kd = 0.2,
        .integral = 0.0,
        .prev_error = 0.0,
        .dead_zone = 0.05,
        .output_limit = 10.0
    };

    double dt = 0.1;
    double setpoints[] = {5.0, 5.0, 5.0, 5.0, 5.0};
    double measurements[] = {4.8, 5.02, 4.97, 5.06, 4.93};

    printf("周期序号\t设定值\t测量值\t计算误差\t控制器输出\n");
    printf("------------------------------------------------------------\n");

    for (int i = 0; i < 5; i++) {
        double output = deadzone_pid_update(&pid, setpoints[i], measurements[i], dt);
        double error = setpoints[i] - measurements[i];

        printf("%d\t\t%.2f\t%.2f\t%.3f\t\t%.3f\n", 
               i+1, setpoints[i], measurements[i], error, output);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

#define PI 3.14159265358979323846
#define BASE_FREQ 50.0f

typedef struct {
    int order;
    float amplitude;
    float phase;
} HarmonicComponent;

void harmonic_analysis(float voltage[], int N, float fs, HarmonicComponent harmonics[]) {
    float f0 = BASE_FREQ;
    int orders[] = {1, 3, 5};
    float target_freqs[] = {f0, 3*f0, 5*f0};

    for (int h = 0; h < 3; h++) {
        int k = (int)(target_freqs[h] * N / fs + 0.5f);
        if (k < 0) k = 0;
        if (k >= N/2) k = N/2 - 1;

        float real = 0.0f;
        float imag = 0.0f;

        for (int n = 0; n < N; n++) {
            float angle = -2.0f * PI * k * n / N;
            real += voltage[n] * cos(angle);
            imag += voltage[n] * sin(angle);
        }

        float amplitude = sqrt(real*real + imag*imag) * 2.0f / N;
        float phase = atan2(imag, real);

        harmonics[h].order = orders[h];
        harmonics[h].amplitude = amplitude;
        harmonics[h].phase = phase;
    }
}

void generate_compensation(HarmonicComponent harmonics[], int N, float fs, float compensation[]) {
    float f0 = BASE_FREQ;

    for (int n = 0; n < N; n++) {
        compensation[n] = 0.0f;

        for (int h = 0; h < 3; h++) {
            float angle = 2.0f * PI * harmonics[h].order * f0 * n / fs + harmonics[h].phase;
            compensation[n] -= harmonics[h].amplitude * sin(angle);
        }
    }
}

int main() {
    int N = 200;
    float fs = 1000.0f;
    float f0 = BASE_FREQ;

    float voltage[N];

    for (int n = 0; n < N; n++) {
        float t = n / fs;
        voltage[n] = 311.0f * sin(2.0f * PI * f0 * t) +
                     15.0f * sin(2.0f * PI * 3 * f0 * t) +
                     8.0f * sin(2.0f * PI * 5 * f0 * t);
    }

    HarmonicComponent harmonics[3];

    harmonic_analysis(voltage, N, fs, harmonics);

    printf("谐波分析结果：\n");
    printf("次数\t幅值(V)\t相位(rad)\n");
    for (int i = 0; i < 3; i++) {
        printf("%d\t%.3f\t%.3f\n", 
               harmonics[i].order, 
               harmonics[i].amplitude,
               harmonics[i].phase);
    }

    float compensation[N];
    generate_compensation(harmonics, N, fs, compensation);

    printf("\n前10个补偿信号值：\n");
    for (int i = 0; i < 10; i++) {
        printf("compensation[%d] = %.3f\n", i, compensation[i]);
    }

    return 0;
}

