#include <stdio.h>
#include <math.h>

// System parameters
#define VIN 24.0
#define VREF -12.0
#define I_MAX 5.0
#define FSW 100000.0
#define T (1.0/FSW)
#define L 100e-6
#define C 470e-6
#define R_LOAD 6.0

// Controller parameters
#define KP_I 0.05
#define KP_V 0.1
#define KI_V 15.0
#define INTEGRAL_LIMIT 2.0
#define DUTY_MIN 0.0
#define DUTY_MAX 0.9

// Voltage PI controller
double voltage_pi_controller(double error, double *integral) {
    double integral_term = *integral + KI_V * error * T;

    // Integral anti-windup
    if (integral_term > INTEGRAL_LIMIT) integral_term = INTEGRAL_LIMIT;
    if (integral_term < -INTEGRAL_LIMIT) integral_term = -INTEGRAL_LIMIT;

    *integral = integral_term;

    double output = KP_V * error + integral_term;

    // Output saturation
    if (output > I_MAX) output = I_MAX;
    if (output < -I_MAX) output = -I_MAX;

    return output;
}

// Current P controller
double current_p_controller(double error) {
    return KP_I * error;
}

// PWM duty cycle calculation
double calculate_duty(double inductor_current, double voltage_pi_output) {
    double current_error = voltage_pi_output - inductor_current;
    double duty_increment = current_p_controller(current_error);

    double duty = 0.5 + duty_increment;

    // Duty cycle limiting
    if (duty > DUTY_MAX) duty = DUTY_MAX;
    if (duty < DUTY_MIN) duty = DUTY_MIN;

    return duty;
}

// Buck-Boost circuit state update
void update_circuit_state(double duty, double *Vout, double *I_L) {
    // Inductor current update
    double I_L_new = *I_L + (VIN * duty / L - (*Vout) * (1 - duty) / L) * T;

    // Output voltage update
    double Vout_new = *Vout + (*I_L * (1 - duty) - *Vout / R_LOAD) * T / C;

    // Current limiting
    if (I_L_new > I_MAX) I_L_new = I_MAX;
    if (I_L_new < -I_MAX) I_L_new = -I_MAX;

    *I_L = I_L_new;
    *Vout = Vout_new;
}

int main() {
    double Vout = 0.0;
    double I_L = 0.0;
    double integral = 0.0;

    printf("Buck-Boost Converter Dual-Loop Control Simulation\n");
    printf("Cycle\tVout(V)\t\tIL(A)\t\tDuty\n");
    printf("----------------------------------------\n");

    for (int cycle = 0; cycle < 1000; cycle++) {
        // 1) Calculate voltage error
        double error = VREF - Vout;

        // 2) Voltage PI controller
        double pi_output = voltage_pi_controller(error, &integral);

        // 3) Calculate duty cycle
        double duty = calculate_duty(I_L, pi_output);

        // 4) Update circuit state
        update_circuit_state(duty, &Vout, &I_L);

        // 5) Print every 100 cycles
        if ((cycle % 100 == 0) || cycle == 999) {
            printf("%d\t%.3f\t\t%.3f\t\t%.3f\n", cycle, Vout, I_L, duty);
        }
    }

    printf("----------------------------------------\n");
    printf("Simulation complete\n");

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define PI 3.14159265358979323846
#define SAMPLE_COUNT 10
#define SAMPLE_FREQ 1000
#define SAMPLE_INTERVAL 0.001
#define VOLTAGE_PEAK 311.0
#define CURRENT 5.0
#define PULSE_THRESHOLD 0.1

double calculate_rms(double samples[], int n) {
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += samples[i] * samples[i];
    }
    return sqrt(sum / n);
}

void generate_balanced_samples(double phase_a[], double phase_b[], double phase_c[]) {
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        double angle = 2 * PI * i / SAMPLE_COUNT;
        phase_a[i] = VOLTAGE_PEAK * sin(angle);
        phase_b[i] = VOLTAGE_PEAK * sin(angle - 2 * PI / 3);
        phase_c[i] = VOLTAGE_PEAK * sin(angle + 2 * PI / 3);
    }
}

void generate_unbalanced_samples(double phase_a[], double phase_b[], double phase_c[]) {
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        double angle = 2 * PI * i / SAMPLE_COUNT;
        phase_a[i] = 1.136 * VOLTAGE_PEAK * sin(angle);
        phase_b[i] = VOLTAGE_PEAK * sin(angle - 2 * PI / 3);
        phase_c[i] = VOLTAGE_PEAK * sin(angle + 2 * PI / 3);
    }
}

void simulate_energy_accumulation(double ua_rms, double ub_rms, double uc_rms, int test_case) {
    double total_energy = 0.0;
    double energy_since_last_pulse = 0.0;
    int pulse_count = 0;

    printf("Test case %d - Energy accumulation simulation:\n", test_case);

    while (total_energy < 0.5) {
        double power = (ua_rms + ub_rms + uc_rms) * CURRENT;
        double energy_increment = power * SAMPLE_INTERVAL / 3600000.0;

        total_energy += energy_increment;
        energy_since_last_pulse += energy_increment;

        if (energy_since_last_pulse >= PULSE_THRESHOLD) {
            pulse_count++;
            printf("  Pulse event %d: Accumulated energy %.3f kWh\n", pulse_count, total_energy);
            energy_since_last_pulse = 0.0;
        }
    }

    printf("  Total accumulated energy: %.3f kWh, Total pulses: %d\n\n", total_energy, pulse_count);
}

int main() {
    double phase_a[SAMPLE_COUNT];
    double phase_b[SAMPLE_COUNT];
    double phase_c[SAMPLE_COUNT];

    printf("Smart Meter Simulation Program\n");
    printf("==============================\n\n");

    printf("Test case 1: Three-phase balanced condition\n");
    generate_balanced_samples(phase_a, phase_b, phase_c);

    double ua_rms1 = calculate_rms(phase_a, SAMPLE_COUNT);
    double ub_rms1 = calculate_rms(phase_b, SAMPLE_COUNT);
    double uc_rms1 = calculate_rms(phase_c, SAMPLE_COUNT);

    printf("  Phase A RMS voltage: %.2f V\n", ua_rms1);
    printf("  Phase B RMS voltage: %.2f V\n", ub_rms1);
    printf("  Phase C RMS voltage: %.2f V\n", uc_rms1);

    simulate_energy_accumulation(ua_rms1, ub_rms1, uc_rms1, 1);

    printf("Test case 2: Phase A voltage high condition\n");
    generate_unbalanced_samples(phase_a, phase_b, phase_c);

    double ua_rms2 = calculate_rms(phase_a, SAMPLE_COUNT);
    double ub_rms2 = calculate_rms(phase_b, SAMPLE_COUNT);
    double uc_rms2 = calculate_rms(phase_c, SAMPLE_COUNT);

    printf("  Phase A RMS voltage: %.2f V\n", ua_rms2);
    printf("  Phase B RMS voltage: %.2f V\n", ub_rms2);
    printf("  Phase C RMS voltage: %.2f V\n", uc_rms2);

    simulate_energy_accumulation(ua_rms2, ub_rms2, uc_rms2, 2);

    return 0;
}

#include <stdio.h>
#include <math.h>

typedef struct {
    float target_position;
    float actual_position;
    float error;
    float Kp, Ki, Kd;
    float Kff;
    float integral;
    float last_error;
} MotorControl;

void motor_init(MotorControl* mc, float Kp, float Ki, float Kd, float Kff) {
    mc->Kp = Kp;
    mc->Ki = Ki;
    mc->Kd = Kd;
    mc->Kff = Kff;
    mc->target_position = 0.0f;
    mc->actual_position = 0.0f;
    mc->error = 0.0f;
    mc->integral = 0.0f;
    mc->last_error = 0.0f;
}

float pid_calculate(MotorControl* mc, float dt) {
    float proportional = mc->Kp * mc->error;
    mc->integral += mc->error * dt;
    float integral = mc->Ki * mc->integral;
    float derivative = mc->Kd * (mc->error - mc->last_error) / dt;
    mc->last_error = mc->error;
    return proportional + integral + derivative;
}

float feedforward_calculate(MotorControl* mc, float target_velocity) {
    return mc->Kff * target_velocity;
}

void motor_update(MotorControl* mc, float dt, float target_vel) {
    mc->error = mc->target_position - mc->actual_position;
    float pid_output = pid_calculate(mc, dt);
    float ff_output = feedforward_calculate(mc, target_vel);
    float control_output = pid_output + ff_output;
    float disturbance = 0.1f;
    mc->actual_position += (control_output + disturbance) * dt;
}

int main() {
    MotorControl motor;
    motor_init(&motor, 2.0f, 0.5f, 0.1f, 0.3f);

    float dt = 0.01f;
    float prev_target = 0.0f;

    for (int i = 1; i <= 5; i++) {
        motor.target_position = i * 20.0f;
        float target_vel = (motor.target_position - prev_target) / dt;
        prev_target = motor.target_position;

        motor_update(&motor, dt, target_vel);

        printf("Cycle[%d] Target:%.2f Actual:%.2f Error:%.2f\n", 
               i, motor.target_position, motor.actual_position, motor.error);
    }

    return 0;
}

