#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

typedef struct {
    int id;
    double capacitor_voltage;
    int inserted;
} SubModule;

void initialize_sms(SubModule sms[], int n, double base_voltage) {
    for (int i = 0; i < n; i++) {
        sms[i].id = i;
        double random_factor = 0.9 + (rand() % 21) / 100.0;
        sms[i].capacitor_voltage = base_voltage * random_factor;
        sms[i].inserted = rand() % 2;
    }
}

void balance_control(SubModule sms[], int n, double target_voltage) {
    double sum_voltage = 0.0;
    int inserted_count = 0;

    for (int i = 0; i < n; i++) {
        if (sms[i].inserted == 1) {
            sum_voltage += sms[i].capacitor_voltage;
            inserted_count++;
        }
    }

    if (inserted_count == 0) return;

    double avg_voltage = sum_voltage / inserted_count;

    for (int i = 0; i < n; i++) {
        if (sms[i].inserted == 1) {
            if (sms[i].capacitor_voltage > avg_voltage * 1.05) {
                sms[i].inserted = 0;
                inserted_count--;
            }
        } else {
            if (sms[i].capacitor_voltage < avg_voltage * 0.95) {
                sms[i].inserted = 1;
                inserted_count++;
            }
        }
    }

    int min_inserted = n / 2;
    if (inserted_count < min_inserted) {
        int need_to_insert = min_inserted - inserted_count;
        for (int i = 0; i < n && need_to_insert > 0; i++) {
            if (sms[i].inserted == 0) {
                sms[i].inserted = 1;
                need_to_insert--;
            }
        }
    }
}

void print_status(SubModule sms[], int n) {
    for (int i = 0; i < n; i++) {
        printf("SM[%d]: voltage=%.2fV, inserted=%d\n", 
               sms[i].id, sms[i].capacitor_voltage, sms[i].inserted);
    }
    printf("\n");
}

int main() {
    srand(time(0));

    const int N = 8;
    SubModule sms[N];

    printf("=== 初始状态 ===\n");
    initialize_sms(sms, N, 100.0);
    print_status(sms, N);

    for (int iter = 1; iter <= 5; iter++) {
        printf("=== 第%d次均压控制 ===\n", iter);
        balance_control(sms, N, 100.0);
        print_status(sms, N);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

typedef struct {
    int id;
    float voltage_out;
    float voltage_ref;
    float duty_cycle;
    float kp, ki;
    float integral_error;
} DCDCModule;

void balance_control(DCDCModule *modules, int n, float dt) {
    if (n <= 0) return;

    float sum_voltage = 0.0f;
    for (int i = 0; i < n; i++) {
        sum_voltage += modules[i].voltage_out;
    }
    float avg_voltage = sum_voltage / n;

    for (int i = 0; i < n; i++) {
        float error = modules[i].voltage_out - avg_voltage;

        modules[i].integral_error += error * dt;

        float control = modules[i].kp * error + modules[i].ki * modules[i].integral_error;
        modules[i].duty_cycle += control;

        if (modules[i].duty_cycle < 0.05f) modules[i].duty_cycle = 0.05f;
        if (modules[i].duty_cycle > 0.95f) modules[i].duty_cycle = 0.95f;
    }
}

int main() {
    srand(time(NULL));

    DCDCModule modules[3];

    modules[0] = (DCDCModule){1, 95.0f, 100.0f, 0.8f, 0.01f, 0.1f, 0.0f};
    modules[1] = (DCDCModule){2, 105.0f, 100.0f, 0.85f, 0.012f, 0.12f, 0.0f};
    modules[2] = (DCDCModule){3, 100.0f, 100.0f, 0.82f, 0.011f, 0.11f, 0.0f};

    float dt = 0.01f;
    int cycles = 5;

    printf("高压DC/DC变换器串联均压控制仿真\n");
    printf("初始状态:\n");
    for (int i = 0; i < 3; i++) {
        printf("模块%d: 电压=%.2fV, 占空比=%.3f\n", 
               modules[i].id, modules[i].voltage_out, modules[i].duty_cycle);
    }
    printf("\n");

    for (int cycle = 0; cycle < cycles; cycle++) {
        printf("周期 %d:\n", cycle + 1);

        for (int i = 0; i < 3; i++) {
            printf("  模块%d: 电压=%.2fV, 占空比=%.3f", 
                   modules[i].id, modules[i].voltage_out, modules[i].duty_cycle);

            float avg = (modules[0].voltage_out + modules[1].voltage_out + modules[2].voltage_out) / 3.0f;
            printf(", 与平均差=%.2fV\n", modules[i].voltage_out - avg);
        }

        balance_control(modules, 3, dt);

        for (int i = 0; i < 3; i++) {
            modules[i].voltage_out = modules[i].duty_cycle * 120.0f + (rand() % 10 - 5) * 0.1f;
        }

        printf("\n");
    }

    printf("最终状态:\n");
    for (int i = 0; i < 3; i++) {
        printf("模块%d: 电压=%.2fV, 占空比=%.3f\n", 
               modules[i].id, modules[i].voltage_out, modules[i].duty_cycle);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float last_error;
} PIDController;

void pid_init(PIDController *pid, float Kp, float Ki, float Kd) {
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->integral = 0.0f;
    pid->last_error = 0.0f;
}

float pid_update(PIDController *pid, float setpoint, float measurement, float dt) {
    float error = setpoint - measurement;

    pid->integral += error * dt;

    float derivative = (error - pid->last_error) / dt;

    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    pid->last_error = error;

    return output;
}

float limit_frequency(float freq) {
    if (freq < 0.0f) return 0.0f;
    if (freq > 50.0f) return 50.0f;
    return freq;
}

int main() {
    PIDController pid;
    pid_init(&pid, 2.0f, 0.5f, 0.1f);

    float setpoint = 1.0f;
    float measurements[] = {0.8f, 0.85f, 0.92f, 0.96f, 0.99f};
    int num_samples = 5;
    float dt = 0.1f;

    printf("水泵变频调速PID控制模拟\n");
    printf("目标压力: %.2f MPa\n", setpoint);
    printf("PID参数: Kp=%.1f, Ki=%.1f, Kd=%.1f\n", pid.Kp, pid.Ki, pid.Kd);
    printf("采样周期: %.1f秒\n\n", dt);
    printf("周期\t测量压力(MPa)\t输出频率(Hz)\n");
    printf("----------------------------------------\n");

    for (int i = 0; i < num_samples; i++) {
        float pid_output = pid_update(&pid, setpoint, measurements[i], dt);
        float frequency = pid_output + 25.0f;
        frequency = limit_frequency(frequency);

        printf("%d\t%.2f\t\t%.2f\n", i+1, measurements[i], frequency);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define PI 3.14159265358979323846
#define SAMPLE_POINTS 64
#define SAMPLE_FREQ 1280.0
#define FUND_FREQ 50.0
#define HARMONIC_FREQ 150.0
#define FUND_AMP 1.0
#define HARMONIC_AMP 0.3

void haar_wavelet_transform(float *signal, float *approx, float *detail, int n) {
    int m = n / 2;
    float sqrt2 = sqrtf(2.0f);

    for (int i = 0; i < m; i++) {
        approx[i] = (signal[2*i] + signal[2*i+1]) / sqrt2;
        detail[i] = (signal[2*i] - signal[2*i+1]) / sqrt2;
    }
}

void haar_wavelet_reconstruct(float *approx, float *detail, float *reconstructed, int n) {
    int m = n / 2;
    float sqrt2 = sqrtf(2.0f);

    for (int i = 0; i < m; i++) {
        reconstructed[2*i] = (approx[i] + detail[i]) / sqrt2;
        reconstructed[2*i+1] = (approx[i] - detail[i]) / sqrt2;
    }
}

void extract_harmonic(float *signal, float *harmonic, int n) {
    float approx[32];
    float detail[32];

    haar_wavelet_transform(signal, approx, detail, n);

    for (int i = 0; i < 32; i++) {
        approx[i] = 0.0f;
    }

    haar_wavelet_reconstruct(approx, detail, harmonic, n);
}

float calculate_rms(float *signal, int n) {
    float sum = 0.0f;
    for (int i = 0; i < n; i++) {
        sum += signal[i] * signal[i];
    }
    return sqrtf(sum / n);
}

int main() {
    float signal[SAMPLE_POINTS];
    float harmonic[SAMPLE_POINTS];
    float time;

    for (int i = 0; i < SAMPLE_POINTS; i++) {
        time = i / SAMPLE_FREQ;
        signal[i] = FUND_AMP * sinf(2.0f * PI * FUND_FREQ * time) +
                    HARMONIC_AMP * sinf(2.0f * PI * HARMONIC_FREQ * time);
    }

    extract_harmonic(signal, harmonic, SAMPLE_POINTS);

    printf("Original signal first 10 points:\n");
    for (int i = 0; i < 10; i++) {
        printf("signal[%d] = %.6f\n", i, signal[i]);
    }

    printf("\nExtracted harmonic signal first 10 points:\n");
    for (int i = 0; i < 10; i++) {
        printf("harmonic[%d] = %.6f\n", i, harmonic[i]);
    }

    float fundamental_rms = calculate_rms(signal, SAMPLE_POINTS);
    float harmonic_rms = calculate_rms(harmonic, SAMPLE_POINTS);
    float thd = (harmonic_rms / fundamental_rms) * 100.0f;

    printf("\nHarmonic Distortion Rate (THD): %.2f%%\n", thd);

    return 0;
}

