#define GRID_FREQ_NOMINAL 50.0
#define FREQ_UPPER_LIMIT 50.5
#define FREQ_LOWER_LIMIT 49.5
#define AFD_PERTURBATION 0.02
#define MAX_CYCLES 10

float detect_islanding(float measured_freq) {
    float perturbed_freq;

    if (measured_freq > GRID_FREQ_NOMINAL) {
        perturbed_freq = measured_freq - AFD_PERTURBATION;
    } else {
        perturbed_freq = measured_freq + AFD_PERTURBATION;
    }

    return perturbed_freq;
}

void test_grid_normal() {
    printf("=== 测试1：电网正常情况 ===\n");
    float current_freq = 50.0;

    for (int i = 0; i < MAX_CYCLES; i++) {
        float perturbed = detect_islanding(current_freq);
        printf("周期 %d: 测量频率=%.3fHz, 扰动后频率=%.3fHz\n", 
               i+1, current_freq, perturbed);
        current_freq = 50.0;
    }
    printf("电网正常：频率稳定在额定值附近\n\n");
}

void test_islanding_scenario() {
    printf("=== 测试2：孤岛发生情况 ===\n");
    float current_freq = 50.0;
    bool island_detected = false;

    for (int cycle = 0; cycle < MAX_CYCLES; cycle++) {
        float perturbed = detect_islanding(current_freq);

        printf("周期 %d: 测量频率=%.3fHz, 扰动后频率=%.3fHz", 
               cycle+1, current_freq, perturbed);

        if (perturbed > FREQ_UPPER_LIMIT || perturbed < FREQ_LOWER_LIMIT) {
            printf(" -> 超出阈值！\n");
            island_detected = true;
            break;
        } else {
            printf(" -> 在正常范围内\n");
        }

        current_freq += 0.1;
    }

    if (island_detected) {
        printf("结果：孤岛检测触发\n");
    } else {
        printf("结果：未触发（达到最大检测周期）\n");
    }
}

int main() {
    test_grid_normal();
    test_islanding_scenario();
    return 0;
}

#include <stdio.h>
#include <math.h>

#define TS 0.001
#define SIM_TIME 1.0
#define STEPS 1000
#define PRINT_INTERVAL 100

typedef struct {
    double Kp;
    double Ki;
    double Kd;
    double integral;
    double prev_error;
    double prev_x_ref;
} PIDController;

double f(double x) {
    return -x*x + 1.0;
}

double g(double x) {
    return 2.0 + sin(x);
}

double pid_feedback_linearization_update(PIDController* ctrl, double x, double x_ref, double x_ref_derivative) {
    double error = x_ref - x;

    ctrl->integral += error * TS;

    double derivative = (error - ctrl->prev_error) / TS;

    double u = (1.0 / g(x)) * (-f(x) - ctrl->Kp * error - ctrl->Ki * ctrl->integral - ctrl->Kd * derivative + x_ref_derivative);

    ctrl->prev_error = error;
    ctrl->prev_x_ref = x_ref;

    return u;
}

void pid_controller_init(PIDController* ctrl, double Kp, double Ki, double Kd) {
    ctrl->Kp = Kp;
    ctrl->Ki = Ki;
    ctrl->Kd = Kd;
    ctrl->integral = 0.0;
    ctrl->prev_error = 0.0;
    ctrl->prev_x_ref = 0.0;
}

int main() {
    PIDController ctrl;
    pid_controller_init(&ctrl, 5.0, 0.5, 0.1);

    double x = 0.5;
    double x_ref = 1.0;
    double x_ref_derivative = 0.0;

    printf("Time(s)\t\tx\t\tu\t\terror\n");
    printf("--------------------------------------------\n");

    for (int i = 0; i <= STEPS; i++) {
        double t = i * TS;
        double u = pid_feedback_linearization_update(&ctrl, x, x_ref, x_ref_derivative);

        double dx = f(x) + g(x) * u;
        x += dx * TS;

        if (i % PRINT_INTERVAL == 0) {
            double error = x_ref - x;
            printf("%.6f\t%.6f\t%.6f\t%.6f\n", t, x, u, error);
        }
    }

    return 0;
}

#include <stdio.h>

double ema_filter(double new_sample, double prev_ema, double alpha) {
    return alpha * new_sample + (1.0 - alpha) * prev_ema;
}

int main() {
    double samples[] = {10.2, 10.5, 10.3, 10.8, 10.6};
    int num_samples = sizeof(samples) / sizeof(samples[0]);
    double alpha = 0.3;

    double ema = samples[0];
    double ema_sum = 0.0;

    for (int i = 0; i < num_samples; i++) {
        if (i == 0) {
            ema = samples[0];
        } else {
            ema = ema_filter(samples[i], ema, alpha);
        }

        printf("Sample[%d]=%.2f, EMA=%.2f\n", i, samples[i], ema);
        ema_sum += ema;
    }

    double average_ema = ema_sum / num_samples;
    printf("Average EMA = %.2f\n", average_ema);

    return 0;
}

