           pid.kp, pid.ki, pid.kd, pid.integral_limit, pid.output_limit);

    for (int i = 0; i < num_cycles; i++) {
        float output = pid_update(&pid, setpoint, measurements[i]);
        printf("Cycle %d: measurement=%.2f, output=%.2f\n", 
               i + 1, measurements[i], output);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

typedef struct {
    float Kp, Ki, Kd;
    float Ts;
    float integral;
    float prev_error;
    float prev_output;
} DiscretePID;

void pid_init(DiscretePID *pid, float Kp, float Ki, float Kd, float Ts) {
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->Ts = Ts;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->prev_output = 0.0f;
}

float pid_update(DiscretePID *pid, float setpoint, float measurement) {
    float error = setpoint - measurement;

    // 比例项
    float proportional = pid->Kp * error;

    // 积分项 - Tustin变换（梯形积分）
    float integral_term = pid->Ki * pid->Ts * (error + pid->prev_error) / 2.0f;

    // 微分项 - Tustin变换（一阶后向差分）
    float derivative_term = pid->Kd * (error - pid->prev_error) / pid->Ts;

    // 计算输出
    float output = proportional + pid->integral + derivative_term;

    // 保存当前误差用于下一次计算
    pid->prev_error = error;

    // 抗积分饱和处理
    if (output > 10.0f) {
        output = 10.0f;
    } else if (output < -10.0f) {
        output = -10.0f;
    } else {
        // 只有输出未饱和时才累积积分
        pid->integral += integral_term;
    }

    pid->prev_output = output;
    return output;
}

