// PSM控制函数
int psm_control(double v_out, double v_ref, double i_load, double i_threshold) {
    static int last_action = 0; // 0:跳过, 1:发出脉冲

    // 重载情况：始终返回1
    if (i_load >= i_threshold) {
        last_action = 1;
        return 1;
    }

    // 轻载情况：PSM模式
    double v_lower = v_ref * 0.98;  // 电压下限
    double v_upper = v_ref * 1.02;  // 电压上限

    if (v_out < v_lower) {
        // 电压低于下限，必须发出脉冲
        last_action = 1;
        return 1;
    } else if (v_out > v_upper) {
        // 电压高于上限，必须跳过脉冲
        last_action = 0;
        return 0;
    } else {
        // 电压在正常范围内，采用交替策略
        if (last_action == 0) {
            last_action = 1;
            return 1;
        } else {
            last_action = 0;
            return 0;
        }
    }
}

