#include <stdio.h>
#include <math.h>

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float prev_error;
    float integral_limit;
    float output_limit;
    float error_threshold;
} PID_Controller;

void PID_Init(PID_Controller *pid, float kp, float ki, float kd, float int_limit, float out_limit, float err_thresh) {
    pid->Kp = kp;
    pid->Ki = ki;
    pid->Kd = kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
    pid->integral_limit = int_limit;
    pid->output_limit = out_limit;
    pid->error_threshold = err_thresh;
}

float PID_Update(PID_Controller *pid, float setpoint, float measurement, float dt) {
    float error = setpoint - measurement;

    if (fabs(error) > pid->error_threshold) {
        pid->integral = 0.0f;
    } else {
        float integral_update = pid->Ki * error * dt;
        float new_integral = pid->integral + integral_update;

        if (fabs(new_integral) <= pid->integral_limit) {
            pid->integral = new_integral;
        }
    }

    float derivative = (error - pid->prev_error) / dt;
    pid->prev_error = error;

    float output = pid->Kp * error + pid->integral + pid->Kd * derivative;

    if (output > pid->output_limit) {
        output = pid->output_limit;
    } else if (output < -pid->output_limit) {
        output = -pid->output_limit;
    }

    return output;
}

int main() {
    PID_Controller pid;
    PID_Init(&pid, 1.0f, 0.5f, 0.1f, 2.0f, 5.0f, 3.0f);

    float setpoints[] = {10.0f, 10.0f, 10.0f, 10.0f, 10.0f};
    float measurements[] = {0.0f, 2.0f, 4.0f, 8.0f, 12.0f};
    float dt = 0.1f;

    printf("PID Anti-Windup Controller Test\n");
    printf("Kp=%.1f, Ki=%.1f, Kd=%.1f, IntLimit=%.1f, OutLimit=%.1f, ErrThresh=%.1f\n\n",
           pid.Kp, pid.Ki, pid.Kd, pid.integral_limit, pid.output_limit, pid.error_threshold);

    for (int i = 0; i < 5; i++) {
        float output = PID_Update(&pid, setpoints[i], measurements[i], dt);
        printf("Cycle %d: Setpoint=%.1f, Measurement=%.1f, Error=%.1f, Output=%.3f, Integral=%.3f\n",
               i+1, setpoints[i], measurements[i], setpoints[i]-measurements[i], output, pid.integral);
    }

    return 0;
}

#include <stdio.h>

typedef struct {
    float rated_freq;
    float rated_voltage;
    float current_freq;
    float compensation_factor;
    float min_comp_freq;
} MotorVFController;

float calculate_output_voltage(MotorVFController *ctrl) {
    float base_voltage = (ctrl->current_freq / ctrl->rated_freq) * ctrl->rated_voltage;

    if (ctrl->current_freq < ctrl->min_comp_freq) {
        float compensation_voltage = ctrl->compensation_factor * ctrl->rated_voltage * 
                                    (1.0f - ctrl->current_freq / ctrl->min_comp_freq);
        return base_voltage + compensation_voltage;
    }

    return base_voltage;
}

int main() {
    MotorVFController controller = {
        .rated_freq = 50.0f,
        .rated_voltage = 220.0f,
        .compensation_factor = 0.1f,
        .min_comp_freq = 10.0f
    };

    float test_freqs[] = {5.0f, 10.0f, 25.0f, 50.0f};
    int num_tests = sizeof(test_freqs) / sizeof(test_freqs[0]);

    for (int i = 0; i < num_tests; i++) {
        controller.current_freq = test_freqs[i];
        float output_voltage = calculate_output_voltage(&controller);
        printf("频率: %.2f Hz, 输出电压: %.2f V\n", controller.current_freq, output_voltage);
    }

    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <stddef.h>

void pwm_encode(uint8_t data, uint32_t pwm_period, uint32_t *pwm_buffer, size_t buffer_size) {
    if (buffer_size < 16) return;

    uint32_t base_width = pwm_period / 2;
    uint32_t delta = pwm_period / 4;

    for (int i = 0; i < 8; i++) {
        uint8_t bit = (data >> (7 - i)) & 0x01;
        uint32_t width = bit ? (base_width + delta) : (base_width - delta);
        pwm_buffer[i * 2] = width;
        pwm_buffer[i * 2 + 1] = width;
    }
}

uint8_t pwm_decode(const uint32_t *pwm_buffer, size_t buffer_size, uint32_t pwm_period) {
    if (buffer_size < 16) return 0;

    uint8_t result = 0;
    uint32_t base_width = pwm_period / 2;

    for (int i = 0; i < 8; i++) {
        uint32_t width = pwm_buffer[i * 2];
        int32_t diff = (int32_t)width - (int32_t)base_width;
        uint8_t bit = (diff > 0) ? 1 : 0;
        result = (result << 1) | bit;
    }

    return result;
}

int main() {
    uint32_t pwm_period = 1000;
    uint32_t buffer[16];

    printf("Test case 1: Encode data 0xAA\n");
    pwm_encode(0xAA, pwm_period, buffer, 16);
    printf("Encoded PWM high level width: ");
    for (int i = 0; i < 16; i++) {
        printf("%u ", buffer[i]);
    }
    printf("\n");

    printf("\nTest case 2: Encode data 0x55\n");
    pwm_encode(0x55, pwm_period, buffer, 16);
    printf("Encoded PWM high level width: ");
    for (int i = 0; i < 16; i++) {
        printf("%u ", buffer[i]);
    }
    printf("\n");

    printf("\nTest case 3: Decode 0xAA encoded data\n");
