#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846

typedef struct {
    int phase_id;
    double duty_cycle;
    double phase_shift;
    double current_ripple;
} PhaseData;

void calculate_total_current(int N, PhaseData phases[], double *total_ripple) {
    double max_single_ripple = 0.0;
    double weighted_sum = 0.0;
    double weight_sum = 0.0;

    for (int i = 0; i < N; i++) {
        phases[i].current_ripple = phases[i].duty_cycle * (1.0 - phases[i].duty_cycle) * 100.0;

        if (phases[i].current_ripple > max_single_ripple) {
            max_single_ripple = phases[i].current_ripple;
        }

        double weight = fabs(cos(phases[i].phase_shift));
        weighted_sum += phases[i].current_ripple * weight;
        weight_sum += weight;
    }

    if (weight_sum > 0.0) {
        *total_ripple = weighted_sum / weight_sum;
    } else {
        *total_ripple = max_single_ripple;
    }
}

int main() {
    printf("=== 3相交错并联DC/DC变换器纹波抑制模拟 ===\n");

    PhaseData phases_3[3];
    double total_ripple_3;

    for (int i = 0; i < 3; i++) {
        phases_3[i].phase_id = i;
        phases_3[i].duty_cycle = 0.4;
        phases_3[i].phase_shift = 2.0 * PI * i / 3.0;
    }

    calculate_total_current(3, phases_3, &total_ripple_3);

    printf("各相参数：\n");
    for (int i = 0; i < 3; i++) {
        printf("相位%d: 占空比=%.2f, 相位偏移=%.2f rad, 单相纹波=%.2f\n",
               phases_3[i].phase_id, phases_3[i].duty_cycle, 
               phases_3[i].phase_shift, phases_3[i].current_ripple);
    }
    printf("总输出电流纹波: %.2f\n\n", total_ripple_3);

    printf("=== 4相交错并联DC/DC变换器纹波抑制模拟 ===\n");

    PhaseData phases_4[4];
    double total_ripple_4;

    for (int i = 0; i < 4; i++) {
        phases_4[i].phase_id = i;
        phases_4[i].duty_cycle = 0.4;
        phases_4[i].phase_shift = 2.0 * PI * i / 4.0;
    }

    calculate_total_current(4, phases_4, &total_ripple_4);

    printf("各相参数：\n");
    for (int i = 0; i < 4; i++) {
        printf("相位%d: 占空比=%.2f, 相位偏移=%.2f rad, 单相纹波=%.2f\n",
               phases_4[i].phase_id, phases_4[i].duty_cycle, 
               phases_4[i].phase_shift, phases_4[i].current_ripple);
    }
    printf("总输出电流纹波: %.2f\n\n", total_ripple_4);

    printf("=== 对比分析 ===\n");
    printf("3相交错总纹波: %.2f\n", total_ripple_3);
    printf("4相交错总纹波: %.2f\n", total_ripple_4);
    printf("纹波抑制改善: %.2f%%\n", (total_ripple_3 - total_ripple_4) / total_ripple_3 * 100.0);

    return 0;
}

#include <stdio.h>
#include <math.h>

#define PI 3.141592653589793

double taylor_sin(double x) {
    double x2 = x * x;
    double x3 = x2 * x;
    double x5 = x3 * x2;
    double x7 = x5 * x2;
    double x9 = x7 * x2;

    return x - x3/6.0 + x5/120.0 - x7/5040.0 + x9/362880.0;
}

double spwm_modulate(double time, double freq, double amplitude) {
    double angle = 2.0 * PI * freq * time;
    double sin_val = taylor_sin(angle);
    return amplitude * (0.5 + 0.5 * sin_val);
}

int main() {
    double freq = 50.0;
    double amplitude = 1.0;
    double time_step = 0.001;

    printf("SPWM调制测试（频率：%.1fHz，幅度：%.1f）\n", freq, amplitude);
    printf("==========================================\n");

    for (int i = 0; i < 10; i++) {
        double time = i * time_step;
        double spwm_value = spwm_modulate(time, freq, amplitude);
        printf("Time: %.3fs, SPWM: %.6f\n", time, spwm_value);
    }

    return 0;
}

