#include <stdio.h>
#include <stdint.h>

#define PLL_CTRL_REG (*(volatile uint32_t*)0x40000000)
#define PLL_STATUS_REG (*(volatile uint32_t*)0x40000004)
#define POWER_MODE_REG (*(volatile uint32_t*)0x40000008)

#define PLL_ENABLE_BIT (1 << 0)
#define PLL_SLEEP_REQ_BIT (1 << 1)

#define PLL_LOCKED_BIT (1 << 0)
#define PLL_WAKEUP_DONE_BIT (1 << 1)

#define POWER_MODE_NORMAL 0
#define POWER_MODE_LOW_POWER 1

typedef enum {
    PLL_STATE_ACTIVE,
    PLL_STATE_SLEEP,
    PLL_STATE_WAKING_UP
} PLL_State;

static PLL_State current_state = PLL_STATE_ACTIVE;

void pll_sleep_request(void) {
    PLL_CTRL_REG |= PLL_SLEEP_REQ_BIT;
}

void pll_wakeup_request(void) {
    PLL_CTRL_REG &= ~PLL_SLEEP_REQ_BIT;
}

const char* pll_state_to_string(void) {
    switch(current_state) {
        case PLL_STATE_ACTIVE: return "ACTIVE";
        case PLL_STATE_SLEEP: return "SLEEP";
        case PLL_STATE_WAKING_UP: return "WAKING_UP";
        default: return "UNKNOWN";
    }
}

void pll_state_machine(void) {
    switch(current_state) {
        case PLL_STATE_ACTIVE:
            if ((PLL_STATUS_REG & PLL_LOCKED_BIT) && (PLL_CTRL_REG & PLL_SLEEP_REQ_BIT)) {
                current_state = PLL_STATE_SLEEP;
                POWER_MODE_REG = POWER_MODE_LOW_POWER;
            }
            break;

        case PLL_STATE_SLEEP:
            if (!(PLL_CTRL_REG & PLL_SLEEP_REQ_BIT)) {
                current_state = PLL_STATE_WAKING_UP;
                PLL_STATUS_REG &= ~PLL_WAKEUP_DONE_BIT;
            }
            break;

        case PLL_STATE_WAKING_UP:
            if (PLL_STATUS_REG & PLL_WAKEUP_DONE_BIT) {
                current_state = PLL_STATE_ACTIVE;
                POWER_MODE_REG = POWER_MODE_NORMAL;
            }
            break;
    }
}

int main() {
    PLL_CTRL_REG = 0;
    PLL_STATUS_REG = 0;
    POWER_MODE_REG = 0;
    current_state = PLL_STATE_ACTIVE;

    printf("=== PLL低功耗模式管理模拟 ===\n\n");

    printf("1. 初始化状态:\n");
    printf("   当前状态: %s\n", pll_state_to_string());
    printf("   PLL_CTRL_REG: 0x%08X\n", PLL_CTRL_REG);
    printf("   PLL_STATUS_REG: 0x%08X\n", PLL_STATUS_REG);
    printf("   POWER_MODE_REG: 0x%08X\n\n", POWER_MODE_REG);

    printf("2. 使能PLL并等待锁定:\n");
    PLL_CTRL_REG |= PLL_ENABLE_BIT;
    PLL_STATUS_REG |= PLL_LOCKED_BIT;
    pll_state_machine();
    printf("   当前状态: %s\n", pll_state_to_string());
    printf("   PLL_CTRL_REG: 0x%08X\n", PLL_CTRL_REG);
    printf("   PLL_STATUS_REG: 0x%08X\n\n", PLL_STATUS_REG);

    printf("3. 请求休眠:\n");
    pll_sleep_request();
    pll_state_machine();
    printf("   当前状态: %s\n", pll_state_to_string());
    printf("   PLL_CTRL_REG: 0x%08X\n", PLL_CTRL_REG);
    printf("   POWER_MODE_REG: 0x%08X\n\n", POWER_MODE_REG);

    printf("4. 请求唤醒:\n");
    pll_wakeup_request();
    pll_state_machine();
    printf("   当前状态: %s\n", pll_state_to_string());
    printf("   PLL_CTRL_REG: 0x%08X\n\n", PLL_CTRL_REG);

    printf("5. 完成唤醒过程:\n");
    PLL_STATUS_REG |= PLL_WAKEUP_DONE_BIT;
    pll_state_machine();
    printf("   当前状态: %s\n", pll_state_to_string());
    printf("   PLL_STATUS_REG: 0x%08X\n", PLL_STATUS_REG);
    printf("   POWER_MODE_REG: 0x%08X\n\n", POWER_MODE_REG);

    printf("=== 模拟完成 ===\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int id;
    int status;
    int is_active;
    int output_value;
} Module;

void init_modules(Module* main, Module* backup) {
    main->id = 1;
    main->status = 1;
    main->is_active = 1;
    main->output_value = 100;

    backup->id = 2;
    backup->status = 1;
    backup->is_active = 0;
    backup->output_value = 100;
}

int get_system_output(Module* main, Module* backup) {
    if (main->is_active && main->status) {
        return main->output_value;
    } else if (backup->is_active && backup->status) {
        return backup->output_value;
    } else {
        return -1;
    }
}

void monitor_and_switch(Module* main, Module* backup) {
    if (main->is_active && !main->status && backup->status) {
        int current_output = get_system_output(main, backup);
        main->is_active = 0;
        backup->is_active = 1;
        backup->output_value = current_output;
    } else if (backup->is_active && !backup->status && main->status) {
        int current_output = get_system_output(main, backup);
        backup->is_active = 0;
        main->is_active = 1;
        main->output_value = current_output;
    }
}

void simulate_fault(Module* module, int fault_status) {
    module->status = fault_status;
}

void print_module_status(Module* module, const char* name) {
    printf("%s模块 [ID:%d]: ", name, module->id);
    printf("状态:%s, ", module->status ? "正常" : "故障");
    printf("角色:%s, ", module->is_active ? "主用" : "备用");
    printf("输出值:%d\n", module->output_value);
}

int main() {
    Module main_module, backup_module;

    printf("=== 电力电子冗余模块切换系统测试 ===\n\n");

    printf("1. 初始化系统:\n");
    init_modules(&main_module, &backup_module);
    print_module_status(&main_module, "主");
    print_module_status(&backup_module, "备");
    printf("系统输出值: %d\n\n", get_system_output(&main_module, &backup_module));

    printf("2. 模拟主模块故障，触发切换:\n");
    printf("切换前系统输出值: %d\n", get_system_output(&main_module, &backup_module));
    simulate_fault(&main_module, 0);
    printf("主模块故障后 - ");
    print_module_status(&main_module, "主");
    monitor_and_switch(&main_module, &backup_module);
    printf("切换后 - ");
    print_module_status(&main_module, "主");
    print_module_status(&backup_module, "备");
    printf("切换后系统输出值: %d\n\n", get_system_output(&main_module, &backup_module));

    printf("3. 模拟原主模块恢复:\n");
    simulate_fault(&main_module, 1);
    printf("原主模块恢复后 - ");
    print_module_status(&main_module, "主");
    print_module_status(&backup_module, "备");
    printf("系统输出值: %d\n\n", get_system_output(&main_module, &backup_module));

    printf("4. 模拟新主模块(原备用模块)故障:\n");
    simulate_fault(&backup_module, 0);
    printf("新主模块故障后 - ");
    print_module_status(&main_module, "主");
    print_module_status(&backup_module, "备");
    monitor_and_switch(&main_module, &backup_module);
    printf("切换尝试后 - ");
    print_module_status(&main_module, "主");
    print_module_status(&backup_module, "备");
    printf("系统输出值: %d\n\n", get_system_output(&main_module, &backup_module));

    printf("=== 测试完成 ===\n");

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define PI 3.14159265358979323846
#define TWO_PI (2.0 * PI)

// PLL结构体
typedef struct {
    double theta;           // 内部振荡器相位
    double f_est;           // 估计频率 (Hz)
    double filter_state;    // 低通滤波器状态
    double prev_signal;     // 前一个采样值（用于过零检测）
    int zero_cross_detected; // 过零检测标志
} PLL;

// 数字低通滤波器（一阶RC滤波器）
double low_pass_filter(double input, double* state, double alpha) {
    *state = alpha * input + (1.0 - alpha) * (*state);
    return *state;
}

// 过零检测函数：检测从负到正的过零点
int detect_zero_crossing(double current_signal, double prev_signal) {
    return (prev_signal <= 0.0 && current_signal > 0.0);
}

// PLL更新函数
void pll_update(PLL* pll, double signal, double dt, double kp, double ki) {
    // 过零检测
    pll->zero_cross_detected = detect_zero_crossing(signal, pll->prev_signal);
    pll->prev_signal = signal;

    if (pll->zero_cross_detected) {
        // 计算相位误差：理想过零点相位应为0，实际内部相位为pll->theta
        double phase_error = -pll->theta;  // 误差 = 目标相位(0) - 当前相位

        // 处理相位卷绕，使误差在[-π, π]范围内
        while (phase_error > PI) phase_error -= TWO_PI;
        while (phase_error < -PI) phase_error += TWO_PI;

        // 低通滤波器参数（截止频率约10Hz）
        double alpha = 0.05;  // 对应时间常数约0.01s
        double filtered_error = low_pass_filter(phase_error, &pll->filter_state, alpha);

        // 更新估计频率：PI控制器
        pll->f_est += ki * filtered_error;

        // 限制频率范围
        if (pll->f_est < 45.0) pll->f_est = 45.0;
        if (pll->f_est > 55.0) pll->f_est = 55.0;
    }

    // 更新内部振荡器相位
    pll->theta += TWO_PI * pll->f_est * dt;

    // 相位模2π运算，保持在[0, 2π)范围内
    if (pll->theta >= TWO_PI) pll->theta -= TWO_PI;
    if (pll->theta < 0.0) pll->theta += TWO_PI;
}

// 模拟单相交流信号
double generate_signal(double t, double Vm, double f, double phi) {
    return Vm * sin(TWO_PI * f * t + phi);
}

int main() {
    // 参数设置
    double Vm = 1.0;           // 幅值
    double f_input = 50.0;     // 输入频率 (Hz)
    double phi = 0.1;          // 初始相位 (弧度)
    double fs = 2000.0;        // 采样率 (Hz)
    double dt = 1.0 / fs;      // 采样间隔 (s)

    int num_samples = 1000;    // 总采样点数
    int print_interval = 100;  // 打印间隔

    // 初始化PLL
    PLL pll;
    pll.theta = 0.0;           // 初始相位
    pll.f_est = 50.0;          // 初始频率估计
    pll.filter_state = 0.0;    // 滤波器初始状态
    pll.prev_signal = 0.0;     // 前一个信号值
    pll.zero_cross_detected = 0;

    // PLL控制器参数
    double kp = 0.0;           // 比例项（当前未使用）
    double ki = 0.1;           // 积分项

    printf("单相锁相环(PLL)仿真测试\n");
    printf("输入信号: Vm=%.2fV, f=%.2fHz, φ=%.2frad\n", Vm, f_input, phi);
    printf("采样率: %.0fHz, 总采样点数: %d\n\n", fs, num_samples);

    printf("%-10s %-12s %-12s %-12s %-12s\n", 
           "时间(s)", "输入信号", "内部相位", "估计频率", "过零检测");
    printf("------------------------------------------------------------\n");

    double steady_state_error_sum = 0.0;
    int steady_state_count = 0;

    for (int i = 0; i < num_samples; i++) {
        double t = i * dt;

        // 生成输入信号
        double signal = generate_signal(t, Vm, f_input, phi);

        // 更新PLL
        pll_update(&pll, signal, dt, kp, ki);

        // 每100个点打印一次
        if (i % print_interval == 0) {
            printf("%-10.4f %-12.6f %-12.6f %-12.6f %-12d\n", 
                   t, signal, pll.theta, pll.f_est, pll.zero_cross_detected);
        }

        // 收集稳态数据（后500个点）
        if (i >= 500) {
            steady_state_error_sum += fabs(pll.f_est - f_input);
            steady_state_count++;
        }
    }

    // 计算稳态频率误差
    double steady_state_error = steady_state_error_sum / steady_state_count;

    printf("\n------------------------------------------------------------\n");
    printf("锁相环收敛结果:\n");
    printf("最终估计频率: %.6f Hz\n", pll.f_est);
    printf("目标频率: %.6f Hz\n", f_input);
    printf("稳态频率误差: %.6f Hz\n", steady_state_error);
    printf("相对误差: %.6f%%\n", (steady_state_error / f_input) * 100.0);

    return 0;
}

#include <stdio.h>

float calculate_insulation_resistance(float U_plus, float U_minus, float R_bridge) {
    float diff = U_plus - U_minus;
    if (diff < 0.001f && diff > -0.001f) {
        return 1000000.0f;
    }
    return R_bridge * (U_plus + U_minus) / diff;
}

void check_insulation_fault(float R_ins, float threshold) {
    if (R_ins < threshold) {
        printf("ALARM: Insulation fault detected! R_ins = %.2f kΩ\n", R_ins);
    } else {
        printf("OK: Insulation normal. R_ins = %.2f kΩ\n", R_ins);
    }
}

int main() {
    float R_bridge = 10.0f;
    float threshold = 20.0f;

    printf("=== Insulation Resistance Fault Detection Test ===\n\n");

    printf("Test 1: Normal insulation (balanced system)\n");
    float U_plus1 = 150.0f;
    float U_minus1 = 150.0f;
    float R_ins1 = calculate_insulation_resistance(U_plus1, U_minus1, R_bridge);
    if (R_ins1 > 999999.0f) {
        printf("Perfectly balanced system: R_ins = INFINITY kΩ\n");
        printf("OK: Insulation normal. R_ins = INFINITY kΩ\n");
    } else {
        check_insulation_fault(R_ins1, threshold);
    }
    printf("\n");

    printf("Test 2: Good insulation (slight imbalance)\n");
    float U_plus2 = 155.0f;
    float U_minus2 = 145.0f;
    float R_ins2 = calculate_insulation_resistance(U_plus2, U_minus2, R_bridge);
    check_insulation_fault(R_ins2, threshold);
    printf("\n");

    printf("Test 3: Insulation fault (low resistance)\n");
    float U_plus3 = 180.0f;
    float U_minus3 = 120.0f;
    float R_ins3 = calculate_insulation_resistance(U_plus3, U_minus3, R_bridge);
    check_insulation_fault(R_ins3, threshold);
    printf("\n");

    printf("Test 4: Severe insulation fault\n");
    float U_plus4 = 195.0f;
    float U_minus4 = 105.0f;
    float R_ins4 = calculate_insulation_resistance(U_plus4, U_minus4, R_bridge);
    check_insulation_fault(R_ins4, threshold);
    printf("\n");

    printf("Test 5: Edge case (very low voltage difference)\n");
    float U_plus5 = 150.1f;
    float U_minus5 = 149.9f;
    float R_ins5 = calculate_insulation_resistance(U_plus5, U_minus5, R_bridge);
    check_insulation_fault(R_ins5, threshold);

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define PI 3.1415926535f
#define RATED_AMPLITUDE 311.0f
#define SAG_THRESHOLD 0.8f

bool detect_voltage_sag(float voltages[]) {
    float sum_abs = 0.0f;
    for (int i = 0; i < 3; i++) {
        sum_abs += fabsf(voltages[i]);
    }
    float avg_amplitude = sum_abs / 3.0f;
    return avg_amplitude < (RATED_AMPLITUDE * SAG_THRESHOLD);
}

void compensate_amplitude(float phase_angle, float compensated[]) {
    compensated[0] = RATED_AMPLITUDE * sinf(phase_angle);
    compensated[1] = RATED_AMPLITUDE * sinf(phase_angle - 2.0f * PI / 3.0f);
    compensated[2] = RATED_AMPLITUDE * sinf(phase_angle + 2.0f * PI / 3.0f);
}

int main() {
    printf("PLL电压跌落幅值锁定算法测试\n");
    printf("额定幅值: %.1fV, 跌落阈值: %.0f%%\n", RATED_AMPLITUDE, SAG_THRESHOLD * 100);
    printf("跌落判断阈值: %.1fV\n\n", RATED_AMPLITUDE * SAG_THRESHOLD);

    float test_voltages[3][3] = {
        {300.0f, -280.0f, 290.0f},
        {150.0f, -130.0f, 140.0f},
        {248.0f, -250.0f, 249.0f}
    };

    float test_phases[3] = {0.5f, 1.2f, 2.0f};

    for (int test_case = 0; test_case < 3; test_case++) {
        printf("测试%d：\n", test_case + 1);
        printf("  输入三相电压: [%.1f, %.1f, %.1f] V\n", 
               test_voltages[test_case][0], 
               test_voltages[test_case][1], 
               test_voltages[test_case][2]);
        printf("  相位角: %.2f 弧度\n", test_phases[test_case]);

        bool is_sag = detect_voltage_sag(test_voltages[test_case]);
        printf("  电压跌落检测: %s\n", is_sag ? "是" : "否");

        if (is_sag) {
            float compensated[3];
            compensate_amplitude(test_phases[test_case], compensated);
            printf("  补偿后三相电压: [%.2f, %.2f, %.2f] V\n", 
                   compensated[0], compensated[1], compensated[2]);
        }
        printf("\n");
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

#define BASE_DEADTIME 0.5f
#define MAX_DEADTIME 3.0f
#define CURRENT_COMP_MAX 1.5f
#define VOLTAGE_COMP_MAX 0.3f
#define CURRENT_COMP_RATE 0.02f
#define VOLTAGE_COMP_RATE 0.001f
#define TEMP_THRESHOLD 85.0f
#define TEMP_COMP_RATE 0.005f

float adaptive_deadtime_calc(float load_current, float dc_voltage, float temperature) {
    float deadtime = BASE_DEADTIME;

    float current_comp = load_current * CURRENT_COMP_RATE;
    if (current_comp > CURRENT_COMP_MAX) {
        current_comp = CURRENT_COMP_MAX;
    }
    deadtime += current_comp;

    float voltage_comp = dc_voltage * VOLTAGE_COMP_RATE;
    if (voltage_comp > VOLTAGE_COMP_MAX) {
        voltage_comp = VOLTAGE_COMP_MAX;
    }
    deadtime += voltage_comp;

    if (temperature > TEMP_THRESHOLD) {
        float temp_comp = (temperature - TEMP_THRESHOLD) * TEMP_COMP_RATE;
        deadtime += temp_comp;
    }

    if (deadtime > MAX_DEADTIME) {
        deadtime = MAX_DEADTIME;
    }

    return deadtime;
}

int main() {
    printf("DC/DC变换器死区时间自适应调整算法测试\n");
    printf("========================================\n");

    float test_cases[4][3] = {
        {2.5f, 48.0f, 25.0f},
        {15.0f, 96.0f, 30.0f},
        {8.0f, 72.0f, 95.0f},
        {25.0f, 120.0f, 105.0f}
    };

    const char* case_names[4] = {"轻载情况", "重载情况", "高温情况", "极限情况"};

    for (int i = 0; i < 4; i++) {
        float load_current = test_cases[i][0];
        float dc_voltage = test_cases[i][1];
        float temperature = test_cases[i][2];

        float deadtime = adaptive_deadtime_calc(load_current, dc_voltage, temperature);

        printf("测试用例%d(%s): 负载电流=%.1fA, 直流电压=%.1fV, 温度=%.1f°C => 死区时间=%.3fμs\n",
               i+1, case_names[i], load_current, dc_voltage, temperature, deadtime);
    }

    printf("\n算法参数说明:\n");
    printf("- 基础死区时间: %.1fμs\n", BASE_DEADTIME);
    printf("- 电流补偿: 每1A增加%.3fμs (上限%.1fμs)\n", CURRENT_COMP_RATE, CURRENT_COMP_MAX);
    printf("- 电压补偿: 每10V增加%.3fμs (上限%.1fμs)\n", VOLTAGE_COMP_RATE*10, VOLTAGE_COMP_MAX);
    printf("- 温度补偿: >%.1f°C时每1°C增加%.3fμs\n", TEMP_THRESHOLD, TEMP_COMP_RATE);
    printf("- 总死区时间上限: %.1fμs\n", MAX_DEADTIME);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    float kp;
    float ki;
    float integral;
    float integral_limit;
    int compensation_delay;
    float* compensation_buffer;
    int buffer_index;
} BuckPIController;

void buck_pi_init(BuckPIController* ctrl, float kp, float ki, float integral_limit, int delay_cycles) {
    ctrl->kp = kp;
    ctrl->ki = ki;
    ctrl->integral = 0.0f;
    ctrl->integral_limit = integral_limit;
    ctrl->compensation_delay = delay_cycles;

    if (delay_cycles > 0) {
        ctrl->compensation_buffer = (float*)malloc(delay_cycles * sizeof(float));
        memset(ctrl->compensation_buffer, 0, delay_cycles * sizeof(float));
    } else {
        ctrl->compensation_buffer = NULL;
    }

    ctrl->buffer_index = 0;
}

float buck_pi_update(BuckPIController* ctrl, float v_ref, float v_fb, float dt) {
    float error = v_ref - v_fb;

    ctrl->integral += ctrl->ki * error * dt;

    if (ctrl->integral > ctrl->integral_limit) {
        ctrl->integral = ctrl->integral_limit;
    } else if (ctrl->integral < -ctrl->integral_limit) {
        ctrl->integral = -ctrl->integral_limit;
    }

    float proportional = ctrl->kp * error;
    float output = proportional + ctrl->integral;

    if (ctrl->compensation_delay > 0) {
        ctrl->compensation_buffer[ctrl->buffer_index] = output;
        ctrl->buffer_index = (ctrl->buffer_index + 1) % ctrl->compensation_delay;

        int delayed_index = (ctrl->buffer_index + ctrl->compensation_delay - 1) % ctrl->compensation_delay;
        return ctrl->compensation_buffer[delayed_index];
    }

    return output;
}

void buck_pi_cleanup(BuckPIController* ctrl) {
    if (ctrl->compensation_buffer != NULL) {
        free(ctrl->compensation_buffer);
        ctrl->compensation_buffer = NULL;
    }
}

int main() {
    BuckPIController ctrl;
    buck_pi_init(&ctrl, 0.5f, 10.0f, 1.0f, 3);

    float dt = 0.001f;
    float v_ref_values[] = {5.0f, 5.0f, 5.0f, 5.0f, 5.0f};
    float v_fb_values[] = {4.5f, 4.8f, 4.9f, 5.0f, 5.1f};

    printf("Buck变换器电压闭环PI控制仿真\n");
    printf("参数: kp=%.1f, ki=%.1f, 积分限幅=%.1f, 延迟补偿=%d周期\n\n", 
           ctrl.kp, ctrl.ki, ctrl.integral_limit, ctrl.compensation_delay);
    printf("周期\tv_ref\tv_fb\t误差\t\t积分值\t\t补偿前输出\t补偿后输出\n");
    printf("-----------------------------------------------------------------------------\n");

    for (int i = 0; i < 5; i++) {
        float v_ref = v_ref_values[i];
        float v_fb = v_fb_values[i];
        float error = v_ref - v_fb;
        float integral_before = ctrl.integral;

        float output_before = ctrl.kp * error + integral_before;
        float output_compensated = buck_pi_update(&ctrl, v_ref, v_fb, dt);

        printf("%d\t%.1f\t%.1f\t%.3f\t\t%.6f\t%.6f\t%.6f\n", 
               i+1, v_ref, v_fb, error, ctrl.integral, output_before, output_compensated);
    }

    buck_pi_cleanup(&ctrl);
    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define PI 3.14159265358979323846
#define FS 10000.0  // 采样频率 10kHz
#define F1 50.0     // 基波频率 50Hz
#define F3 150.0    // 3次谐波频率 150Hz
#define F5 250.0    // 5次谐波频率 250Hz
#define N 1024      // 采样点数

// DFT结构体，存储谐波信息
typedef struct {
    double amplitude;  // 幅值
    double phase;      // 相位（弧度）
} HarmonicInfo;

// 计算单个频率分量的DFT
HarmonicInfo compute_dft_component(double *signal, int n, double freq) {
    HarmonicInfo result = {0.0, 0.0};
    double real = 0.0;
    double imag = 0.0;

    for (int k = 0; k < n; k++) {
        double angle = 2.0 * PI * freq * k / FS;
        real += signal[k] * cos(angle);
        imag += signal[k] * sin(angle);
    }

    real = 2.0 * real / n;
    imag = 2.0 * imag / n;

    result.amplitude = sqrt(real * real + imag * imag);
    result.phase = atan2(imag, real);

    return result;
}

// 谐波补偿函数
void harmonic_compensation(double *voltage, int n, double *compensated) {
    // 检测基波、3次谐波和5次谐波
    HarmonicInfo fundamental = compute_dft_component(voltage, n, F1);
    HarmonicInfo harmonic3 = compute_dft_component(voltage, n, F3);
    HarmonicInfo harmonic5 = compute_dft_component(voltage, n, F5);

    // 从原始信号中减去3次和5次谐波分量
    for (int i = 0; i < n; i++) {
        double t = i / FS;

        // 3次谐波分量
        double h3 = harmonic3.amplitude * cos(2.0 * PI * F3 * t + harmonic3.phase);

        // 5次谐波分量
        double h5 = harmonic5.amplitude * cos(2.0 * PI * F5 * t + harmonic5.phase);

        // 补偿后信号 = 原始信号 - 3次谐波 - 5次谐波
        compensated[i] = voltage[i] - h3 - h5;
    }
}

int main() {
    double voltage[N];
    double compensated[N];

    // 生成测试信号参数
    double A1 = 311.0;    // 基波幅值 311V (对应220V有效值)
    double A3 = 15.5;     // 3次谐波幅值 15.5V (5%畸变)
    double A5 = 9.3;      // 5次谐波幅值 9.3V (3%畸变)

    double phi1 = 0.0;    // 基波初始相位
    double phi3 = PI/6;   // 3次谐波初始相位 30度
    double phi5 = PI/4;   // 5次谐波初始相位 45度

    // 生成测试信号
    for (int i = 0; i < N; i++) {
        double t = i / FS;

        // 基波分量
        double v1 = A1 * cos(2.0 * PI * F1 * t + phi1);

        // 3次谐波分量
        double v3 = A3 * cos(2.0 * PI * F3 * t + phi3);

        // 5次谐波分量
        double v5 = A5 * cos(2.0 * PI * F5 * t + phi5);

        voltage[i] = v1 + v3 + v5;
    }

    // 调用谐波补偿函数
    harmonic_compensation(voltage, N, compensated);

    // 打印前10个采样点的结果
    printf("逆变器输出电压谐波补偿结果：\n");
    printf("采样频率：%.0f Hz，采样点数：%d\n", FS, N);
    printf("基波频率：%.0f Hz，3次谐波：%.0f Hz，5次谐波：%.0f Hz\n\n", F1, F3, F5);

    for (int i = 0; i < 10; i++) {
        printf("Sample [%d]: raw=%7.2f V, compensated=%7.2f V\n", 
               i, voltage[i], compensated[i]);
    }

    // 计算并显示谐波检测结果
    printf("\n谐波检测结果：\n");

    HarmonicInfo fundamental = compute_dft_component(voltage, N, F1);
    HarmonicInfo harmonic3 = compute_dft_component(voltage, N, F3);
    HarmonicInfo harmonic5 = compute_dft_component(voltage, N, F5);

    printf("基波(50Hz): 幅值=%7.2f V, 相位=%7.2f 度\n", 
           fundamental.amplitude, fundamental.phase * 180.0 / PI);
    printf("3次谐波(150Hz): 幅值=%7.2f V, 相位=%7.2f 度\n", 
           harmonic3.amplitude, harmonic3.phase * 180.0 / PI);
    printf("5次谐波(250Hz): 幅值=%7.2f V, 相位=%7.2f 度\n", 
           harmonic5.amplitude, harmonic5.phase * 180.0 / PI);

    // 计算THD（总谐波畸变率）
    double thd = sqrt(harmonic3.amplitude * harmonic3.amplitude + 
                      harmonic5.amplitude * harmonic5.amplitude) / 
                 fundamental.amplitude * 100.0;
    printf("\n总谐波畸变率(THD): %.2f%%\n", thd);

    return 0;
}

