#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define PI 3.14159265358979323846f

float random_triangle_wave(float t, float base_freq, float freq_range) {
    static float current_freq = 0.0f;
    static float last_cycle = -1.0f;

    float phase = t * base_freq;
    int cycle = (int)phase;

    if (cycle > last_cycle) {
        float rand_val = (float)rand() / RAND_MAX;
        current_freq = base_freq + (rand_val * 2.0f - 1.0f) * freq_range;
        last_cycle = cycle;
    }

    float actual_phase = t * current_freq;
    float triangle_phase = actual_phase - floorf(actual_phase);

    if (triangle_phase < 0.5f) {
        return -1.0f + 4.0f * triangle_phase;
    } else {
        return 1.0f - 4.0f * (triangle_phase - 0.5f);
    }
}

int random_pwm(float t, float modulation_index) {
    float carrier = random_triangle_wave(t, 1000.0f, 200.0f);
    float mod_signal = modulation_index * sinf(2.0f * PI * 50.0f * t);

    return (mod_signal > carrier) ? 1 : 0;
}

int main() {
    srand(0);

    float t_start = 0.0f;
    float t_end = 0.1f;
    float dt = 0.0001f;
    float modulation_index = 0.5f;
    float base_freq = 1000.0f;
    float freq_range = 200.0f;

    int total_samples = (int)((t_end - t_start) / dt) + 1;
    int high_count = 0;

    printf("Time(s)  Carrier  ModSignal  PWM\n");

    for (int i = 0; i < total_samples; i++) {
        float t = t_start + i * dt;

        float carrier = random_triangle_wave(t, base_freq, freq_range);
        float mod_signal = modulation_index * sinf(2.0f * PI * 50.0f * t);
        int pwm_output = (mod_signal > carrier) ? 1 : 0;

        if (pwm_output) {
            high_count++;
        }

        if (i < 5) {
            printf("%f  %f  %f  %d\n", t, carrier, mod_signal, pwm_output);
        }
    }

    float duty_cycle = (float)high_count / total_samples * 100.0f;
    printf("Duty cycle: %.2f%%\n", duty_cycle);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef enum {
    PLL_LOCKED,
    PLL_UNLOCKED,
    PLL_RESTARTING
} PLL_Status;

typedef struct {
    PLL_Status current_state;
    float phase_error;
    int unlock_counter;
    int restart_step;
} PLL_State;

void pll_detect_unlock(PLL_State *pll, float phase_error) {
    if (phase_error > 0.5f) {
        pll->unlock_counter++;
        printf("UnlockCount=%d\n", pll->unlock_counter);
        if (pll->unlock_counter >= 3) {
            pll->current_state = PLL_UNLOCKED;
            printf("Enter UNLOCKED state!\n");
        }
    } else {
        pll->unlock_counter = 0;
    }
}

void pll_restart_sequence(PLL_State *pll) {
    switch (pll->restart_step) {
        case 0:
            printf("Step 1: Reset phase error\n");
            pll->phase_error = 0.0f;
            pll->restart_step = 1;
            break;
        case 1:
            printf("Step 2: Frequency pull-back\n");
            pll->restart_step = 2;
            break;
        case 2:
            printf("Step 3: Re-locking completed\n");
            pll->restart_step = 0;
            pll->current_state = PLL_LOCKED;
            pll->unlock_counter = 0;
            printf("Return to LOCKED state\n");
            break;
    }
}

void pll_update(PLL_State *pll, float new_phase_error) {
    pll->phase_error = new_phase_error;

    switch (pll->current_state) {
        case PLL_LOCKED:
            pll_detect_unlock(pll, new_phase_error);
            break;
        case PLL_UNLOCKED:
            pll->current_state = PLL_RESTARTING;
            pll->restart_step = 0;
            printf("Enter RESTARTING state...\n");
            break;
        case PLL_RESTARTING:
            pll_restart_sequence(pll);
            break;
    }
}

int main() {
    PLL_State pll = {
        .current_state = PLL_LOCKED,
        .phase_error = 0.0f,
        .unlock_counter = 0,
        .restart_step = 0
    };

    float phase_errors[] = {0.1f, 0.6f, 0.7f, 0.65f, 0.05f, 0.1f};
    int num_steps = sizeof(phase_errors) / sizeof(phase_errors[0]);

    for (int i = 0; i < num_steps; i++) {
        printf("Time %d: PhaseError=%.3f, State=", i+1, phase_errors[i]);

        switch (pll.current_state) {
            case PLL_LOCKED: printf("LOCKED"); break;
            case PLL_UNLOCKED: printf("UNLOCKED"); break;
            case PLL_RESTARTING: printf("RESTARTING"); break;
        }

        if (pll.current_state == PLL_LOCKED && pll.unlock_counter > 0) {
            printf(", UnlockCount=%d", pll.unlock_counter);
        } else if (pll.current_state == PLL_LOCKED) {
            printf(", Counter=0");
        }
        printf("\n");

        pll_update(&pll, phase_errors[i]);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

#define PI 3.14159265358979323846f
#define TWO_PI (2.0f * PI)
#define ALPHA 0.2f

float pll_phase_filter(float raw_phase) {
    static float last_raw_phase = 0.0f;
    static float last_output = 0.0f;
    static float last_delta_filtered = 0.0f;
    static int first_call = 1;

    if (first_call) {
        last_raw_phase = raw_phase;
        last_output = raw_phase;
        last_delta_filtered = 0.0f;
        first_call = 0;
        return raw_phase;
    }

    float delta = raw_phase - last_raw_phase;

    if (delta > PI) {
        delta -= TWO_PI;
    } else if (delta < -PI) {
        delta += TWO_PI;
    }

    float delta_filtered = ALPHA * delta + (1.0f - ALPHA) * last_delta_filtered;

    float output = last_output + delta_filtered;

    while (output >= TWO_PI) {
        output -= TWO_PI;
    }
    while (output < 0.0f) {
        output += TWO_PI;
    }

    last_raw_phase = raw_phase;
    last_output = output;
    last_delta_filtered = delta_filtered;

    return output;
}

int main() {
    float test_phases[] = {0.1f, 0.2f, 0.3f, 6.1f, 6.2f, 6.3f, 0.5f, 0.6f};
    int num_samples = sizeof(test_phases) / sizeof(test_phases[0]);

    printf("Sample\tRaw Phase\tFiltered Phase\n");
    printf("------\t----------\t--------------\n");

    for (int i = 0; i < num_samples; i++) {
        float filtered = pll_phase_filter(test_phases[i]);
        printf("%d\t%.3f\t\t%.3f\n", i+1, test_phases[i], filtered);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int period_ms;
    unsigned int last_edge_time;
    int missing_count;
    int fault_flag;
} PWM_Monitor;

void pwm_monitor_init(PWM_Monitor *mon, int period_ms) {
    mon->period_ms = period_ms;
    mon->last_edge_time = 0;
    mon->missing_count = 0;
    mon->fault_flag = 0;
}

void pwm_edge_detected(PWM_Monitor *mon, unsigned int current_time) {
    mon->last_edge_time = current_time;
    mon->missing_count = 0;
}

int check_pwm_missing(PWM_Monitor *mon, unsigned int current_time) {
    if (mon->fault_flag) {
        return 1;
    }

    if (mon->last_edge_time == 0) {
        return 0;
    }

    unsigned int time_since_last_edge = current_time - mon->last_edge_time;

    if (time_since_last_edge > (mon->period_ms * 1.5)) {
        mon->missing_count++;

        if (mon->missing_count >= 3) {
            mon->fault_flag = 1;
        }

        return 1;
    }

    return 0;
}

int main() {
    PWM_Monitor monitor;
    pwm_monitor_init(&monitor, 20);

    int edge_times[] = {5, 25, 45, 65, 85};
    int edge_count = 5;
    int edge_index = 0;

    for (unsigned int time_ms = 0; time_ms <= 100; time_ms++) {
        if (edge_index < edge_count && time_ms == edge_times[edge_index]) {
            pwm_edge_detected(&monitor, time_ms);
            edge_index++;
        }

        int missing = check_pwm_missing(&monitor, time_ms);

        if (missing) {
            printf("Time %ums: Missing detected! Count=%d", time_ms, monitor.missing_count);
            if (monitor.fault_flag) {
                printf(" FAULT!");
            }
            printf("\n");
        } else {
            printf("Time %ums: No missing\n", time_ms);
        }
    }

    return 0;
}

