}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define PI 3.14159265358979323846
#define SAMPLE_RATE 1600  // 32点 * 50Hz = 1600Hz

int detect_ct_saturation(float* samples, int n, float threshold) {
    if (n <= 0 || samples == NULL) {
        return 0;
    }

    float max_val = samples[0];
    float min_val = samples[0];

    for (int i = 0; i < n; i++) {
        if (samples[i] > max_val) {
            max_val = samples[i];
        }
        if (samples[i] < min_val) {
            min_val = samples[i];
        }
    }

    if (max_val > threshold && min_val < -threshold) {
        return 1;
    }
    else if (max_val > threshold) {
        return 1;
    }
    else if (min_val < -threshold) {
        return -1;
    }
    else {
        return 0;
    }
}

void generate_sine_wave(float* buffer, int n, float amplitude, float frequency) {
    for (int i = 0; i < n; i++) {
        float t = (float)i / SAMPLE_RATE;
        buffer[i] = amplitude * sin(2 * PI * frequency * t);
    }
}

void generate_positive_saturation(float* buffer, int n, float amplitude, float frequency) {
    float threshold = 1.0f;
    for (int i = 0; i < n; i++) {
        float t = (float)i / SAMPLE_RATE;
        float value = amplitude * sin(2 * PI * frequency * t);
        if (value > threshold) {
            value = threshold;
        }
        buffer[i] = value;
    }
}

void generate_negative_saturation(float* buffer, int n, float amplitude, float frequency) {
    float threshold = -1.0f;
    for (int i = 0; i < n; i++) {
        float t = (float)i / SAMPLE_RATE;
        float value = amplitude * sin(2 * PI * frequency * t);
        if (value < threshold) {
            value = threshold;
        }
        buffer[i] = value;
    }
}

int main() {
    const int n = 32;
    float samples_normal[n];
    float samples_pos_sat[n];
    float samples_neg_sat[n];

    float threshold = 1.2f;

    generate_sine_wave(samples_normal, n, 0.8f, 50.0f);
    generate_positive_saturation(samples_pos_sat, n, 1.8f, 50.0f);
    generate_negative_saturation(samples_neg_sat, n, 1.6f, 50.0f);

    int result1 = detect_ct_saturation(samples_normal, n, threshold);
    int result2 = detect_ct_saturation(samples_pos_sat, n, threshold);
    int result3 = detect_ct_saturation(samples_neg_sat, n, threshold);

    printf("Test 1: Normal waveform -> Saturation status: %d\n", result1);
    printf("Test 2: Positive saturation -> Saturation status: %d\n", result2);
    printf("Test 3: Negative saturation -> Saturation status: %d\n", result3);

    return 0;
}

#include <stdio.h>
#include <math.h>

#define CAPACITANCE 0.001
#define VOLTAGE_THRESHOLD 0.1

typedef struct {
    double capacitor_voltage;
    int inserted;
    double energy;
} SubModule;

void calculate_energy(SubModule *sm) {
    sm->energy = 0.5 * CAPACITANCE * sm->capacitor_voltage * sm->capacitor_voltage;
}

void balance_control(SubModule sms[], int n, double target_voltage) {
    double sum_voltage = 0.0;
    int count_inserted = 0;

    for (int i = 0; i < n; i++) {
        if (sms[i].inserted == 1) {
            sum_voltage += sms[i].capacitor_voltage;
            count_inserted++;
        }
    }

    if (count_inserted == 0) return;

    double avg_voltage = sum_voltage / count_inserted;

    if (fabs(avg_voltage - target_voltage) > VOLTAGE_THRESHOLD) {
        int highest_idx = -1;
        double highest_voltage = -1.0;

        int lowest_idx = -1;
        double lowest_voltage = 1000.0;

        for (int i = 0; i < n; i++) {
            if (sms[i].inserted == 1 && sms[i].capacitor_voltage > highest_voltage) {
                highest_voltage = sms[i].capacitor_voltage;
                highest_idx = i;
            }

            if (sms[i].inserted == 0 && sms[i].capacitor_voltage < lowest_voltage) {
                lowest_voltage = sms[i].capacitor_voltage;
                lowest_idx = i;
            }
        }

        if (highest_idx != -1 && lowest_idx != -1) {
            sms[highest_idx].inserted = 0;
            sms[lowest_idx].inserted = 1;
            sms[lowest_idx].capacitor_voltage = target_voltage;
        }
    }

    for (int i = 0; i < n; i++) {
        calculate_energy(&sms[i]);
    }
}

void print_sm_status(SubModule sms[], int n, const char *title) {
    printf("\n%s:\n", title);
    printf("Index | Voltage (V) | Inserted | Energy (J)\n");
    printf("------|-------------|----------|------------\n");

    for (int i = 0; i < n; i++) {
        printf("%5d | %11.2f | %8d | %10.4f\n", 
               i, sms[i].capacitor_voltage, sms[i].inserted, sms[i].energy);
    }
}

int main() {
    SubModule sms[6];

    double initial_voltages[] = {99.8, 100.1, 100.0, 99.9, 100.2, 99.7};
    int initial_inserted[] = {1, 1, 1, 1, 0, 0};

    for (int i = 0; i < 6; i++) {
        sms[i].capacitor_voltage = initial_voltages[i];
        sms[i].inserted = initial_inserted[i];
        calculate_energy(&sms[i]);
    }

    print_sm_status(sms, 6, "Initial Status");

    balance_control(sms, 6, 100.0);

    print_sm_status(sms, 6, "After Balance Control");

    return 0;
}

