#define PWM_DUTY_REG (*((volatile uint32_t*)0x40000000))
#define ADC_VOUT_REG (*((volatile uint32_t*)0x40000004))

static volatile uint32_t mock_adc_value = 0;
static volatile uint32_t mock_pwm_duty = 0;

#define PWM_DUTY_REG mock_pwm_duty
#define ADC_VOUT_REG mock_adc_value

void soft_start_control(int *current_voltage, int target_voltage, int delta_v_max) {
    if (*current_voltage < target_voltage) {
        int delta = target_voltage - *current_voltage;
        if (delta > delta_v_max) {
            delta = delta_v_max;
        }
        *current_voltage += delta;

        int duty_ratio = (*current_voltage * 1000) / target_voltage;
        if (duty_ratio > 1000) duty_ratio = 1000;
        PWM_DUTY_REG = duty_ratio;

        ADC_VOUT_REG = *current_voltage;
    }
}

int main() {
    int vin = 12000;
    int vtarget = 24000;
    int delta_v_max = 500;

    int current_voltage = 0;
    int time_ms = 0;
    int print_counter = 0;

    printf("DC/DC Soft Start Control Simulation\n");
    printf("Input Voltage: %d mV (%.1f V)\n", vin, vin/1000.0);
    printf("Target Voltage: %d mV (%.1f V)\n", vtarget, vtarget/1000.0);
    printf("Soft Start Time: 100ms\n");
    printf("Sampling Period: 1ms\n");
    printf("Max Voltage Change Rate: %d mV/ms (%.1f V/ms)\n\n", delta_v_max, delta_v_max/1000.0);

    printf("Time(ms)\tOutput Voltage(V)\n");
    printf("-----------------------------\n");

    while (current_voltage < vtarget) {
        soft_start_control(&current_voltage, vtarget, delta_v_max);
        time_ms++;
        print_counter++;

        if (print_counter >= 10) {
            printf("%d\t\t%.2f\n", time_ms, current_voltage/1000.0);
            print_counter = 0;
        }
    }

    if (print_counter > 0) {
        printf("%d\t\t%.2f\n", time_ms, current_voltage/1000.0);
    }

    printf("\nSoft start completed\n");
    printf("Final Voltage: %.2f V\n", current_voltage/1000.0);
    printf("Total Time: %d ms\n", time_ms);

    return 0;
}

#include <stdio.h>
#include <math.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

void vsg_pll_step(double grid_theta, double delta_t, double J, double D, double *theta, double *omega) {
    double delta_theta = grid_theta - *theta;
    double T_acc = delta_theta * D;
    *omega += (T_acc / J) * delta_t;
    *theta += *omega * delta_t;
    *theta = fmod(*theta + M_PI, 2 * M_PI) - M_PI;
}

int main() {
    double theta = 0.0;
    double omega = 314.16;
    double J = 0.1;
    double D = 10.0;
    double delta_t = 0.001;
    double t = 0.0;

    for (int i = 0; i < 200; i++) {
        double grid_theta;
        if (t < 0.1) {
            grid_theta = 314.16 * t;
        } else {
            grid_theta = 314.16 * t + 0.5;
        }

        vsg_pll_step(grid_theta, delta_t, J, D, &theta, &omega);

        if (i % 20 == 0) {
            printf("%.3f, %.4f, %.4f, %.4f\n", t, grid_theta, theta, omega);
        }

        t += delta_t;
    }

    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <unistd.h>

#define MODULE_A_STATUS   (*((volatile uint8_t*)0x40001000))
#define MODULE_A_CONTROL  (*((volatile uint8_t*)0x40001001))
#define MODULE_A_CURRENT  (*((volatile uint16_t*)0x40001002))
#define MODULE_B_STATUS   (*((volatile uint8_t*)0x40002000))
#define MODULE_B_CONTROL  (*((volatile uint8_t*)0x40002001))
#define MODULE_B_CURRENT  (*((volatile uint16_t*)0x40002002))

#define STATUS_WORKING      0x01
#define STATUS_READY        0x02
#define STATUS_FAULT        0x03
#define STATUS_MAINTENANCE  0x04

#define CMD_START_WORK      0x10
#define CMD_ENTER_MAINT     0x20

#define MAIN_CURRENT        100
#define BACKUP_CURRENT      100

typedef struct {
    volatile uint8_t* status_reg;
    volatile uint8_t* control_reg;
    volatile uint16_t* current_reg;
    uint8_t is_primary;
} PowerModule;

PowerModule module_a = {&MODULE_A_STATUS, &MODULE_A_CONTROL, &MODULE_A_CURRENT, 1};
PowerModule module_b = {&MODULE_B_STATUS, &MODULE_B_CONTROL, &MODULE_B_CURRENT, 0};

void init_modules(void) {
    *module_a.status_reg = STATUS_WORKING;
    *module_a.control_reg = CMD_START_WORK;
    *module_a.current_reg = MAIN_CURRENT;

    *module_b.status_reg = STATUS_READY;
    *module_b.control_reg = 0x00;
    *module_b.current_reg = BACKUP_CURRENT;
}

void print_status(const char* name, uint8_t status) {
    const char* status_str;
    switch(status) {
        case STATUS_WORKING: status_str = "WORKING"; break;
        case STATUS_READY: status_str = "READY"; break;
        case STATUS_FAULT: status_str = "FAULT"; break;
        case STATUS_MAINTENANCE: status_str = "MAINTENANCE"; break;
        default: status_str = "UNKNOWN"; break;
    }
    printf("%s Status: %s (0x%02X)\n", name, status_str, status);
}

uint16_t calculate_output_current(float decay_factor, float enhance_factor) {
    uint16_t main_current = *module_a.current_reg;
    uint16_t backup_current = *module_b.current_reg;

    return (uint16_t)(main_current * decay_factor + backup_current * enhance_factor);
}

void perform_redundant_switch(void) {
    printf("\n=== 开始冗余切换 ===\n");

    float decay_factor = 1.0;
    float enhance_factor = 0.0;
    float step = 0.25;

    for(int i = 0; i <= 4; i++) {
        uint16_t output_current = calculate_output_current(decay_factor, enhance_factor);
        printf("切换阶段 %d: 衰减系数=%.2f, 增强系数=%.2f, 输出电流=%uA\n", 
               i, decay_factor, enhance_factor, output_current);

        if(i < 4) {
            decay_factor -= step;
            enhance_factor += step;
            usleep(200000);
        }
    }

    *module_a.status_reg = STATUS_MAINTENANCE;
    *module_a.control_reg = CMD_ENTER_MAINT;

    *module_b.status_reg = STATUS_WORKING;
    *module_b.control_reg = CMD_START_WORK;

    module_a.is_primary = 0;
    module_b.is_primary = 1;

    printf("切换完成: Module_A进入维修状态, Module_B成为主模块\n");
}

void check_and_handle_fault(void) {
    if(*module_a.status_reg == STATUS_FAULT && module_a.is_primary) {
        printf("\n检测到主模块故障! 触发冗余切换...\n");
        perform_redundant_switch();
    }
}

int main(void) {
    printf("=== 电力电子冗余模块切换系统 ===\n\n");

    init_modules();

    printf("1. 系统初始化完成:\n");
    print_status("Module_A", *module_a.status_reg);
    print_status("Module_B", *module_b.status_reg);
    printf("Module_A电流: %uA\n", *module_a.current_reg);
    printf("Module_B电流: %uA\n", *module_b.current_reg);

    printf("\n2. 主模块正常工作状态:\n");
    uint16_t initial_output = calculate_output_current(1.0, 0.0);
    printf("输出电流 = 主模块电流 = %uA\n", initial_output);

    printf("\n3. 模拟主模块故障...\n");
    *module_a.status_reg = STATUS_FAULT;
    print_status("Module_A", *module_a.status_reg);

    check_and_handle_fault();

    printf("\n4. 最终状态:\n");
    print_status("Module_A", *module_a.status_reg);
    print_status("Module_B", *module_b.status_reg);
    printf("Module_A电流: %uA\n", *module_a.current_reg);
    printf("Module_B电流: %uA\n", *module_b.current_reg);
    uint16_t final_output = calculate_output_current(0.0, 1.0);
    printf("最终输出电流 = 新主模块电流 = %uA\n", final_output);

    return 0;
}

#include <stdio.h>
#include <math.h>

#define VDC 300.0
#define R 10.0
#define L 0.01
#define TS 0.0001

typedef struct {
    double v_alpha;
    double v_beta;
} VoltageVector;

typedef struct {
    int sa;
    int sb;
    int sc;
} SwitchState;

void precompute_voltage_vectors(VoltageVector vectors[8]) {
    const double two_thirds = 2.0 / 3.0;
    const double sqrt3_div3 = sqrt(3.0) / 3.0;

    for (int i = 0; i < 8; i++) {
        int sa = (i >> 2) & 1;
        int sb = (i >> 1) & 1;
        int sc = i & 1;

        vectors[i].v_alpha = two_thirds * VDC * (sa - 0.5 * (sb + sc));
        vectors[i].v_beta = sqrt3_div3 * VDC * (sb - sc);
    }
}

void predict_current(double i_alpha_k, double i_beta_k, double v_alpha, double v_beta,
                     double* i_alpha_k1, double* i_beta_k1) {
    double factor = 1.0 - R * TS / L;
    double gain = TS / L;

    *i_alpha_k1 = factor * i_alpha_k + gain * v_alpha;
    *i_beta_k1 = factor * i_beta_k + gain * v_beta;
}

double compute_cost(double i_alpha_ref, double i_beta_ref, 
                    double i_alpha_k1, double i_beta_k1) {
    double error_alpha = i_alpha_ref - i_alpha_k1;
    double error_beta = i_beta_ref - i_beta_k1;
    return error_alpha * error_alpha + error_beta * error_beta;
}

void find_optimal_switch_state(double i_alpha_k, double i_beta_k,
                               double i_alpha_ref, double i_beta_ref,
                               VoltageVector vectors[8],
                               int* optimal_state, double* min_cost) {
    *min_cost = 1e20;
    *optimal_state = 0;

    for (int i = 0; i < 8; i++) {
        double i_alpha_k1, i_beta_k1;
        predict_current(i_alpha_k, i_beta_k, 
                       vectors[i].v_alpha, vectors[i].v_beta,
                       &i_alpha_k1, &i_beta_k1);

        double cost = compute_cost(i_alpha_ref, i_beta_ref, i_alpha_k1, i_beta_k1);

        if (cost < *min_cost) {
            *min_cost = cost;
            *optimal_state = i;
        }
    }
}

void print_switch_state(int state) {
    int sa = (state >> 2) & 1;
    int sb = (state >> 1) & 1;
    int sc = state & 1;
    printf("%d%d%d", sa, sb, sc);
}

int main() {
    VoltageVector vectors[8];
    precompute_voltage_vectors(vectors);

    printf("逆变器MPC单步成本函数优化算法\n");
    printf("==============================\n\n");

