#include <stdio.h>
#include <math.h>

typedef struct {
    double Vin;
    double Vout;
    double Vref;
    double Iload;
    double Duty;
    double integral_error;
    double Kp;
    double Ki;
} BuckConverter;

void update_buck_control(BuckConverter *buck, double Vin_new, double Vout_measured, double Iload_new) {
    double prev_integral_error = buck->integral_error;

    buck->Vin = Vin_new;
    buck->Vout = Vout_measured;
    buck->Iload = Iload_new;

    double Duty_ff = buck->Vref / Vin_new;
    if (Duty_ff < 0.0) Duty_ff = 0.0;
    if (Duty_ff > 0.95) Duty_ff = 0.95;

    double error = buck->Vref - Vout_measured;
    buck->integral_error += error;

    double Duty_fb = buck->Kp * error + buck->Ki * buck->integral_error;

    double Duty_total = Duty_ff + Duty_fb;

    if (Duty_total > 0.95) {
        Duty_total = 0.95;
        buck->integral_error = prev_integral_error;
    }
    if (Duty_total < 0.05) {
        Duty_total = 0.05;
        buck->integral_error = prev_integral_error;
    }

    buck->Duty = Duty_total;
}

int main() {
    BuckConverter buck;

    buck.Vref = 5.0;
    buck.Kp = 0.1;
    buck.Ki = 0.01;
    buck.Vin = 0.0;
    buck.Vout = 0.0;
    buck.Iload = 0.0;
    buck.Duty = 0.0;
    buck.integral_error = 0.0;

    printf("Buck Converter Control Simulation\n");
    printf("=================================\n");

    printf("Test 1: Normal operation\n");
    update_buck_control(&buck, 12.0, 4.8, 1.0);
    printf("Vin=%.2f V, Vout=%.2f V, Iload=%.2f A => Duty=%.2f%%\n", 
