#include <stdio.h>
#include <stdlib.h>

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float prev_error;
} PID_Controller;

void PID_Init(PID_Controller *pid, float kp, float ki, float kd) {
    pid->Kp = kp;
    pid->Ki = ki;
    pid->Kd = kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
}

float PID_Update(PID_Controller *pid, float setpoint, float measured, float dt) {
    float error = setpoint - measured;

    pid->integral += error * dt;

    float derivative = (error - pid->prev_error) / dt;

    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    pid->prev_error = error;

    return output;
}

int main() {
    PID_Controller pid;
    PID_Init(&pid, 0.8f, 0.2f, 0.1f);

    float setpoint = 400.0f;
    float measured_voltages[] = {390.0f, 395.0f, 398.0f, 401.0f, 400.0f};
    float dt = 0.1f;
    int steps = 5;

    printf("船舶电力系统PID稳压控制模拟\n");
    printf("设定电压: %.1f V\n", setpoint);
    printf("PID参数: Kp=%.1f, Ki=%.1f, Kd=%.1f\n", pid.Kp, pid.Ki, pid.Kd);
    printf("时间步长: %.1f 秒\n\n", dt);

    for (int i = 0; i < steps; i++) {
        float measured = measured_voltages[i];
        float output = PID_Update(&pid, setpoint, measured, dt);

        printf("时间步 %d: 测量电压=%.1f V, PID输出调整量=%.3f\n", 
               i+1, measured, output);
    }

    printf("\n积分项最终值: %.3f\n", pid.integral);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define BATTERY_CAPACITY 100.0
#define MAX_POWER 20.0
#define INITIAL_SOC 30.0
#define EFFICIENCY 0.95

typedef enum {
    VALLEY,     // 谷时段 0:00-8:00
    PEAK,       // 峰时段 16:00-20:00
    NORMAL      // 平时段 8:00-16:00, 20:00-24:00
} TimePeriod;

typedef struct {
    double price;
    const char* name;
} PriceInfo;

const PriceInfo price_table[3] = {
    {0.3, "谷时段"},
    {1.2, "峰时段"},
    {0.6, "平时段"}
};

TimePeriod get_time_period(int hour) {
    if (hour >= 0 && hour < 8) {
        return VALLEY;
    } else if (hour >= 8 && hour < 16) {
        return NORMAL;
    } else if (hour >= 16 && hour < 20) {
        return PEAK;
    } else {
        return NORMAL;
    }
}

double calculate_charge(double soc, double power, int hour) {
    TimePeriod period = get_time_period(hour);

    if (period == VALLEY) {
        double available_capacity = BATTERY_CAPACITY - soc;
        double max_charge = power * EFFICIENCY;

        if (available_capacity >= max_charge) {
            return max_charge;
        } else {
            return available_capacity;
        }
    }

    return 0.0;
}

double calculate_discharge(double soc, double power, int hour) {
    TimePeriod period = get_time_period(hour);

    if (period == PEAK) {
        double max_discharge = power / EFFICIENCY;

        if (soc >= max_discharge) {
            return max_discharge;
        } else {
            return soc;
        }
    }

    return 0.0;
}

int main() {
    double soc = INITIAL_SOC;
    double total_charge = 0.0;
    double total_discharge = 0.0;
    double total_cost = 0.0;
    double total_income = 0.0;

    printf("储能系统24小时模拟运行\n");
    printf("初始电量: %.2f kWh\n\n", soc);

    for (int hour = 0; hour < 24; hour++) {
        TimePeriod period = get_time_period(hour);
        double charge_amount = 0.0;
        double discharge_amount = 0.0;
        double power_used = 0.0;
        double old_soc = soc;

        if (period == VALLEY) {
            charge_amount = calculate_charge(soc, MAX_POWER, hour);
            if (charge_amount > 0) {
                power_used = charge_amount / EFFICIENCY;
                soc += charge_amount;
                total_charge += charge_amount;
                total_cost += power_used * price_table[period].price;
            }
        } else if (period == PEAK) {
            discharge_amount = calculate_discharge(soc, MAX_POWER, hour);
            if (discharge_amount > 0) {
                power_used = discharge_amount * EFFICIENCY;
                soc -= discharge_amount;
                total_discharge += discharge_amount;
                total_income += power_used * price_table[period].price;
            }
        }

        printf("Hour %2d: %s, ", hour, price_table[period].name);

        if (charge_amount > 0) {
            printf("充电%.2fkW, 电量从%.2f增加到%.2f", 
                   charge_amount / EFFICIENCY, old_soc, soc);
        } else if (discharge_amount > 0) {
            printf("放电%.2fkW, 电量从%.2f减少到%.2f", 
                   discharge_amount * EFFICIENCY, old_soc, soc);
        } else {
            printf("保持电量不变, 当前电量%.2f", soc);
        }
        printf("\n");
    }

    printf("\n=== 统计结果 ===\n");
    printf("总充电量: %.2f kWh\n", total_charge);
    printf("总放电量: %.2f kWh\n", total_discharge);
    printf("总支出: %.2f 元\n", total_cost);
    printf("总收入: %.2f 元\n", total_income);
    printf("净收益: %.2f 元\n", total_income - total_cost);

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define PI 3.14159265358979323846
#define SAMPLE_RATE 2000.0  // 2kHz采样率
#define SAMPLE_POINTS 200   // 采样点数
#define BASE_FREQ 50.0      // 基波频率50Hz
#define HARMONIC_5 250.0    // 5次谐波250Hz
#define HARMONIC_7 350.0    // 7次谐波350Hz

// 谐波分析结果结构体
typedef struct {
    double fundamental;  // 基波幅值
    double harmonic5;    // 5次谐波幅值
    double harmonic7;    // 7次谐波幅值
} HarmonicAnalysis;

// 补偿计算结果结构体
typedef struct {
    double comp_current5;  // 5次谐波补偿电流
    double comp_current7;  // 7次谐波补偿电流
} CompensationResult;

// 谐波分析函数 - 使用简化FFT方法
HarmonicAnalysis analyze_harmonics(double* samples, int num_samples) {
    HarmonicAnalysis result = {0};

    // 计算基波幅值
    double sum_real = 0, sum_imag = 0;
    for (int n = 0; n < num_samples; n++) {
        double angle = 2 * PI * BASE_FREQ * n / SAMPLE_RATE;
        sum_real += samples[n] * cos(angle);
        sum_imag += samples[n] * sin(angle);
    }
    result.fundamental = 2 * sqrt(sum_real*sum_real + sum_imag*sum_imag) / num_samples;

    // 计算5次谐波幅值
    sum_real = 0; sum_imag = 0;
    for (int n = 0; n < num_samples; n++) {
        double angle = 2 * PI * HARMONIC_5 * n / SAMPLE_RATE;
        sum_real += samples[n] * cos(angle);
        sum_imag += samples[n] * sin(angle);
    }
    result.harmonic5 = 2 * sqrt(sum_real*sum_real + sum_imag*sum_imag) / num_samples;

    // 计算7次谐波幅值
    sum_real = 0; sum_imag = 0;
    for (int n = 0; n < num_samples; n++) {
        double angle = 2 * PI * HARMONIC_7 * n / SAMPLE_RATE;
        sum_real += samples[n] * cos(angle);
        sum_imag += samples[n] * sin(angle);
    }
    result.harmonic7 = 2 * sqrt(sum_real*sum_real + sum_imag*sum_imag) / num_samples;

    return result;
}

// 有源补偿计算函数
CompensationResult calculate_compensation(HarmonicAnalysis analysis) {
    CompensationResult result = {0};
    double Kp = 1.2;  // 比例系数
    double target5 = 0.5;  // 5次谐波目标幅值
    double target7 = 0.3;  // 7次谐波目标幅值

    // 补偿电流 = Kp * (检测谐波 - 目标阈值)
    if (analysis.harmonic5 > target5) {
        result.comp_current5 = Kp * (analysis.harmonic5 - target5);
    }

    if (analysis.harmonic7 > target7) {
        result.comp_current7 = Kp * (analysis.harmonic7 - target7);
    }

    return result;
}

// 生成模拟信号
void generate_signal(double* samples, int num_samples) {
    for (int i = 0; i < num_samples; i++) {
        double t = i / SAMPLE_RATE;
        // 基波: 10A @ 50Hz
        // 5次谐波: 2A @ 250Hz
        // 7次谐波: 1.5A @ 350Hz
        samples[i] = 10.0 * sin(2 * PI * BASE_FREQ * t) +
                     2.0 * sin(2 * PI * HARMONIC_5 * t) +
                     1.5 * sin(2 * PI * HARMONIC_7 * t);
    }
}

int main() {
    printf("=== 整流器输入电流谐波抑制算法模拟 ===\n\n");

    // 1. 生成模拟信号
    double samples[SAMPLE_POINTS];
    generate_signal(samples, SAMPLE_POINTS);

    printf("1. 原始信号特征:\n");
    printf("   - 基波: 50Hz, 幅值10A\n");
    printf("   - 5次谐波: 250Hz, 幅值2A\n");
    printf("   - 7次谐波: 350Hz, 幅值1.5A\n");
    printf("   - 采样频率: %.0f Hz, 采样点数: %d\n\n", SAMPLE_RATE, SAMPLE_POINTS);

    // 2. 谐波分析
    HarmonicAnalysis analysis = analyze_harmonics(samples, SAMPLE_POINTS);

    printf("2. 分析得到的谐波幅值:\n");
    printf("   - 基波幅值: %.3f A\n", analysis.fundamental);
    printf("   - 5次谐波幅值: %.3f A\n", analysis.harmonic5);
    printf("   - 7次谐波幅值: %.3f A\n\n", analysis.harmonic7);

    // 3. 补偿计算
    CompensationResult compensation = calculate_compensation(analysis);

    printf("3. 计算出的补偿电流参考值:\n");
    printf("   - 5次谐波补偿电流: %.3f A\n", compensation.comp_current5);
    printf("   - 7次谐波补偿电流: %.3f A\n\n", compensation.comp_current7);

    // 4. 验证补偿效果
    printf("4. 补偿效果验证:\n");
    printf("   - 5次谐波抑制前: %.3f A, 抑制后: %.3f A\n", 
           analysis.harmonic5, analysis.harmonic5 - compensation.comp_current5);
    printf("   - 7次谐波抑制前: %.3f A, 抑制后: %.3f A\n", 
           analysis.harmonic7, analysis.harmonic7 - compensation.comp_current7);

    // 检查是否达到目标
    double after_comp5 = analysis.harmonic5 - compensation.comp_current5;
    double after_comp7 = analysis.harmonic7 - compensation.comp_current7;

