}

#include <stdio.h>
#include <math.h>

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float epsilon;
    float last_error;
    float integral;
    float last_measurement;
} PID_Controller;

void PID_Init(PID_Controller *pid, float Kp, float Ki, float Kd, float epsilon) {
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->epsilon = epsilon;
    pid->last_error = 0.0f;
    pid->integral = 0.0f;
    pid->last_measurement = 0.0f;
}

float PID_Calculate(PID_Controller *pid, float setpoint, float measurement) {
    float error = setpoint - measurement;

    if (fabsf(error) > pid->epsilon) {
        pid->integral = 0.0f;
    } else {
        pid->integral += error;
    }

    float derivative = measurement - pid->last_measurement;

    float output = pid->Kp * error + pid->Ki * pid->integral - pid->Kd * derivative;

    pid->last_error = error;
    pid->last_measurement = measurement;

    return output;
}

int main() {
    PID_Controller pid;
    PID_Init(&pid, 1.2f, 0.5f, 0.3f, 10.0f);

    float test_setpoints[] = {100.0f, 100.0f, 100.0f, 100.0f, 100.0f};
    float test_measurements[] = {80.0f, 85.0f, 95.0f, 99.0f, 100.5f};

    printf("周期号 | 设定值 | 测量值 | 控制输出\n");
    printf("------------------------------------\n");

    for (int i = 0; i < 5; i++) {
        float output = PID_Calculate(&pid, test_setpoints[i], test_measurements[i]);
        printf("%6d | %6.1f | %6.1f | %8.2f\n", 
               i + 1, test_setpoints[i], test_measurements[i], output);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

typedef struct {
    float target_power;
    float current_power;
    float pwm_duty;
    float kp;
    float ki;
    float integral_error;
} PowerControl;

void power_control_init(PowerControl *pc, float target, float kp, float ki) {
    pc->target_power = target;
    pc->current_power = 0.0f;
    pc->pwm_duty = 0.0f;
    pc->kp = kp;
    pc->ki = ki;
    pc->integral_error = 0.0f;
}

float read_power_sensor(void) {
    static float base_power = 0.0f;
    static int initialized = 0;

    if (!initialized) {
        srand(time(NULL));
        base_power = 400.0f + (rand() % 200);
        initialized = 1;
    }

    float noise = ((rand() % 100) - 50) / 10.0f;
    return base_power + noise;
}

void update_pwm(PowerControl *pc) {
    float error = pc->target_power - pc->current_power;
    pc->integral_error += error;

    float new_duty = pc->kp * error + pc->ki * pc->integral_error;

    if (new_duty < 0.0f) {
        pc->pwm_duty = 0.0f;
    } else if (new_duty > 1.0f) {
        pc->pwm_duty = 1.0f;
    } else {
        pc->pwm_duty = new_duty;
    }
}

void apply_pwm(float duty) {
    printf("Applied PWM duty: %.3f\n", duty);
}

void power_control_step(PowerControl *pc) {
    pc->current_power = read_power_sensor();
    update_pwm(pc);
    apply_pwm(pc->pwm_duty);
}

int main() {
    PowerControl pc;
    power_control_init(&pc, 500.0f, 0.01f, 0.001f);

    for (int i = 1; i <= 10; i++) {
        printf("Cycle %d: ", i);
        power_control_step(&pc);
        printf("current=%.1fW, target=%.1fW, duty=%.3f\n\n", 
               pc.current_power, pc.target_power, pc.pwm_duty);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>

#define SQRT3 1.73205080757f
#define COS120 -0.5f
#define SIN120 0.86602540378f

void calculate_negative_sequence(float ua, float ub, float uc, float *alpha, float *beta) {
    float alpha_val = ua;
    float beta_val = (ub - uc) / SQRT3;

    float alpha_cos120 = alpha_val * COS120;
    float beta_sin120 = beta_val * SIN120;
    float alpha_sin120 = alpha_val * SIN120;
    float beta_cos120 = beta_val * COS120;

    *alpha = (alpha_cos120 + beta_sin120) / 3.0f;
    *beta = (-alpha_sin120 + beta_cos120) / 3.0f;
}

void compensation(float *mod_a, float *mod_b, float *mod_c, float alpha_neg, float beta_neg) {
    float ua_comp = alpha_neg;
    float ub_comp = -0.5f * alpha_neg + (SQRT3/2.0f) * beta_neg;
    float uc_comp = -0.5f * alpha_neg - (SQRT3/2.0f) * beta_neg;

    *mod_a = *mod_a - ua_comp;
    *mod_b = *mod_b - ub_comp;
    *mod_c = *mod_c - uc_comp;
}

int main() {
    float ua = 1.0f;
    float ub = -0.5f;
    float uc = -0.5f;

    float alpha_neg, beta_neg;
    calculate_negative_sequence(ua, ub, uc, &alpha_neg, &beta_neg);
    printf("alpha_neg=%.3f, beta_neg=%.3f\n", alpha_neg, beta_neg);

    float mod_a = 0.8f;
    float mod_b = 0.4f;
    float mod_c = 0.4f;

    compensation(&mod_a, &mod_b, &mod_c, alpha_neg, beta_neg);
    printf("mod_a=%.3f, mod_b=%.3f, mod_c=%.3f\n", mod_a, mod_b, mod_c);

    return 0;
}

#include <stdio.h>
