#define EEPROM_SIZE 1024
#define PARAM_AREA_SIZE 256
#define FAULT_AREA_SIZE 768
#define MAX_PARAMS 64
#define MAX_FAULTS 256
#define UNINITIALIZED_VALUE 0xFF

static uint8_t eeprom_memory[EEPROM_SIZE];

void eeprom_init(void) {
    memset(eeprom_memory, UNINITIALIZED_VALUE, EEPROM_SIZE);
}

int write_parameter(int index, float value) {
    if (index < 0 || index >= MAX_PARAMS) {
        return -1;
    }

    int addr = index * sizeof(float);
    if (addr + sizeof(float) > PARAM_AREA_SIZE) {
        return -1;
    }

    uint8_t *bytes = (uint8_t*)&value;
    for (int i = 0; i < sizeof(float); i++) {
        eeprom_memory[addr + i] = bytes[i];
    }

    return 0;
}

float read_parameter(int index) {
    if (index < 0 || index >= MAX_PARAMS) {
        return 0.0f;
    }

    int addr = index * sizeof(float);
    if (addr + sizeof(float) > PARAM_AREA_SIZE) {
        return 0.0f;
    }

    float value;
    uint8_t *bytes = (uint8_t*)&value;

    for (int i = 0; i < sizeof(float); i++) {
        bytes[i] = eeprom_memory[addr + i];
    }

    return value;
}

int log_fault(uint32_t timestamp, uint8_t code) {
    static int fault_index = 0;

    if (fault_index >= MAX_FAULTS) {
        fault_index = 0;
    }

    int base_addr = PARAM_AREA_SIZE + fault_index * (sizeof(uint32_t) + sizeof(uint8_t));

    if (base_addr + sizeof(uint32_t) + sizeof(uint8_t) > EEPROM_SIZE) {
        return -1;
    }

    uint8_t *timestamp_bytes = (uint8_t*)&timestamp;
    for (int i = 0; i < sizeof(uint32_t); i++) {
        eeprom_memory[base_addr + i] = timestamp_bytes[i];
    }

    eeprom_memory[base_addr + sizeof(uint32_t)] = code;

    int current_index = fault_index;
    fault_index++;

    return current_index;
}

int read_fault(int index, uint32_t *timestamp, uint8_t *code) {
    if (index < 0 || index >= MAX_FAULTS) {
        return -1;
    }

    int base_addr = PARAM_AREA_SIZE + index * (sizeof(uint32_t) + sizeof(uint8_t));

    if (base_addr + sizeof(uint32_t) + sizeof(uint8_t) > EEPROM_SIZE) {
        return -1;
    }

    uint8_t timestamp_bytes[sizeof(uint32_t)];
    for (int i = 0; i < sizeof(uint32_t); i++) {
        timestamp_bytes[i] = eeprom_memory[base_addr + i];
    }

    *timestamp = *(uint32_t*)timestamp_bytes;
    *code = eeprom_memory[base_addr + sizeof(uint32_t)];

    return 0;
}

int main() {
    printf("=== EEPROM Simulation Test ===\n");

    eeprom_init();
    printf("EEPROM initialization completed\n");

    printf("\n1. Parameter write test:\n");
    int ret;

    ret = write_parameter(0, 12.5f);
    printf("Write parameter[0]=12.5: %s\n", ret == 0 ? "Success" : "Failed");

    ret = write_parameter(1, 220.0f);
    printf("Write parameter[1]=220.0: %s\n", ret == 0 ? "Success" : "Failed");

    ret = write_parameter(2, 3.14f);
    printf("Write parameter[2]=3.14: %s\n", ret == 0 ? "Success" : "Failed");

    printf("\n2. Parameter read test:\n");
    printf("Read parameter[0]: %.2f\n", read_parameter(0));
    printf("Read parameter[1]: %.2f\n", read_parameter(1));
    printf("Read parameter[2]: %.2f\n", read_parameter(2));

    printf("\n3. Fault logging test:\n");
    int idx1 = log_fault(1000, 0x01);
    printf("Log fault 1: timestamp=1000, code=0x01, index=%d\n", idx1);

    int idx2 = log_fault(2000, 0x02);
    printf("Log fault 2: timestamp=2000, code=0x02, index=%d\n", idx2);

    int idx3 = log_fault(3000, 0x03);
    printf("Log fault 3: timestamp=3000, code=0x03, index=%d\n", idx3);

    printf("\n4. Fault reading test:\n");
    uint32_t ts;
    uint8_t code;

    for (int i = 0; i < 3; i++) {
        if (read_fault(i, &ts, &code) == 0) {
            printf("Fault record[%d]: timestamp=%u, code=0x%02X\n", i, ts, code);
        } else {
            printf("Read fault record[%d] failed\n", i);
        }
    }

    printf("\n5. Boundary test:\n");
    ret = write_parameter(-1, 99.9f);
    printf("Write parameter[-1]: %s\n", ret == -1 ? "Failed(correct)" : "Success(error)");

    ret = write_parameter(64, 99.9f);
    printf("Write parameter[64]: %s\n", ret == -1 ? "Failed(correct)" : "Success(error)");

    ret = write_parameter(63, 99.9f);
    printf("Write parameter[63]: %s\n", ret == 0 ? "Success" : "Failed");

    float val = read_parameter(-1);
    printf("Read parameter[-1]: %.2f (should be 0.0)\n", val);

    val = read_parameter(64);
    printf("Read parameter[64]: %.2f (should be 0.0)\n", val);

    printf("\n=== Test completed ===\n");

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <time.h>

#define PI 3.14159265358979323846
#define FS 2000.0f
#define R 0.95f

typedef struct {
    float b0, b1, b2;
    float a1, a2;
} FilterCoeff;

float notch_filter(float input, float *state_x, float *state_y, 
                   float b0, float b1, float b2, float a1, float a2) {
    float output;

    output = b0 * input + b1 * state_x[0] + b2 * state_x[1]
             - a1 * state_y[0] - a2 * state_y[1];

    state_x[1] = state_x[0];
    state_x[0] = input;

    state_y[1] = state_y[0];
    state_y[0] = output;

    return output;
}

void calculate_notch_coeff(float freq, FilterCoeff *coeff) {
    float omega0 = 2.0f * PI * freq / FS;
    float cos_omega0 = cosf(omega0);

    coeff->b0 = 1.0f;
    coeff->b1 = -2.0f * cos_omega0;
    coeff->b2 = 1.0f;

    coeff->a1 = -2.0f * R * cos_omega0;
    coeff->a2 = R * R;
}

float generate_test_signal(int n) {
    float t = n / FS;
    float signal = 0.0f;

    signal += 1.0f * sinf(2.0f * PI * 50.0f * t);
    signal += 0.3f * sinf(2.0f * PI * 150.0f * t);
    signal += 0.2f * sinf(2.0f * PI * 250.0f * t);
    signal += 0.15f * sinf(2.0f * PI * 350.0f * t);

    signal += 0.05f * ((float)rand() / RAND_MAX - 0.5f);

    return signal;
}

int main() {
    srand(time(NULL));

    FilterCoeff coeff_3rd, coeff_5th, coeff_7th;
    calculate_notch_coeff(150.0f, &coeff_3rd);
    calculate_notch_coeff(250.0f, &coeff_5th);
    calculate_notch_coeff(350.0f, &coeff_7th);

    float state_x1[2] = {0, 0};
    float state_y1[2] = {0, 0};
    float state_x2[2] = {0, 0};
    float state_y2[2] = {0, 0};
    float state_x3[2] = {0, 0};
    float state_y3[2] = {0, 0};

    printf("PLL前置抗谐波干扰数字滤波器测试\n");
    printf("采样频率: %.0f Hz\n", FS);
    printf("滤除谐波: 150Hz(3次), 250Hz(5次), 350Hz(7次)\n");
    printf("极点半径: %.2f\n\n", R);

    for (int i = 0; i < 20; i++) {
        float input = generate_test_signal(i);

        float output1 = notch_filter(input, state_x1, state_y1,
                                    coeff_3rd.b0, coeff_3rd.b1, coeff_3rd.b2,
                                    coeff_3rd.a1, coeff_3rd.a2);

        float output2 = notch_filter(output1, state_x2, state_y2,
                                    coeff_5th.b0, coeff_5th.b1, coeff_5th.b2,
                                    coeff_5th.a1, coeff_5th.a2);

        float output3 = notch_filter(output2, state_x3, state_y3,
                                    coeff_7th.b0, coeff_7th.b1, coeff_7th.b2,
                                    coeff_7th.a1, coeff_7th.a2);

        printf("采样点%d: 输入=%.6f, 输出=%.6f\n", i, input, output3);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int id;
    float voltage;
    float threshold;
    int alarm_flag;
} Capacitor;

void check_voltage_balance(Capacitor caps[], int n, float tolerance) {
    if (n <= 0) return;

    float sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += caps[i].voltage;
    }
    float avg_voltage = sum / n;

    printf("平均电压: %.1fV\n", avg_voltage);

    for (int i = 0; i < n; i++) {
        float deviation = ((caps[i].voltage - avg_voltage) / avg_voltage) * 100.0;
        if (deviation > tolerance || deviation < -tolerance) {
            printf("均压检查: 电容%d电压偏差过大(%.1f%%)\n", caps[i].id, deviation);
        }
    }
}

void detect_overvoltage(Capacitor caps[], int n) {
    for (int i = 0; i < n; i++) {
        if (caps[i].voltage > caps[i].threshold) {
            caps[i].alarm_flag = 1;
            printf("电容%d: 电压=%.1fV, 状态=过压告警\n", caps[i].id, caps[i].voltage);
        }
    }
}

void protection_action(Capacitor caps[], int n) {
    for (int i = 0; i < n; i++) {
        if (caps[i].alarm_flag == 1) {
            caps[i].voltage = caps[i].threshold * 0.95;
            caps[i].alarm_flag = 0;
        }
    }
    printf("保护动作执行完成\n");
}

int main() {
    Capacitor caps[5];

    caps[0] = (Capacitor){1, 105.0, 110.0, 0};
    caps[1] = (Capacitor){2, 112.5, 110.0, 0};
    caps[2] = (Capacitor){3, 108.0, 115.0, 0};
    caps[3] = (Capacitor){4, 102.0, 110.0, 0};
    caps[4] = (Capacitor){5, 107.5, 110.0, 0};

    printf("初始状态:\n");
    for (int i = 0; i < 5; i++) {
        printf("电容%d: 电压=%.1fV, 阈值=%.1fV\n", caps[i].id, caps[i].voltage, caps[i].threshold);
    }

    printf("\n均压检查:\n");
    check_voltage_balance(caps, 5, 5.0);

    printf("\n过压检测:\n");
    detect_overvoltage(caps, 5);

    printf("\n保护动作:\n");
    protection_action(caps, 5);

    printf("\n最终状态:\n");
    for (int i = 0; i < 5; i++) {
        const char* status = caps[i].alarm_flag == 1 ? "过压告警" : "正常";
        printf("电容%d: 电压=%.1fV, 状态=%s\n", caps[i].id, caps[i].voltage, status);
    }

    return 0;
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define PI 3.14159265358979323846

double calculate_power_factor(double voltage_angle, double current_angle) {
    double voltage_rad = voltage_angle * PI / 180.0;
    double current_rad = current_angle * PI / 180.0;
    double phase_diff = fabs(voltage_rad - current_rad);
    return cos(phase_diff);
}

double closed_loop_control(double target_pf, double current_pf, double kp) {
    if (current_pf < target_pf) {
        return kp * (target_pf - current_pf);
    }
    return 0.0;
}

int main() {
    double target_pf = 0.99;
    double kp = 0.5;

    double test_data[5][2] = {
        {0, 10},
        {5, 15},
        {10, 18},
        {15, 20},
        {20, 22}
    };

    printf("Rectifier Power Factor Closed-loop Control Simulation\n");
    printf("Target Power Factor: %.2f\n", target_pf);
    printf("KP: %.1f\n\n", kp);
    printf("Voltage Angle(deg)\tCurrent Angle(deg)\tCurrent PF\tAdjustment\tStatus\n");
    printf("----------------------------------------------------------------------------\n");

    for (int i = 0; i < 5; i++) {
        double voltage_angle = test_data[i][0];
        double current_angle = test_data[i][1];
        double current_pf = calculate_power_factor(voltage_angle, current_angle);
        double adjustment = closed_loop_control(target_pf, current_pf, kp);
        const char* status = (current_pf >= target_pf) ? "OK" : "NEED ADJUST";

        printf("%.1f\t\t\t%.1f\t\t\t%.4f\t\t%.4f\t\t%s\n",
               voltage_angle, current_angle, current_pf, adjustment, status);
    }

    return 0;
}

#include <stdio.h>

float delay_compensation(float current_u, float *prev_u) {
    float u_comp = current_u + (current_u - *prev_u);
    *prev_u = current_u;
    return u_comp;
}

int main() {
    float prev_u = 0.0f;
    float input_sequence[] = {1.0f, 2.0f, 1.5f, 3.0f};
    int num_samples = sizeof(input_sequence) / sizeof(input_sequence[0]);

    printf("DC/DC变换器一拍延迟补偿算法模拟\n");
    printf("补偿公式: u_comp[k] = u[k] + (u[k] - u[k-1])\n");
    printf("初始状态: u[k-1] = %.3f\n\n", prev_u);

    for (int i = 0; i < num_samples; i++) {
        float current_u = input_sequence[i];
        float u_comp = delay_compensation(current_u, &prev_u);

        printf("周期%d: u[k]=%.3f, u_comp=%.3f, 更新后u[k-1]=%.3f\n", 
               i + 1, current_u, u_comp, prev_u);
    }

    return 0;
}

#include <stdio.h>
