#include <stdio.h>
#include <math.h>
#include <float.h>

#define EPSILON 1e-6

double calculate_trip_time(double current, double base_current, double time_multiplier, char curve_type) {
    if (current < base_current - EPSILON) {
        return -1.0;
    }

    if (fabs(current - base_current) < EPSILON) {
        return -1.0;
    }

    double ratio = current / base_current;

    switch (curve_type) {
        case 'I':
            if (ratio < 1.0 + EPSILON) {
                return -1.0;
            }
            return time_multiplier * 0.14 / (pow(ratio, 0.02) - 1.0);

        case 'V':
            if (ratio < 1.0 + EPSILON) {
                return -1.0;
            }
            return time_multiplier * 13.5 / (ratio - 1.0);

        case 'E':
            if (ratio < 1.0 + EPSILON) {
                return -1.0;
            }
            return time_multiplier * 80.0 / (pow(ratio, 2.0) - 1.0);

        default:
            return -1.0;
    }
}

int main() {
    printf("反时限过流保护算法测试\n");
    printf("=====================\n\n");

    double result;

    result = calculate_trip_time(5.0, 4.0, 1.0, 'I');
    printf("测试1: 电流=5.0A, 基准=4.0A, 乘数=1.0, 曲线=I => 跳闸时间=%.6f秒\n", result);

    result = calculate_trip_time(6.0, 4.0, 2.5, 'V');
    printf("测试2: 电流=6.0A, 基准=4.0A, 乘数=2.5, 曲线=V => 跳闸时间=%.6f秒\n", result);

    result = calculate_trip_time(8.0, 4.0, 0.5, 'E');
    printf("测试3: 电流=8.0A, 基准=4.0A, 乘数=0.5, 曲线=E => 跳闸时间=%.6f秒\n", result);

    result = calculate_trip_time(3.0, 4.0, 1.0, 'I');
    printf("测试4: 电流=3.0A, 基准=4.0A, 乘数=1.0, 曲线=I => 跳闸时间=%.6f秒\n", result);

    printf("\n测试完成\n");
    return 0;
}

