    }

    // 写入ADC数据寄存器
    ADC_DR = adc_value;

    // 触发DMA传输
    if (DMA_SxCR & DMA_SxCR_EN) {
        uint32_t remaining = DMA_SxNDTR;
        if (remaining > 0) {
            // DMA自动传输数据到缓冲区
            dma_buffer[TOTAL_SAMPLES - remaining] = ADC_DR;
            DMA_SxNDTR = remaining - 1;

            // 更新通道索引
            current_channel = (current_channel + 1) % ADC_CHANNELS;
            adc_conversion_count++;

            // 检查是否传输完成
            if (remaining == 1) {
                dma_transfer_complete = 1;
            }
        }
    }

    // 清除EOC标志
    ADC_SR &= ~ADC_SR_EOC;
}

// DMA传输完成回调
void dma_transfer_complete_callback(void) {
    printf("\nDMA传输完成！\n");
    printf("总转换次数：%d\n", adc_conversion_count);
    printf("传输数据量：%d\n", TOTAL_SAMPLES);
}

// 启动ADC和DMA
void start_adc_dma(void) {
    // 启动DMA
    DMA_SxCR |= DMA_SxCR_EN;

    // 启动ADC转换
    printf("启动ADC和DMA采集...\n");

    // 模拟连续转换
    for (int i = 0; i < TOTAL_SAMPLES; i++) {
        simulate_adc_conversion_complete();
    }
}

// 打印采样数据
void print_sampled_data(void) {
    printf("\n前5组采样数据（格式：CH0值, CH1值, CH2值）：\n");

    for (int group = 0; group < 5; group++) {
        printf("第%d组: ", group + 1);
        for (int ch = 0; ch < ADC_CHANNELS; ch++) {
            int index = group * ADC_CHANNELS + ch;
            if (index < TOTAL_SAMPLES) {
                printf("%d", dma_buffer[index]);
                if (ch < ADC_CHANNELS - 1) {
                    printf(", ");
                }
            }
        }
        printf("\n");
    }
}

// 打印DMA传输统计
void print_dma_stats(void) {
    printf("\nDMA传输统计信息：\n");
    printf("缓冲区地址：%p\n", (void*)dma_buffer);
    printf("缓冲区大小：%d 字节\n", TOTAL_SAMPLES * sizeof(uint16_t));
    printf("剩余传输数量：%d\n", DMA_SxNDTR);
    printf("DMA控制寄存器状态：0x%08X\n", DMA_SxCR);

    // 计算数据校验
    uint32_t sum = 0;
    for (int i = 0; i < TOTAL_SAMPLES; i++) {
        sum += dma_buffer[i];
    }
    printf("数据校验和：%u\n", sum);
}

int main(void) {
    // 初始化随机数种子
    srand(time(NULL));

    printf("=== STM32 ADC多通道DMA采样模拟程序 ===\n");

    // 初始化ADC和DMA
    adc_init();
    dma_init();

    // 启动采集
    start_adc_dma();

    // 检查传输是否完成
    if (dma_transfer_complete) {
        dma_transfer_complete_callback();
    }

    // 打印采样数据
    print_sampled_data();

    // 打印DMA统计信息
    print_dma_stats();

    printf("\n程序执行完成！\n");

    return 0;
}

#include <stdio.h>

// 故障类型枚举
typedef enum {
    FAULT_NONE = 0,
    FAULT_LIGHT,
    FAULT_HEAVY
} FaultType;

// 传感器正常范围阈值
#define VOLTAGE_MIN 10.0f
#define VOLTAGE_MAX 15.0f
#define VOLTAGE_CRITICAL_MIN 8.0f
#define VOLTAGE_CRITICAL_MAX 18.0f

#define CURRENT_MIN 0.0f
#define CURRENT_MAX 10.0f
#define CURRENT_CRITICAL_MAX 15.0f

#define TEMPERATURE_MIN 0.0f
#define TEMPERATURE_MAX 60.0f
#define TEMPERATURE_CRITICAL_MAX 80.0f

// 故障诊断函数
FaultType diagnose_fault(float voltage, float current, float temperature) {
    int heavy_fault = 0;
    int light_fault = 0;

    // 检查电压
    if (voltage < VOLTAGE_CRITICAL_MIN || voltage > VOLTAGE_CRITICAL_MAX) {
        heavy_fault = 1;
    } else if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
        light_fault = 1;
    }

    // 检查电流
    if (current > CURRENT_CRITICAL_MAX) {
        heavy_fault = 1;
    } else if (current > CURRENT_MAX) {
        light_fault = 1;
    }

    // 检查温度
    if (temperature > TEMPERATURE_CRITICAL_MAX) {
        heavy_fault = 1;
    } else if (temperature > TEMPERATURE_MAX) {
        light_fault = 1;
    }

    // 按重故障优先原则返回
    if (heavy_fault) {
        return FAULT_HEAVY;
    } else if (light_fault) {
        return FAULT_LIGHT;
    } else {
        return FAULT_NONE;
    }
}

// 故障类型转字符串
const char* fault_type_to_string(FaultType type) {
    switch (type) {
        case FAULT_NONE: return "正常";
        case FAULT_LIGHT: return "轻故障";
        case FAULT_HEAVY: return "重故障";
        default: return "未知";
    }
}

