        {7.5f, 12.0f, 85.0f},    // 多重重故障
        {13.5f, 11.0f, 65.0f},   // 电流轻故障+温度轻故障
        {16.5f, 8.0f, 50.0f}     // 电压轻故障
    };

    printf("电力电子变换器故障自诊断系统\n");
    printf("==============================\n");

    for (int i = 0; i < 5; i++) {
        float voltage = test_cases[i][0];
        float current = test_cases[i][1];
        float temperature = test_cases[i][2];

