    double theta1 = 1.0;
    double freq1 = 50.0;
    int delay1 = 2;
    double compensated1 = compensate_phase_delay(theta1, freq1, delay1, T);
    printf("当前相位: %.6f rad, 频率: %.2f Hz, 延迟周期: %d\n", theta1, freq1, delay1);
    printf("补偿后相位: %.6f rad\n\n", compensated1);

    printf("测试用例2: 补偿后超过2π的情况\n");
    double theta2 = 5.5;
    double freq2 = 50.0;
    int delay2 = 5;
    double compensated2 = compensate_phase_delay(theta2, freq2, delay2, T);
    printf("当前相位: %.6f rad, 频率: %.2f Hz, 延迟周期: %d\n", theta2, freq2, delay2);
    printf("补偿后相位: %.6f rad\n\n", compensated2);

    printf("测试用例3: 补偿后为负值的情况（频率为负）\n");
    double theta3 = 1.0;
    double freq3 = -50.0;
    int delay3 = 3;
    double compensated3 = compensate_phase_delay(theta3, freq3, delay3, T);
    printf("当前相位: %.6f rad, 频率: %.2f Hz, 延迟周期: %d\n", theta3, freq3, delay3);
    printf("补偿后相位: %.6f rad\n\n", compensated3);

    printf("测试用例4: 边界情况测试\n");
    double theta4 = 6.28;
    double freq4 = 50.0;
    int delay4 = 1;
    double compensated4 = compensate_phase_delay(theta4, freq4, delay4, T);
    printf("当前相位: %.6f rad (接近2π), 频率: %.2f Hz, 延迟周期: %d\n", theta4, freq4, delay4);
    printf("补偿后相位: %.6f rad\n", compensated4);

    return 0;
}

#include <stdio.h>
#include <math.h>

// 硬件相关宏定义
#define PWM_PERIOD 10000  // 100kHz对应周期计数值
#define ADC_VOLTAGE_RANGE 20.0f  // ADC电压量程0-20V
#define ADC_CURRENT_RANGE 10.0f  // ADC电流量程0-10A

// 控制器参数
#define KP_V 0.5f    // 电压环比例系数
#define KI_V 0.1f    // 电压环积分系数
#define KP_I 0.3f    // 电流环比例系数

// 限幅参数
#define VOLTAGE_INTEGRAL_LIMIT 5.0f    // 电压环积分限幅
#define CURRENT_REF_MIN 0.1f           // 电流参考最小值
#define CURRENT_REF_MAX 5.0f           // 电流参考最大值
#define DUTY_MIN 0.05f                 // 占空比最小值
#define DUTY_MAX 0.95f                 // 占空比最大值

// 控制器状态变量
typedef struct {
    float voltage_integral;    // 电压环积分项
    float current_ref;         // 电流参考值
    float duty_cycle;          // 当前占空比
} BuckBoostController;

static BuckBoostController controller;

// 限幅函数
static float clamp(float value, float min_val, float max_val) {
    if (value < min_val) return min_val;
    if (value > max_val) return max_val;
    return value;
}

// 初始化控制器
void buck_boost_init(void) {
    controller.voltage_integral = 0.0f;
    controller.current_ref = 0.0f;
    controller.duty_cycle = 0.0f;
}

// 电压环PI控制器
float voltage_pi_controller(float v_ref, float v_meas) {
    float error = v_ref - v_meas;

    // 比例项
    float proportional = KP_V * error;

    // 积分项
    controller.voltage_integral += KI_V * error;
    controller.voltage_integral = clamp(controller.voltage_integral, 
                                        -VOLTAGE_INTEGRAL_LIMIT, 
                                        VOLTAGE_INTEGRAL_LIMIT);

    // 计算电流参考值
    float i_ref = proportional + controller.voltage_integral;

    // 电流参考限幅
    controller.current_ref = clamp(i_ref, CURRENT_REF_MIN, CURRENT_REF_MAX);

    return controller.current_ref;
}

// 电流环P控制器
float current_p_controller(float i_ref, float i_meas) {
    float error = i_ref - i_meas;
    float duty = controller.duty_cycle + KP_I * error;

    // 占空比限幅
    controller.duty_cycle = clamp(duty, DUTY_MIN, DUTY_MAX);

    return controller.duty_cycle;
}

// 更新PWM占空比（模拟函数）
void update_pwm_duty(float duty) {
    // 模拟更新PWM寄存器
    int pwm_value = (int)(duty * PWM_PERIOD);
    // 这里只是模拟，实际硬件会更新PWM寄存器
    (void)pwm_value; // 避免未使用变量警告
}

int main(void) {
    // 初始化控制器
    buck_boost_init();

    // 参考电压
    float v_ref = 12.0f;

    // 模拟测量值初始化
    float v_meas = 10.0f;  // 初始电压
    float i_meas = 1.0f;   // 初始电流

    printf("Buck-Boost变换器双环控制仿真\n");
    printf("周期\tVref(V)\tVmeas(V)\tImeas(A)\tIref(A)\tDuty\n");
    printf("------------------------------------------------------------\n");

    // 模拟5个控制周期
    for (int cycle = 1; cycle <= 5; cycle++) {
        // 电压环PI控制器计算电流参考值
        float i_ref = voltage_pi_controller(v_ref, v_meas);

        // 电流环P控制器计算占空比
        float duty = current_p_controller(i_ref, i_meas);

        // 更新PWM占空比
        update_pwm_duty(duty);

        // 打印当前周期结果
        printf("%d\t%.2f\t%.2f\t\t%.2f\t\t%.2f\t%.3f\n", 
               cycle, v_ref, v_meas, i_meas, i_ref, duty);

        // 模拟下一个周期的测量值变化
        v_meas += 0.5f;  // 每个周期电压增加0.5V
        i_meas += 0.2f;  // 每个周期电流增加0.2A
    }

    return 0;
}

#include <stdint.h>
#include <stdio.h>

#define TRIGGER_RISING  0
#define TRIGGER_FALLING 1
#define TRIGGER_BOTH    2

typedef struct {
    uint32_t IDR;  // 输入数据寄存器
    uint32_t CRL;  // 配置寄存器低
    uint32_t IMR;  // 中断屏蔽寄存器
    uint32_t PR;   // 中断挂起寄存器
} GPIO_TypeDef;

static uint32_t last_level = 0;
static uint32_t debounce_count = 0;
static uint32_t debounce_target = 0;
static uint32_t trigger_edge = 0;

void GPIO_Init(GPIO_TypeDef* GPIOx, uint32_t trigger_edge_config) {
    GPIOx->IDR = 0;
    GPIOx->CRL = trigger_edge_config;
    GPIOx->IMR = 1;  // 使能中断
    GPIOx->PR = 0;
    trigger_edge = trigger_edge_config;
    last_level = 0;
    debounce_count = 0;
    debounce_target = 0;
}

void GPIO_InterruptHandler(GPIO_TypeDef* GPIOx, uint32_t current_level) {
    GPIOx->IDR = current_level;

    uint32_t edge_detected = 0;
    uint32_t rising_edge = (last_level == 0 && current_level == 1);
    uint32_t falling_edge = (last_level == 1 && current_level == 0);

    if (trigger_edge == TRIGGER_RISING && rising_edge) {
        edge_detected = 1;
    } else if (trigger_edge == TRIGGER_FALLING && falling_edge) {
        edge_detected = 1;
    } else if (trigger_edge == TRIGGER_BOTH && (rising_edge || falling_edge)) {
        edge_detected = 1;
    }

    if (edge_detected) {
        if (debounce_count == 0) {
            debounce_target = current_level;
            debounce_count = 1;
            printf("采样值:%u | PR:%u | 状态:防抖计数中(1/3)\n", current_level, GPIOx->PR);
        } else if (current_level == debounce_target) {
            debounce_count++;
            if (debounce_count < 3) {
                printf("采样值:%u | PR:%u | 状态:防抖计数中(%u/3)\n", current_level, GPIOx->PR, debounce_count);
            } else {
                GPIOx->PR = 1;
                if (rising_edge) {
                    printf("采样值:%u | PR:%u | 状态:↑上升沿中断触发\n", current_level, GPIOx->PR);
                } else {
                    printf("采样值:%u | PR:%u | 状态:↓下降沿中断触发\n", current_level, GPIOx->PR);
                }
                debounce_count = 0;
            }
        } else {
            debounce_count = 0;
            printf("采样值:%u | PR:%u | 状态:防抖失败，重新检测\n", current_level, GPIOx->PR);
        }
    } else {
        if (debounce_count > 0 && current_level != debounce_target) {
            debounce_count = 0;
            printf("采样值:%u | PR:%u | 状态:防抖中断，重新检测\n", current_level, GPIOx->PR);
        } else if (debounce_count > 0) {
            printf("采样值:%u | PR:%u | 状态:电平稳定，继续防抖\n", current_level, GPIOx->PR);
        } else {
            printf("采样值:%u | PR:%u | 状态:无边沿变化\n", current_level, GPIOx->PR);
        }
    }

    last_level = current_level;
}

int main() {
    GPIO_TypeDef GPIOA;

    GPIO_Init(&GPIOA, TRIGGER_RISING);

    uint32_t test_sequence[] = {0, 0, 1, 1, 1, 0, 1, 0, 0, 1};
    uint32_t sequence_length = sizeof(test_sequence) / sizeof(test_sequence[0]);

    printf("GPIO中断防抖模拟测试（上升沿触发）\n");
    printf("==================================\n");

    for (uint32_t i = 0; i < sequence_length; i++) {
        GPIO_InterruptHandler(&GPIOA, test_sequence[i]);
    }

    printf("==================================\n");
    printf("测试完成\n");

    return 0;
}

#include <stdio.h>
#include <math.h>

#define Kp 0.05
#define Ki 0.001
#define DUTY_MAX 0.95
#define DUTY_MIN 0.0

double buck_control(double Vref, double Vin, double Vout, double Iload, double* integral_err) {
    double error = Vref - Vout;

    double D_ff = Vref / Vin;

    double D_fb = Kp * error + Ki * (*integral_err);

    *integral_err += error;

    double D = D_ff + D_fb;

    if (D > DUTY_MAX) {
        D = DUTY_MAX;
    } else if (D < DUTY_MIN) {
        D = DUTY_MIN;
    }

    return D;
}

int main() {
    printf("=== Buck变换器动态响应优化控制算法测试 ===\n\n");

    double integral_err = 0.0;

    printf("=== 稳态测试 ===\n");
    double Vin = 12.0;
    double Vref = 5.0;
    double Vout = 4.95;
    double Iload = 1.0;

    for (int i = 0; i < 5; i++) {
        double D = buck_control(Vref, Vin, Vout, Iload, &integral_err);
        printf("Step %d: Vout=%.2fV, D=%.4f\n", i+1, Vout, D);
        Vout += 0.01;
    }

    printf("\n=== 输入电压突变测试 ===\n");
    integral_err = 0.0;
    Vin = 12.0;
    Vref = 5.0;
    Vout = 5.0;
    Iload = 1.0;

    double D_before = buck_control(Vref, Vin, Vout, Iload, &integral_err);
    printf("Before: Vin=%.1fV, D=%.4f\n", Vin, D_before);

    Vin = 15.0;
    double D_after = buck_control(Vref, Vin, Vout, Iload, &integral_err);
    printf("After:  Vin=%.1fV, D=%.4f\n", Vin, D_after);

    printf("\n=== 负载突变测试 ===\n");
    integral_err = 0.0;
    Vin = 12.0;
    Vref = 5.0;
    Vout = 5.0;
    Iload = 1.0;

    D_before = buck_control(Vref, Vin, Vout, Iload, &integral_err);
    printf("Before: Iload=%.1fA, D=%.4f\n", Iload, D_before);

    Iload = 2.0;
    D_after = buck_control(Vref, Vin, Vout, Iload, &integral_err);
    printf("After:  Iload=%.1fA, D=%.4f\n", Iload, D_after);

    return 0;
}
